fn json_type_name(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "boolean",
        Value::Number(_) => "number",
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

/// A project.json carries its version either as a semver string or, in
/// pre-semver and native fixtures, as a bare integer revision counter. Integers
/// carry no field layout, so they take the additive fill path and are reported
/// as migratable instead of rejected — the same rule the shell applies.
fn schema_version_state(value: Option<&Value>) -> &'static str {
    match value {
        None | Some(Value::Null) => "absent",
        Some(Value::Number(number)) => match number.as_f64() {
            Some(float) if float.fract() == 0.0 && float >= 0.0 => "migratable",
            _ => "unsupported",
        },
        Some(Value::String(text)) => {
            let trimmed = text.trim();
            if trimmed.is_empty() {
                return "absent";
            }
            let body = trimmed
                .strip_prefix('v')
                .or_else(|| trimmed.strip_prefix('V'))
                .unwrap_or(trimmed);
            let parts: Vec<&str> = body.split('.').collect();
            if parts.is_empty()
                || parts.len() > 4
                || parts
                    .iter()
                    .any(|part| part.is_empty() || !part.chars().all(|c| c.is_ascii_digit()))
            {
                return "unsupported";
            }
            let current: Vec<u64> = CURRENT_PROJECT_SCHEMA_VERSION
                .split('.')
                .map(|part| part.parse().unwrap_or(0))
                .collect();
            let parsed: Vec<u64> = parts
                .iter()
                .map(|part| part.parse::<u64>().unwrap_or(0))
                .collect();
            let mut diff = 0i64;
            for index in 0..current.len() {
                diff = parsed.get(index).copied().unwrap_or(0) as i64 - current[index] as i64;
                if diff != 0 {
                    break;
                }
            }
            if diff == 0 {
                diff = parsed.len() as i64 - current.len() as i64;
            }
            match diff.cmp(&0) {
                std::cmp::Ordering::Equal => "current",
                std::cmp::Ordering::Less => "migratable",
                std::cmp::Ordering::Greater => "unsupported",
            }
        }
        _ => "unsupported",
    }
}

fn project_file_schema_state(root: Option<&Value>, nested: Option<&Value>) -> &'static str {
    let states = [schema_version_state(root), schema_version_state(nested)];
    if states.contains(&"unsupported") {
        return "unsupported";
    }
    if states.iter().all(|state| *state == "current") {
        return "current";
    }
    if states.iter().all(|state| *state == "absent") {
        return "absent";
    }
    "migratable"
}

fn inspection_problem(
    code: &str,
    path: &str,
    message: &str,
    expected: &str,
    actual: &str,
) -> Value {
    json!({
        "code": code,
        "path": path,
        "message": message,
        "expected": expected,
        "actual": actual,
    })
}

fn inspection_result(
    status: &str,
    schema_version: Value,
    problem: Option<Value>,
    project: Option<Value>,
) -> Value {
    json!({
        "status": status,
        "schema_version": schema_version,
        "supported_schema_version": CURRENT_PROJECT_SCHEMA_VERSION,
        "problem": problem.unwrap_or(Value::Null),
        "project": project.unwrap_or(Value::Null),
    })
}

fn project_unreadable(code: &str, path: &str, message: String, actual: &str) -> Value {
    inspection_result(
        "unreadable",
        Value::Null,
        Some(inspection_problem(
            code,
            path,
            &message,
            "可读的项目目录中的 project.json",
            actual,
        )),
        None,
    )
}

fn no_project_json_result() -> Value {
    inspection_result(
        "no_project_json",
        Value::Null,
        Some(inspection_problem(
            "project_json_missing",
            PROJECT_JSON_LABEL,
            "这个文件夹里还没有 project.json，因此它还不是 Workbench 项目。你可以把它作为已有文件夹导入。",
            "所选文件夹根目录中存在 project.json",
            "project.json 不存在",
        )),
        None,
    )
}

fn invalid_json_result(actual: &str) -> Value {
    inspection_result(
        "malformed_json",
        Value::Null,
        Some(inspection_problem(
            "malformed_json",
            PROJECT_JSON_LABEL,
            "project.json 存在，但内容无法解析，文件可能已损坏。",
            "可解析的 JSON 对象",
            actual,
        )),
        None,
    )
}

/// Focused canonical check used to classify a folder for the launcher.
///
/// Deliberate scope boundary: this is NOT the persistence validator. It covers
/// only what routing needs — root shape, project identity, schema range,
/// collection shapes, item identity/uniqueness and the parent/child references
/// between the primary collections. `src/domain/store.ts::validateProjectData`
/// stays the authoritative validator for saves, and `inspectProjectData` there
/// mirrors this function code-for-code.
fn inspect_project_value(parsed: &Value) -> Value {
    let object = match parsed.as_object() {
        Some(object) => object,
        None => {
            return inspection_result(
                "invalid",
                Value::Null,
                Some(inspection_problem(
                    "invalid_root",
                    "",
                    "project.json 的顶层内容不是课程项目对象。",
                    "JSON 对象",
                    &format!("{} 类型", json_type_name(parsed)),
                )),
                None,
            )
        }
    };
    let raw_version = object
        .get("schema_version")
        .filter(|value| value.is_string() || value.is_number())
        .cloned()
        .unwrap_or(Value::Null);
    let invalid =
        |problem: Value| inspection_result("invalid", raw_version.clone(), Some(problem), None);
    let project = match object.get("project").and_then(Value::as_object) {
        Some(project) => project.clone(),
        None => {
            let actual = match object.get("project") {
                None => "project 字段不存在".to_string(),
                Some(value) => format!("project 字段为 {}，不是对象", json_type_name(value)),
            };
            return invalid(inspection_problem(
                "missing_project",
                "project",
                "project.json 存在，但其中没有 course 项目对象。",
                "project 对象，包含非空字符串 id 和 title",
                &actual,
            ));
        }
    };
    let project_id = project
        .get("id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("")
        .to_string();
    if project_id.is_empty() {
        let actual = match project.get("id") {
            None => "project.id 为 undefined".to_string(),
            Some(value) => format!("project.id 为 {}", json_type_name(value)),
        };
        return invalid(inspection_problem(
            "missing_project",
            "project.id",
            "project.json 存在，但项目缺少有效 id。",
            "project.id 为非空字符串",
            &actual,
        ));
    }
    let title = match project.get("title") {
        None | Some(Value::Null) => {
            return invalid(inspection_problem(
                "missing_project_title",
                "project.title",
                "project.json 存在，但项目缺少标题。",
                "project.title 为非空字符串",
                "project.title 字段不存在",
            ))
        }
        Some(Value::String(text)) if text.trim().is_empty() => {
            return invalid(inspection_problem(
                "missing_project_title",
                "project.title",
                "project.json 存在，但项目缺少标题。",
                "project.title 为非空字符串",
                "project.title 为空字符串",
            ))
        }
        Some(Value::String(text)) => text.trim().to_string(),
        Some(other) => {
            return invalid(inspection_problem(
                "invalid_title",
                "project.title",
                "project.json 存在，但项目缺少标题。",
                "project.title 为非空字符串",
                &format!("project.title 为 {}", json_type_name(other)),
            ))
        }
    };

    let version_state =
        project_file_schema_state(object.get("schema_version"), project.get("schema_version"));
    if version_state == "unsupported" {
        let found = object
            .get("schema_version")
            .or_else(|| project.get("schema_version"))
            .map(|value| value.to_string())
            .unwrap_or_default();
        return invalid(inspection_problem(
            "unsupported_schema",
            "schema_version",
            "这个 project.json 的版本比当前工作台更新，打开会损坏内容。请升级工作台后重试。",
            &format!("不高于 {} 的版本", CURRENT_PROJECT_SCHEMA_VERSION),
            &found,
        ));
    }

    let mut arrays: HashMap<&str, &Vec<Value>> = HashMap::new();
    for key in CANONICAL_ARRAY_KEYS {
        let Some(value) = object.get(key) else {
            continue;
        };
        match value.as_array() {
            Some(items) => {
                arrays.insert(key, items);
            }
            None => {
                return invalid(inspection_problem(
                    "invalid_collection",
                    key,
                    &format!("项目字段 {key} 无法读取，导入流程已停止。"),
                    &format!("{key} 为数组"),
                    &format!("{key} 为 {}", json_type_name(value)),
                ))
            }
        }
    }

    let mut identities: HashMap<String, &str> = HashMap::new();
    for key in CANONICAL_ARRAY_KEYS {
        let Some(items) = arrays.get(key) else {
            continue;
        };
        for (index, item) in items.iter().enumerate() {
            let Some(item) = item.as_object() else {
                return invalid(inspection_problem(
                    "invalid_id",
                    &format!("{key}[{index}].id"),
                    &format!("{key} 中有一项不是对象，无法识别身份。"),
                    "每项必须是包含非空 id 的对象",
                    &format!("{key}[{index}] 为 {}", json_type_name(item)),
                ));
            };
            let id = match item.get("id").and_then(Value::as_str) {
                Some(value) => value.trim().to_string(),
                None => String::new(),
            };
            if id.is_empty() {
                let actual = match item.get("id") {
                    None => "id 为 undefined".to_string(),
                    Some(value) => format!("id 为 {}", json_type_name(value)),
                };
                return invalid(inspection_problem(
                    "invalid_id",
                    &format!("{key}[{index}].id"),
                    &format!("{key} 中有一项缺少 id。"),
                    "每项必须有非空字符串 id",
                    &actual,
                ));
            }
            if let Some(previous) = identities.get(&id) {
                let code = if *previous == key {
                    "duplicate_id"
                } else {
                    "duplicate_global_id"
                };
                return invalid(inspection_problem(
                    code,
                    &format!("{key}[{index}].id"),
                    &format!("{key} 中出现重复 id，导入流程已停止。"),
                    "每个 id 在项目内唯一",
                    &format!("id {id} 已在 {previous} 中使用"),
                ));
            }
            identities.insert(id, key);
        }
    }

    let mut maps: HashMap<&str, HashMap<String, Map<String, Value>>> = HashMap::new();
    for key in CANONICAL_ARRAY_KEYS {
        let Some(items) = arrays.get(key) else {
            continue;
        };
        let mut map: HashMap<String, Map<String, Value>> = HashMap::new();
        for item in items.iter().filter_map(Value::as_object) {
            if let Some(id) = item.get("id").and_then(Value::as_str) {
                let id = id.trim().to_string();
                if !id.is_empty() {
                    map.insert(id, item.clone());
                }
            }
        }
        maps.insert(key, map);
    }
    for rule in INSPECTION_REFERENCES {
        let Some(items) = arrays.get(rule.collection) else {
            continue;
        };
        let Some(target) = maps.get(rule.target) else {
            continue;
        };
        for (index, item) in items.iter().enumerate() {
            let Some(item) = item.as_object() else {
                continue;
            };
            let path = format!("{}[{}].{}", rule.collection, index, rule.field);
            let referenced = item.get(rule.field);
            let item_id = item.get("id").and_then(Value::as_str).unwrap_or("");
            match referenced {
                None | Some(Value::Null) if rule.nullable => continue,
                None | Some(Value::Null) => {
                    return invalid(inspection_problem(
                        "invalid_reference",
                        &path,
                        &format!(
                            "{}（{} 第 {} 项）。",
                            rule.message,
                            rule.collection,
                            index + 1
                        ),
                        "必填引用指向已存在的对象",
                        &format!("{} 未设置", rule.field),
                    ))
                }
                Some(value) => {
                    let referenced_id = value.as_str().map(str::trim).unwrap_or("");
                    if referenced_id == item_id && !referenced_id.is_empty() {
                        return invalid(inspection_problem(
                            "cycle",
                            &path,
                            &format!("{} 中存在自引用的父级。", rule.collection),
                            "父级引用指向其他对象",
                            &format!("id 与父级引用相同：{referenced_id}"),
                        ));
                    }
                    if referenced_id.is_empty() || !target.contains_key(referenced_id) {
                        return invalid(inspection_problem(
                            "invalid_reference",
                            &path,
                            &format!(
                                "{}（{} 第 {} 项）。",
                                rule.message,
                                rule.collection,
                                index + 1
                            ),
                            "引用指向已存在的对象 id",
                            &format!("引用值为 {}，目标集合中不存在", json_type_name(value)),
                        ));
                    }
                }
            }
        }
    }

    inspection_result(
        if version_state == "current" {
            "valid"
        } else {
            "migratable"
        },
        raw_version,
        None,
        Some(json!({ "id": project_id, "title": title })),
    )
}

/// Pure, side-effect-free classification of a candidate project folder. Never
/// takes the project lock, never creates project.json, never mutates the folder.
fn inspect_project_directory(directory: &Path) -> Value {
    let shown = directory.to_string_lossy().to_string();
    let meta = match fs::symlink_metadata(directory) {
        Ok(meta) => meta,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return project_unreadable(
                "missing_directory",
                "",
                "项目目录不存在，可能已被移动或删除。".into(),
                &format!("{shown} 不存在"),
            )
        }
        Err(error) => {
            return project_unreadable(
                "io_error",
                "",
                format!("无法检查项目目录：{error}"),
                &error.to_string(),
            )
        }
    };
    if meta.file_type().is_symlink() {
        return project_unreadable(
            "symlink_path",
            "",
            "为避免越过目录边界，项目目录不能是符号链接。".into(),
            &format!("{shown} 是符号链接"),
        );
    }
    if !meta.is_dir() {
        return project_unreadable(
            "not_a_directory",
            "",
            "打开项目需要选择一个文件夹，而不是单个文件。".into(),
            &format!("{shown} 不是目录"),
        );
    }
    let path = directory.join(PROJECT_JSON_LABEL);
    match fs::symlink_metadata(&path) {
        Ok(meta) if meta.file_type().is_symlink() => {
            return project_unreadable(
                "symlink_path",
                PROJECT_JSON_LABEL,
                "为避免越过目录边界，project.json 不能是符号链接。".into(),
                "project.json 是符号链接",
            )
        }
        Ok(meta) if !meta.is_file() => {
            return project_unreadable(
                "not_a_file",
                PROJECT_JSON_LABEL,
                "project.json 不是一个普通文件。".into(),
                "project.json 不是文件",
            )
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return no_project_json_result()
        }
        Err(error) => {
            return project_unreadable(
                "io_error",
                PROJECT_JSON_LABEL,
                format!("无法读取 project.json：{error}"),
                &error.to_string(),
            )
        }
        Ok(_) => {}
    }
    let contents = match fs::read(&path) {
        Ok(contents) => contents,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return no_project_json_result()
        }
        Err(error) if error.kind() == std::io::ErrorKind::PermissionDenied => {
            return project_unreadable(
                "permission_denied",
                PROJECT_JSON_LABEL,
                format!("无法读取 project.json：{error}"),
                &error.to_string(),
            )
        }
        Err(error) => {
            return project_unreadable(
                "io_error",
                PROJECT_JSON_LABEL,
                format!("无法读取 project.json：{error}"),
                &error.to_string(),
            )
        }
    };
    match serde_json::from_slice::<Value>(&contents) {
        Ok(parsed) => inspect_project_value(&parsed),
        Err(error) => invalid_json_result(&error.to_string()),
    }
}

/// Problems that stop a folder from opening at all. The remaining `invalid`
/// codes stay openable on purpose: the shell's own migration repairs them, so
/// refusing to open would lock users out of recoverable data. Corrupt JSON has
/// its own `malformed_json` status and is blocked directly, not listed here.
const PROJECT_OPEN_BLOCKING_CODES: [&str; 5] = [
    "invalid_root",
    "missing_project",
    "missing_project_title",
    "invalid_title",
    "unsupported_schema",
];

fn project_open_legacy_failure(error: &str) -> Option<Value> {
    let message = error.to_string();
    if message.starts_with("项目 JSON 无效") {
        return Some(invalid_json_result(&message));
    }
    if message == "项目数据必须是 JSON 对象" {
        return Some(inspection_result(
            "invalid",
            Value::Null,
            Some(inspection_problem(
                "invalid_root",
                "",
                "project.json 的顶层内容不是课程项目对象。",
                "JSON 对象",
                &message,
            )),
            None,
        ));
    }
    if message == "项目目录中没有 project.json" {
        return Some(no_project_json_result());
    }
    if message.starts_with("无法读取项目文件") {
        let code = if message.contains("PermissionDenied") || message.contains("permission denied")
        {
            "permission_denied"
        } else {
            "io_error"
        };
        return Some(project_unreadable(
            code,
            PROJECT_JSON_LABEL,
            message.clone(),
            &message,
        ));
    }
    if message == "项目文件不能是符号链接" {
        return Some(project_unreadable(
            "symlink_path",
            PROJECT_JSON_LABEL,
            message.clone(),
            &message,
        ));
    }
    if message == "项目数据不得包含凭据或本机私有字段" {
        return Some(inspection_result(
            "invalid",
            Value::Null,
            Some(inspection_problem(
                "sensitive_fields",
                "",
                &message,
                "不含凭据或本机私有字段的项目数据",
                &message,
            )),
            None,
        ));
    }
    None
}

#[tauri::command]
fn project_inspect(path: String) -> Result<Value, String> {
    let raw = path.trim();
    if raw.is_empty() || !Path::new(raw).is_absolute() {
        return Err("项目目录必须是用户明确选择的绝对路径".into());
    }
    Ok(inspect_project_directory(Path::new(raw)))
}

enum ProjectOpenOutcome {
    Inspection(Value),
    Opened {
        project: Value,
        fingerprint: FileFingerprint,
        project_id: String,
        lease_generation: String,
    },
}

fn project_open_inner(project_dir: String) -> Result<Option<ProjectOpenOutcome>, String> {
    let requested = project_dir.trim().to_string();
    let project_dir = match explicit_project_dir(&project_dir, false) {
        Ok(dir) => dir,
        // A folder that is simply gone is a classification, not an opaque error.
        Err(error) if error == "项目目录不存在" => {
            return Ok(Some(ProjectOpenOutcome::Inspection(
                inspect_project_directory(Path::new(&requested)),
            )))
        }
        Err(error) => return Err(error),
    };
    let already_open = project_lock_registered(&project_dir, current_app_instance_id());
    acquire_project_lock(&project_dir)?;
    let release_if_new = || {
        if !already_open {
            let _ = release_project_lock(&project_dir);
        }
    };
    let inspection = inspect_project_directory(&project_dir);
    let blocking = match inspection.get("status").and_then(Value::as_str) {
        Some("no_project_json") | Some("unreadable") | Some("malformed_json") => true,
        Some("invalid") => {
            let code = inspection
                .get("problem")
                .and_then(|problem| problem.get("code"))
                .and_then(Value::as_str)
                .unwrap_or("");
            PROJECT_OPEN_BLOCKING_CODES.contains(&code)
        }
        _ => false,
    };
    if blocking {
        release_if_new();
        return Ok(Some(ProjectOpenOutcome::Inspection(inspection)));
    }
    let path = match project_file(&project_dir, "project.json") {
        Ok(path) => path,
        Err(error) => {
            release_if_new();
            return Err(error);
        }
    };
    if !path.exists() {
        release_if_new();
        return Ok(Some(ProjectOpenOutcome::Inspection(
            no_project_json_result(),
        )));
    }
    match read_project_state(&project_dir) {
        Ok((project, fingerprint)) => {
            if let Err(error) =
                store_project_baseline(&project_dir, fingerprint.clone(), Some(project.clone()))
            {
                release_if_new();
                return Err(error);
            }
            let (project_id, lease_generation) =
                match project_id_of(&project).and_then(|project_id| {
                    active_lease_generation(&project_dir)
                        .map(|lease_generation| (project_id, lease_generation))
                }) {
                    Ok(identity) => identity,
                    Err(error) => {
                        release_if_new();
                        return Err(error);
                    }
                };
            Ok(Some(ProjectOpenOutcome::Opened {
                project,
                fingerprint,
                project_id,
                lease_generation,
            }))
        }
        Err(error) => {
            release_if_new();
            match project_open_legacy_failure(&error) {
                Some(failure) => Ok(Some(ProjectOpenOutcome::Inspection(failure))),
                // Genuinely unexpected failures keep the 无法打开项目 fallback.
                None => Err(error),
            }
        }
    }
}

#[tauri::command]
fn project_open(project_dir: String) -> Result<Option<Value>, String> {
    Ok(
        project_open_inner(project_dir)?.map(|outcome| match outcome {
            ProjectOpenOutcome::Inspection(value) => value,
            ProjectOpenOutcome::Opened { project, .. } => project,
        }),
    )
}

#[tauri::command]
fn project_open_state(project_dir: String) -> Result<Option<Value>, String> {
    Ok(
        project_open_inner(project_dir.clone())?.map(|outcome| match outcome {
            ProjectOpenOutcome::Inspection(value) => value,
            ProjectOpenOutcome::Opened {
                project,
                fingerprint,
                project_id,
                lease_generation,
            } => {
                let mut state = json!({
                    "project": project,
                    "fingerprint": fingerprint,
                    "project_id": project_id,
                    "lease_generation": lease_generation,
                });
                // Reuse the just-parsed canonical project so native startup
                // can filter a post-commit journal without reopening project.json.
                if let Ok(project_dir) = explicit_project_dir(&project_dir, false) {
                    if let Ok(recovery_journal) = read_recovery_journal_with_canonical_context(
                        &project_dir,
                        state.get("project"),
                    ) {
                        state["recovery_journal"] = json!(recovery_journal);
                    }
                }
                state
            }
        }),
    )
}

#[tauri::command]
fn project_read_state(project_dir: String) -> Result<Option<Value>, String> {
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let path = project_file(&project_dir, "project.json")?;
    if !path.exists() {
        return Ok(None);
    }
    let (project, fingerprint) = read_project_state(&project_dir)?;
    let project_id = project_id_of(&project)?;
    Ok(Some(json!({
        "project": project,
        "fingerprint": fingerprint,
        "project_id": project_id,
    })))
}

#[tauri::command]
fn project_lease_status(project_dir: String) -> Result<Value, String> {
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let directory =
        fs::canonicalize(&project_dir).map_err(|error| format!("无法解析项目目录: {error}"))?;
    let handle = active_project_locks()
        .lock()
        .unwrap()
        .get(&directory)
        .cloned();
    let Some(handle) = handle.filter(|handle| {
        handle.app_instance_id == current_app_instance_id() && !handle.stop.load(Ordering::Acquire)
    }) else {
        return Ok(json!({
            "state": "lost",
            "lease_generation": Value::Null,
            "retry_count": 0,
            "last_error": project_lock_lost_error(),
        }));
    };
    let health = handle.health.lock().unwrap().clone();
    Ok(json!({
        "state": health.state,
        "lease_generation": handle.generation,
        "retry_count": health.retry_count,
        "last_error": health.last_error,
    }))
}

/// Compatibility name for the browser shell. It still requires an explicit
/// project directory; it never falls back to app-local-data.
#[tauri::command]
fn read_project(project_dir: String) -> Result<Option<Value>, String> {
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let path = project_file(&project_dir, "project.json")?;
    if !path.exists() {
        return Ok(None);
    }
    Ok(Some(read_project_value(&project_dir)?))
}

fn project_save_error_contract(
    message: &str,
    stage: &str,
    retryable: bool,
    fingerprint: Option<&FileFingerprint>,
) -> String {
    project_save_error_contract_with_state(message, stage, retryable, "not_committed", fingerprint)
}

fn project_save_error_contract_with_state(
    message: &str,
    stage: &str,
    retryable: bool,
    commit_state: &str,
    fingerprint: Option<&FileFingerprint>,
) -> String {
    let mut root = serde_json::from_str::<Value>(message).unwrap_or(Value::Null);
    let mut error = root
        .get("error")
        .filter(|value| value.is_object())
        .cloned()
        .unwrap_or_else(|| json!({}));
    let code = error
        .get("code")
        .and_then(Value::as_str)
        .map(ToOwned::to_owned)
        .or_else(|| message.split_once(':').map(|(code, _)| code.to_owned()))
        .unwrap_or_else(|| "project_save_failed".into());
    let text = error
        .get("message")
        .or_else(|| error.get("user_message"))
        .or_else(|| error.get("technical_message"))
        .and_then(Value::as_str)
        .map(ToOwned::to_owned)
        .unwrap_or_else(|| message.to_owned());
    error["code"] = json!(code);
    error["message"] = json!(text);
    error["commit_state"] = json!(commit_state);
    error["stage"] = json!(stage);
    error["retryable"] = json!(retryable);
    if let Some(fingerprint) = fingerprint {
        error["fingerprint"] = json!(fingerprint);
    }
    if !root.is_object() {
        root = json!({});
    }
    root["error"] = error;
    root.to_string()
}

fn project_save_atomic_error_contract(
    failure: &AtomicWriteFailure,
    operation_id: Option<&str>,
    revision: Option<u64>,
    current_fingerprint: Option<&FileFingerprint>,
    expected_committed_fingerprint: Option<&FileFingerprint>,
) -> String {
    let mut root = serde_json::from_str::<Value>(&project_save_error_contract_with_state(
        &failure.message,
        failure.stage,
        failure.retryable,
        failure.commit_state,
        current_fingerprint,
    ))
    .unwrap_or_else(|_| json!({}));
    if !root.is_object() {
        root = json!({});
    }
    if !root.get("error").is_some_and(Value::is_object) {
        root["error"] = json!({});
    }
    let error = &mut root["error"];
    if let Some(operation_id) = operation_id {
        error["operation_id"] = json!(operation_id);
    }
    if let Some(revision) = revision {
        error["revision"] = json!(revision);
    }
    if failure.commit_state == "outcome_uncertain" {
        if let Some(fingerprint) =
            expected_committed_fingerprint.or(failure.expected_committed_fingerprint.as_ref())
        {
            error["expected_committed_fingerprint"] = json!(fingerprint);
        }
    }
    root.to_string()
}

#[cfg(test)]
fn fail_atomic_write_for_test(target: &Path, stage: &str) {
    let normalized_target = target
        .parent()
        .and_then(|parent| fs::canonicalize(parent).ok())
        .and_then(|parent| target.file_name().map(|name| parent.join(name)))
        .unwrap_or_else(|| target.to_path_buf());
    ATOMIC_WRITE_FAIL_STAGE
        .get_or_init(|| Mutex::new(HashSet::new()))
        .lock()
        .unwrap()
        .insert((normalized_target, stage.to_owned()));
}

#[tauri::command]
fn project_save(
    project_dir: String,
    expected_fingerprint: FileFingerprint,
    recovery_journal: Option<Value>,
    project: Value,
    expected_project_id: Option<String>,
    lease_generation: Option<String>,
    editor_generation: Option<u64>,
    operation_id: Option<String>,
    revision: Option<u64>,
    recovery_metadata: Option<Value>,
) -> Result<Value, String> {
    let project_dir = explicit_project_dir(&project_dir, false)
        .map_err(|error| project_save_error_contract(&error, "project_path", false, None))?;
    let _lease_guard = require_active_project_lock(&project_dir)
        .map_err(|error| project_save_error_contract(&error, "lease_validate", false, None))?;
    let active_generation = verify_lease_generation(&project_dir, lease_generation.as_deref())
        .map_err(|error| project_save_error_contract(&error, "lease_validate", false, None))?;

    // One project read supplies both the parsed value and the CAS fingerprint.
    let (current_project, current_fingerprint) = read_project_state(&project_dir)
        .map_err(|error| project_save_error_contract(&error, "project_read", false, None))?;
    if fingerprints_differ(&expected_fingerprint, &current_fingerprint) {
        let error = external_conflict_error(Some(&expected_fingerprint), &current_fingerprint);
        return Err(project_save_error_contract(
            &error,
            "fingerprint_preflight",
            false,
            Some(&current_fingerprint),
        ));
    }
    let baseline = project_baselines()
        .lock()
        .unwrap()
        .get(&project_dir)
        .map(|baseline| baseline.fingerprint.clone());
    if baseline
        .as_ref()
        .map(|fingerprint| fingerprints_differ(fingerprint, &current_fingerprint))
        .unwrap_or(current_fingerprint.exists)
    {
        let error = external_conflict_error(baseline.as_ref(), &current_fingerprint);
        return Err(project_save_error_contract(
            &error,
            "baseline_preflight",
            false,
            Some(&current_fingerprint),
        ));
    }

    validate_project(&project).map_err(|error| {
        project_save_error_contract(
            &error,
            "payload_validate",
            false,
            Some(&current_fingerprint),
        )
    })?;
    let current_project_id = project_id_of(&current_project).map_err(|error| {
        project_save_error_contract(
            &error,
            "project_identity",
            false,
            Some(&current_fingerprint),
        )
    })?;
    let requested_project_id = expected_project_id
        .as_deref()
        .unwrap_or(&current_project_id);
    if requested_project_id != current_project_id
        || project_id_of(&project).ok().as_deref() != Some(requested_project_id)
    {
        let error = json!({ "error": {
            "code": "project_id_mismatch",
            "message": "保存请求与当前项目身份不匹配。",
        }})
        .to_string();
        return Err(project_save_error_contract(
            &error,
            "project_identity",
            false,
            Some(&current_fingerprint),
        ));
    }
    if operation_id
        .as_deref()
        .is_some_and(|value| !valid_snapshot_id(value))
    {
        let error = json!({ "error": {
            "code": "invalid_operation_id",
            "message": "保存操作编号无效。",
        }})
        .to_string();
        return Err(project_save_error_contract(
            &error,
            "operation_validate",
            false,
            Some(&current_fingerprint),
        ));
    }

    if let Some(metadata) = recovery_metadata.as_ref() {
        reject_sensitive(metadata).map_err(|error| {
            project_save_error_contract(
                &error,
                "recovery_validate",
                false,
                Some(&current_fingerprint),
            )
        })?;
        let metadata_project_id = metadata.get("project_id").and_then(Value::as_str);
        let canonical_revision = metadata.get("canonical_revision").and_then(Value::as_str);
        let current_revision = project
            .get("project")
            .and_then(|value| value.get("updated_at"))
            .and_then(Value::as_str);
        if metadata_project_id.is_some_and(|value| value != current_project_id)
            || canonical_revision.is_some_and(|value| Some(value) != current_revision)
        {
            let error = json!({ "error": {
                "code": "recovery_metadata_mismatch",
                "message": "恢复记录与本次保存的项目版本不匹配。",
            }})
            .to_string();
            return Err(project_save_error_contract(
                &error,
                "recovery_validate",
                false,
                Some(&current_fingerprint),
            ));
        }
    }
    if let Some(journal) = recovery_journal.as_ref() {
        reject_sensitive(journal).map_err(|error| {
            project_save_error_contract(
                &error,
                "recovery_validate",
                false,
                Some(&current_fingerprint),
            )
        })?;
        if journal
            .get("project")
            .is_some_and(|journal_project| journal_project != &project)
            || journal
                .get("project_id")
                .and_then(Value::as_str)
                .is_some_and(|journal_project_id| journal_project_id != current_project_id)
        {
            let error = "恢复记录必须与保存的项目快照一致";
            return Err(project_save_error_contract(
                error,
                "recovery_validate",
                false,
                Some(&current_fingerprint),
            ));
        }
    }

    let project_dir_text = project_dir.to_string_lossy().into_owned();
    if current_project == project {
        return Ok(json!({
            "fingerprint": current_fingerprint,
            "project_id": current_project_id,
            "project_dir": project_dir_text,
            "lease_generation": active_generation,
            "editor_generation": editor_generation,
            "operation_id": operation_id,
            "revision": revision,
            "outcome": "unchanged",
            "commit_state": "committed",
            "recovery_warning": Value::Null,
            "durability_warning": Value::Null,
        }));
    }

    let contents = serde_json::to_string_pretty(&project).map_err(|error| {
        project_save_error_contract(
            &error.to_string(),
            "serialize",
            false,
            Some(&current_fingerprint),
        )
    })? + "\n";
    let journal = if let Some(journal) = recovery_journal {
        Some(journal)
    } else if let Some(metadata) = recovery_metadata {
        Some(json!({
            "transaction_id": operation_id.clone().unwrap_or_else(|| native_id("save")),
            "project_id": current_project_id,
            "canonical_revision": metadata.get("canonical_revision").cloned().unwrap_or_else(|| {
                project.get("project").and_then(|value| value.get("updated_at")).cloned().unwrap_or(Value::Null)
            }),
            "saved_at": metadata.get("saved_at").cloned().unwrap_or_else(|| json!(rfc3339_now())),
            "project": project,
        }))
    } else {
        None
    };
    if let Some(journal) = journal {
        let journal_contents = serde_json::to_string(&journal).map_err(|error| {
            project_save_error_contract(
                &error.to_string(),
                "recovery_serialize",
                false,
                Some(&current_fingerprint),
            )
        })?;
        write_recovery_journal_unlocked(&project_dir, &journal_contents).map_err(|error| {
            project_save_error_contract(&error, "recovery_write", true, Some(&current_fingerprint))
        })?;
    }

    // A second and final full-file comparison closes the serialization and
    // recovery-write window. The commit helper below performs no manifest reads.
    let final_fingerprint = project_fingerprint(&project_dir).map_err(|error| {
        project_save_error_contract(&error, "final_validate", false, Some(&current_fingerprint))
    })?;
    if fingerprints_differ(&current_fingerprint, &final_fingerprint) {
        let error = external_conflict_error(Some(&current_fingerprint), &final_fingerprint);
        return Err(project_save_error_contract(
            &error,
            "final_validate",
            false,
            Some(&final_fingerprint),
        ));
    }
    let expected_committed_fingerprint = FileFingerprint {
        exists: true,
        mtime_ms: None,
        size: Some(contents.len() as u64),
        hash: Some(sha256_hex(contents.as_bytes())),
    };
    let report = write_project_contents_report_unlocked(&project_dir, &project, &contents)
        .map_err(|failure| {
            project_save_atomic_error_contract(
                &failure,
                operation_id.as_deref(),
                revision,
                Some(&final_fingerprint),
                Some(&expected_committed_fingerprint),
            )
        })?;
    let canonical_path = project_dir.join("project.json");
    if atomic_write_failure_requested(&canonical_path, "save_ack_after_commit") {
        let failure = atomic_failure(
            "测试注入：canonical 已提交但成功响应丢失",
            "acknowledgement",
            "outcome_uncertain",
            false,
        );
        return Err(project_save_atomic_error_contract(
            &failure,
            operation_id.as_deref(),
            revision,
            Some(&report.fingerprint),
            Some(&report.fingerprint),
        ));
    }
    Ok(json!({
        "fingerprint": report.fingerprint,
        "project_id": current_project_id,
        "project_dir": project_dir_text,
        "lease_generation": active_generation,
        "editor_generation": editor_generation,
        "operation_id": operation_id,
        "revision": revision,
        "outcome": "written",
        "commit_state": "committed",
        "recovery_warning": report.recovery_warning,
        "durability_warning": report.durability_warning,
    }))
}

#[tauri::command]
fn project_create(project_dir: String, project: Value) -> Result<(), String> {
    project_create_report(project_dir, &project).map(|_| ())
}

fn project_create_report(
    project_dir: String,
    project: &Value,
) -> Result<ProjectWriteReport, String> {
    let project_dir = explicit_project_dir(&project_dir, true)?;
    let already_open = project_lock_registered(&project_dir, current_app_instance_id());
    acquire_project_lock(&project_dir)?;
    if !already_open {
        let current = project_fingerprint(&project_dir)?;
        if current.exists {
            let _ = release_project_lock(&project_dir);
            return Err(external_conflict_error(None, &current));
        }
        set_project_baseline(&project_dir, None)?;
    }
    match write_project_value_report_unlocked(&project_dir, project, None) {
        Ok(report) => Ok(report),
        Err(failure) => {
            if !already_open {
                let _ = release_project_lock(&project_dir);
            }
            Err(project_save_atomic_error_contract(
                &failure, None, None, None, None,
            ))
        }
    }
}

