fn snapshot_directory(project_dir: &Path) -> PathBuf {
    project_dir.join(".workspace").join("snapshots")
}

fn existing_snapshot_directory(project_dir: &Path) -> Result<Option<PathBuf>, String> {
    let workspace = project_dir.join(".workspace");
    let snapshots = snapshot_directory(project_dir);
    for path in [&workspace, &snapshots] {
        reject_symlink(path, "历史版本目录")?;
        match fs::symlink_metadata(path) {
            Ok(metadata) if !metadata.is_dir() => return Err("历史版本目录不是目录".into()),
            Ok(_) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
            Err(error) => return Err(format!("无法检查历史版本目录: {error}")),
        }
    }
    Ok(Some(snapshots))
}

fn ensure_snapshot_directory(project_dir: &Path) -> Result<PathBuf, String> {
    ensure_directory(&project_dir.join(".workspace"), "项目工作区目录")
        .and_then(|workspace| ensure_directory(&workspace.join("snapshots"), "历史版本目录"))
}

fn valid_snapshot_id(snapshot_id: &str) -> bool {
    !snapshot_id.is_empty()
        && snapshot_id.len() <= 128
        && snapshot_id
            .chars()
            .all(|character| character.is_ascii_alphanumeric() || matches!(character, '-' | '_'))
}

#[derive(Clone, Debug)]
struct SnapshotBinding {
    project_id: String,
    project_dir: String,
    lease_generation: String,
    editor_generation: Option<u64>,
    operation_id: Option<String>,
    revision: Option<u64>,
}

fn snapshot_content_hash(project: &Value) -> Result<String, String> {
    let contents = serde_json::to_vec(project).map_err(|error| error.to_string())?;
    Ok(sha256_hex(&contents))
}

fn snapshot_binding(
    project_dir: &Path,
    project: &Value,
    expected_project_id: Option<&str>,
    requested_lease_generation: Option<&str>,
    editor_generation: Option<u64>,
    operation_id: Option<String>,
    revision: Option<u64>,
) -> Result<SnapshotBinding, String> {
    let project_id = project_id_of(project)?;
    if expected_project_id.is_some_and(|expected| expected != project_id) {
        return Err(snapshot_error(
            "project_id_mismatch",
            "快照项目身份已变化，请重新打开项目后重试。",
            "snapshot_preflight",
            "not_committed",
            false,
        ));
    }
    if let Some(operation_id) = operation_id.as_deref() {
        if !valid_snapshot_id(operation_id) {
            return Err(snapshot_error(
                "invalid_operation_id",
                "快照操作编号无效。",
                "snapshot_preflight",
                "not_committed",
                false,
            ));
        }
    }
    let directory =
        fs::canonicalize(project_dir).map_err(|error| format!("无法解析项目目录: {error}"))?;
    let current = read_project_state(&directory)?.0;
    if project_id_of(&current)? != project_id {
        return Err(snapshot_error(
            "project_id_mismatch",
            "快照与当前项目不匹配。",
            "snapshot_preflight",
            "not_committed",
            false,
        ));
    }
    let lease_generation = verify_lease_generation(&directory, requested_lease_generation)?;
    Ok(SnapshotBinding {
        project_id,
        project_dir: directory.to_string_lossy().into_owned(),
        lease_generation,
        editor_generation,
        operation_id,
        revision,
    })
}

fn snapshot_error(
    code: &str,
    message: &str,
    stage: &str,
    commit_state: &str,
    retryable: bool,
) -> String {
    json!({
        "error": {
            "code": code,
            "message": message,
            "commit_state": commit_state,
            "stage": stage,
            "retryable": retryable,
        }
    })
    .to_string()
}

fn snapshot_id_for_operation(operation_id: Option<&str>) -> Result<String, String> {
    let Some(operation_id) = operation_id else {
        return Ok(native_id("snapshot"));
    };
    if !valid_snapshot_id(operation_id) {
        return Err(snapshot_error(
            "invalid_operation_id",
            "快照操作编号无效。",
            "snapshot_preflight",
            "not_committed",
            false,
        ));
    }
    let hash = sha256_hex(operation_id.as_bytes());
    Ok(format!("snapshot-{}", &hash[..24]))
}

fn snapshot_envelope(
    snapshot_id: String,
    name: String,
    note: String,
    project: Value,
    binding: Option<&SnapshotBinding>,
) -> Result<Value, String> {
    let mut envelope = json!({
        "id": snapshot_id,
        "name": name,
        "note": note,
        "created_at": unix_millis().to_string(),
        "content_hash": snapshot_content_hash(&project)?,
        "project": project,
    });
    if let Some(binding) = binding {
        envelope["project_id"] = json!(binding.project_id);
        envelope["project_dir"] = json!(binding.project_dir);
        envelope["lease_generation"] = json!(binding.lease_generation);
        envelope["editor_generation"] = json!(binding.editor_generation);
        envelope["operation_id"] = json!(binding.operation_id);
        envelope["revision"] = json!(binding.revision);
    }
    Ok(envelope)
}

fn snapshot_binding_matches(envelope: &Value, binding: &SnapshotBinding) -> bool {
    envelope.get("project_id") == Some(&json!(binding.project_id))
        && envelope.get("project_dir") == Some(&json!(binding.project_dir))
        && envelope.get("lease_generation") == Some(&json!(binding.lease_generation))
        && envelope.get("editor_generation") == Some(&json!(binding.editor_generation))
        && envelope.get("operation_id") == Some(&json!(binding.operation_id))
        && envelope.get("revision") == Some(&json!(binding.revision))
}

fn snapshot_ack(envelope: Value, outcome: &str) -> Value {
    let field = |name: &str| envelope.get(name).cloned().unwrap_or(Value::Null);
    json!({
        "id": field("id"),
        "snapshot_id": field("id"),
        "name": field("name"),
        "note": field("note"),
        "created_at": field("created_at"),
        "content_hash": field("content_hash"),
        "project_id": field("project_id"),
        "project_dir": field("project_dir"),
        "lease_generation": field("lease_generation"),
        "editor_generation": field("editor_generation"),
        "operation_id": field("operation_id"),
        "revision": field("revision"),
        "persisted": true,
        "outcome": outcome,
    })
}

fn atomic_create_snapshot(path: &Path, contents: &[u8]) -> Result<Option<String>, String> {
    let parent = path.parent().ok_or("历史版本文件没有父目录")?;
    ensure_directory(parent, "历史版本目录")?;
    reject_symlink(path, "历史版本文件")?;
    let file_name = path
        .file_name()
        .ok_or("历史版本文件名无效")?
        .to_string_lossy();
    let temporary = parent.join(format!(
        ".{file_name}.tmp-{}-{}",
        std::process::id(),
        native_id("snapshot")
    ));
    let mut file = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&temporary)
        .map_err(|error| format!("无法创建历史版本临时文件: {error}"))?;
    if let Err(error) = file.write_all(contents).and_then(|_| file.sync_all()) {
        let _ = fs::remove_file(&temporary);
        return Err(format!("无法写入历史版本: {error}"));
    }
    drop(file);
    match fs::hard_link(&temporary, path) {
        Ok(()) => Ok(fs::remove_file(&temporary)
            .err()
            .map(|error| format!("历史版本已保存，但临时文件清理失败: {error}"))),
        Err(error) => {
            let _ = fs::remove_file(&temporary);
            if error.kind() == std::io::ErrorKind::AlreadyExists {
                Err(snapshot_error(
                    "snapshot_id_conflict",
                    "历史版本编号已被占用，请重新读取历史版本。",
                    "snapshot_create",
                    "not_committed",
                    false,
                ))
            } else {
                Err(format!("无法确认历史版本落盘: {error}"))
            }
        }
    }
}

#[cfg(test)]
fn fail_snapshot_write_for_test(snapshot_id: &str) {
    *SNAPSHOT_FAIL_ID
        .get_or_init(|| Mutex::new(None))
        .lock()
        .unwrap() = Some(snapshot_id.to_owned());
}

fn snapshot_write_failure_requested(snapshot_id: &str) -> bool {
    #[cfg(test)]
    {
        let mut fail_id = SNAPSHOT_FAIL_ID
            .get_or_init(|| Mutex::new(None))
            .lock()
            .unwrap();
        if fail_id.as_deref() == Some(snapshot_id) {
            *fail_id = None;
            return true;
        }
    }
    let _ = snapshot_id;
    false
}

fn write_snapshot_unlocked(
    project_dir: &Path,
    snapshot_id: String,
    name: String,
    note: String,
    project: Value,
    binding: &SnapshotBinding,
) -> Result<Value, String> {
    if !valid_snapshot_id(&snapshot_id) {
        return Err(snapshot_error(
            "invalid_snapshot_id",
            "历史版本编号无效。",
            "snapshot_preflight",
            "not_committed",
            false,
        ));
    }
    validate_project(&project)?;
    let envelope = snapshot_envelope(snapshot_id, name, note, project, Some(binding))?;
    reject_sensitive(&envelope)?;
    let directory = ensure_snapshot_directory(project_dir)?;
    let id = envelope
        .get("id")
        .and_then(Value::as_str)
        .ok_or("历史版本编号缺失")?;
    let path = directory.join(format!("{id}.json"));
    reject_symlink(&path, "历史版本文件")?;
    match fs::symlink_metadata(&path) {
        Ok(metadata) if metadata.is_file() => {
            let existing =
                read_snapshot_envelope(project_dir, id)?.ok_or("历史版本文件在读取时消失")?;
            let existing_project = existing.get("project").ok_or("历史版本缺少项目数据")?;
            let existing_hash = existing
                .get("content_hash")
                .and_then(Value::as_str)
                .map(ToOwned::to_owned)
                .unwrap_or(snapshot_content_hash(existing_project)?);
            let requested_hash = envelope["content_hash"].as_str().unwrap_or_default();
            if existing_hash == requested_hash && snapshot_binding_matches(&existing, binding) {
                return Ok(snapshot_ack(existing, "unchanged"));
            }
            return Err(snapshot_error(
                "snapshot_id_conflict",
                "相同历史版本编号对应不同内容或操作代次，原有历史版本未覆盖。",
                "snapshot_preflight",
                "not_committed",
                false,
            ));
        }
        Ok(_) => {
            return Err(snapshot_error(
                "snapshot_id_conflict",
                "历史版本编号已被其他文件占用，原有内容未覆盖。",
                "snapshot_preflight",
                "not_committed",
                false,
            ));
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(format!("无法检查历史版本文件: {error}")),
    }
    if snapshot_write_failure_requested(id) {
        return Err(snapshot_error(
            "snapshot_write_failed",
            "历史版本未保存，原有内容未改变。",
            "snapshot_write",
            "not_committed",
            true,
        ));
    }
    let mut contents = serde_json::to_vec_pretty(&envelope).map_err(|error| error.to_string())?;
    contents.push(b'\n');
    let durability_warning = atomic_create_snapshot(&path, &contents)?;
    let mut acknowledgement = snapshot_ack(envelope, "written");
    if let Some(warning) = durability_warning {
        acknowledgement["durability_warning"] = json!(warning);
    }
    Ok(acknowledgement)
}

fn write_snapshot(
    project_dir: &Path,
    snapshot_id: String,
    name: String,
    note: String,
    project: Value,
    expected_project_id: Option<&str>,
    lease_generation: Option<&str>,
    editor_generation: Option<u64>,
    operation_id: Option<String>,
    revision: Option<u64>,
) -> Result<Value, String> {
    let _lease_guard = require_active_project_lock(project_dir)?;
    ensure_no_external_modification(project_dir)?;
    let binding = snapshot_binding(
        project_dir,
        &project,
        expected_project_id,
        lease_generation,
        editor_generation,
        operation_id,
        revision,
    )?;
    write_snapshot_unlocked(project_dir, snapshot_id, name, note, project, &binding)
}

#[tauri::command]
fn create_snapshot(
    project_dir: String,
    snapshot_id: Option<String>,
    name: String,
    note: String,
    project: Value,
    expected_project_id: Option<String>,
    lease_generation: Option<String>,
    editor_generation: Option<u64>,
    operation_id: Option<String>,
    revision: Option<u64>,
) -> Result<Value, String> {
    let project_dir = explicit_project_dir(&project_dir, true)?;
    let id = match snapshot_id {
        Some(snapshot_id) => snapshot_id,
        None => snapshot_id_for_operation(operation_id.as_deref())?,
    };
    write_snapshot(
        &project_dir,
        id,
        name,
        note,
        project,
        expected_project_id.as_deref(),
        lease_generation.as_deref(),
        editor_generation,
        operation_id,
        revision,
    )
}

fn read_snapshot_envelope(project_dir: &Path, snapshot_id: &str) -> Result<Option<Value>, String> {
    if !valid_snapshot_id(snapshot_id) {
        return Err("历史版本编号无效".into());
    }
    let Some(directory) = existing_snapshot_directory(project_dir)? else {
        return Ok(None);
    };
    let path = directory.join(format!("{snapshot_id}.json"));
    reject_symlink(&path, "历史版本文件")?;
    match fs::symlink_metadata(&path) {
        Ok(metadata) if metadata.is_file() => {}
        Ok(_) => return Err("历史版本文件不是普通文件".into()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(format!("无法检查历史版本文件: {error}")),
    }
    let value = read_json_file(&path)?;
    if value.get("id").is_some() && value.get("name").is_some() && value.get("project").is_some() {
        let project = value.get("project").ok_or("历史版本缺少项目数据")?;
        validate_project(project)?;
        return Ok(Some(value));
    }
    // Accept the earlier raw-project snapshot format for migration/restore.
    validate_project(&value)?;
    Ok(Some(snapshot_envelope(
        snapshot_id.to_owned(),
        "历史版本".into(),
        "".into(),
        value,
        None,
    )?))
}

#[tauri::command]
fn read_snapshot(project_dir: String, snapshot_id: String) -> Result<Option<Value>, String> {
    let project_dir = explicit_project_dir(&project_dir, false)?;
    Ok(read_snapshot_envelope(&project_dir, &snapshot_id)?
        .and_then(|envelope| envelope.get("project").cloned()))
}

#[tauri::command]
fn list_snapshots(project_dir: String) -> Result<Value, String> {
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let Some(directory) = existing_snapshot_directory(&project_dir)? else {
        return Ok(Value::Array(Vec::new()));
    };
    let mut entries = Vec::new();
    let reader = match fs::read_dir(&directory) {
        Ok(reader) => reader,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Ok(Value::Array(Vec::new()))
        }
        Err(error) => return Err(format!("无法读取历史版本: {error}")),
    };
    for entry in reader {
        let entry = match entry {
            Ok(entry) => entry,
            Err(error) => {
                entries.push(json!({
                    "id": Value::Null,
                    "name": "历史版本条目无法读取",
                    "note": "",
                    "created_at": "",
                    "status": "error",
                    "error": {
                        "code": "snapshot_entry_unreadable",
                        "message": format!("无法读取历史版本条目: {error}"),
                    },
                }));
                continue;
            }
        };
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }
        let Some(id) = path.file_stem().and_then(|value| value.to_str()) else {
            entries.push(json!({
                "id": Value::Null,
                "name": "历史版本编号无效",
                "note": "",
                "created_at": "",
                "status": "error",
                "error": {
                    "code": "snapshot_invalid_id",
                    "message": "历史版本文件名无效",
                },
            }));
            continue;
        };
        match read_snapshot_envelope(&project_dir, id) {
            Ok(Some(envelope)) => entries.push(json!({
                "id": envelope.get("id").cloned().unwrap_or_else(|| json!(id)),
                "name": envelope.get("name").cloned().unwrap_or_else(|| json!("历史版本")),
                "note": envelope.get("note").cloned().unwrap_or_else(|| json!("")),
                "created_at": envelope.get("created_at").cloned().unwrap_or_else(|| json!("")),
                "status": "available",
            })),
            Ok(None) => {}
            Err(error) => entries.push(json!({
                "id": id,
                "name": "历史版本无法读取",
                "note": "",
                "created_at": "",
                "status": "error",
                "error": {
                    "code": "snapshot_unreadable",
                    "message": error,
                },
            })),
        }
    }
    entries.sort_by(|left, right| {
        right
            .get("created_at")
            .and_then(Value::as_str)
            .cmp(&left.get("created_at").and_then(Value::as_str))
    });
    Ok(Value::Array(entries))
}

#[tauri::command]
fn restore_snapshot(
    project_dir: String,
    snapshot_id: String,
    expected_project_id: Option<String>,
    lease_generation: Option<String>,
    editor_generation: Option<u64>,
    operation_id: Option<String>,
    revision: Option<u64>,
    expected_fingerprint: Option<FileFingerprint>,
) -> Result<Value, String> {
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let _lease_guard = require_active_project_lock(&project_dir)?;
    let (current, current_fingerprint) = read_project_state(&project_dir)?;
    ensure_project_matches_baseline(&project_dir, &current_fingerprint)?;
    let current_project_id = project_id_of(&current)?;
    if expected_project_id
        .as_deref()
        .is_some_and(|expected| expected != current_project_id)
    {
        return Err(snapshot_error(
            "project_id_mismatch",
            "快照项目身份已变化，请重新打开项目后重试。",
            "snapshot_preflight",
            "not_committed",
            false,
        ));
    }
    let active_generation = verify_lease_generation(&project_dir, lease_generation.as_deref())?;
    if expected_fingerprint
        .as_ref()
        .is_some_and(|expected| fingerprints_differ(expected, &current_fingerprint))
    {
        return Err(project_save_error_contract(
            &external_conflict_error(expected_fingerprint.as_ref(), &current_fingerprint),
            "fingerprint_preflight",
            false,
            Some(&current_fingerprint),
        ));
    }
    if operation_id
        .as_deref()
        .is_some_and(|value| !valid_snapshot_id(value))
    {
        return Err(snapshot_error(
            "invalid_operation_id",
            "快照操作编号无效。",
            "snapshot_preflight",
            "not_committed",
            false,
        ));
    }
    let binding = SnapshotBinding {
        project_id: current_project_id,
        project_dir: project_dir.to_string_lossy().into_owned(),
        lease_generation: active_generation.clone(),
        editor_generation,
        operation_id,
        revision,
    };
    let mutation_binding = if expected_fingerprint.is_some() {
        let mut input = Map::new();
        input.insert("expected_project_id".into(), json!(binding.project_id));
        input.insert("expected_fingerprint".into(), json!(expected_fingerprint));
        input.insert("lease_generation".into(), json!(binding.lease_generation));
        input.insert("editor_generation".into(), json!(binding.editor_generation));
        input.insert("operation_id".into(), json!(binding.operation_id));
        input.insert("revision".into(), json!(binding.revision));
        parse_canonical_mutation_binding(&input)?
    } else {
        None
    };
    validate_canonical_mutation_binding(
        mutation_binding.as_ref(),
        &current,
        &current_fingerprint,
        &active_generation,
    )?;
    let envelope =
        read_snapshot_envelope(&project_dir, &snapshot_id)?.ok_or("找不到这个历史版本")?;
    let mut restored = envelope
        .get("project")
        .cloned()
        .ok_or("历史版本缺少项目数据")?;
    if project_id_of(&restored)? != binding.project_id
        || envelope
            .get("project_id")
            .and_then(Value::as_str)
            .is_some_and(|project_id| project_id != binding.project_id)
    {
        return Err(snapshot_error(
            "snapshot_project_mismatch",
            "历史版本属于其他项目，无法恢复。",
            "restore_preflight",
            "not_committed",
            false,
        ));
    }
    let backup_id = binding
        .operation_id
        .as_deref()
        .map(|operation_id| {
            let hash = sha256_hex(operation_id.as_bytes());
            format!("restore-before-{}", &hash[..24])
        })
        .unwrap_or_else(|| native_id("restore-before"));
    let backup = write_snapshot_unlocked(
        &project_dir,
        backup_id.clone(),
        "恢复前备份".into(),
        "恢复旧版本前自动创建".into(),
        current,
        &binding,
    )?;
    let restored_object = restored.as_object_mut().ok_or("历史版本项目数据格式无效")?;
    let snapshots = restored_object
        .entry("snapshots")
        .or_insert_with(|| Value::Array(Vec::new()));
    let snapshot_list = snapshots
        .as_array_mut()
        .ok_or("历史版本的 snapshots 格式无效")?;
    snapshot_list
        .retain(|snapshot| snapshot.get("id").and_then(Value::as_str) != Some(backup_id.as_str()));
    snapshot_list.insert(
        0,
        json!({
            "id": backup.get("id").cloned().unwrap_or_else(|| json!(backup_id)),
            "name": backup.get("name").cloned().unwrap_or_else(|| json!("恢复前备份")),
            "note": backup.get("note").cloned().unwrap_or_else(|| json!("恢复旧版本前自动创建")),
            "created_at": backup.get("created_at").cloned().unwrap_or_else(|| json!(unix_millis().to_string())),
            "content_hash": backup.get("content_hash").cloned().unwrap_or(Value::Null),
        }),
    );
    let report = write_canonical_mutation_report_unlocked(
        &project_dir,
        &restored,
        &current_fingerprint,
        mutation_binding.as_ref(),
    )?;
    let mutation_ack = canonical_mutation_ack(
        mutation_binding.as_ref(),
        &restored,
        &report.fingerprint,
        &project_dir,
        &binding.lease_generation,
        "written",
        report.durability_warning.as_deref(),
        report.recovery_warning.as_deref(),
    );
    Ok(json!({
        "restored": true,
        "snapshot_id": snapshot_id,
        "backup_snapshot_id": backup_id,
        "project": restored,
        "fingerprint": report.fingerprint,
        "project_id": binding.project_id,
        "project_dir": binding.project_dir,
        "lease_generation": binding.lease_generation,
        "editor_generation": binding.editor_generation,
        "operation_id": binding.operation_id,
        "revision": binding.revision,
        "commit_state": "committed",
        "outcome": "written",
        "mutation_ack": mutation_ack,
        "backup_persisted": backup["persisted"] == true,
        "recovery_warning": report.recovery_warning,
        "durability_warning": report.durability_warning,
        "backup_durability_warning": backup.get("durability_warning").cloned(),
    }))
}

fn source_path(value: &Value) -> Result<(PathBuf, PathBuf), String> {
    let object = value.as_object().ok_or("导入参数必须是结构化对象")?;
    let raw = required_string(object, &["path", "source_path"], "导入文件")?;
    let path = PathBuf::from(raw);
    if !path.is_absolute() {
        return Err("导入文件必须是用户明确选择的绝对路径".into());
    }
    reject_symlink(&path, "导入文件")?;
    let canonical =
        fs::canonicalize(&path).map_err(|error| format!("无法读取导入文件: {error}"))?;
    reject_symlink(&canonical, "导入文件")?;
    Ok((path, canonical))
}

fn file_kind(path: &Path) -> &'static str {
    match path
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase()
        .as_str()
    {
        "md" | "markdown" => "markdown",
        "txt" => "text",
        "json" => "json",
        "png" | "jpg" | "jpeg" | "gif" | "webp" | "svg" => "image",
        "mp4" | "mov" | "webm" => "video",
        "mp3" | "wav" | "m4a" => "audio",
        _ => "file",
    }
}

fn import_item(path: &Path) -> Result<Value, String> {
    let metadata = fs::metadata(path).map_err(|error| format!("无法读取导入文件信息: {error}"))?;
    let title = path
        .file_stem()
        .and_then(|value| value.to_str())
        .unwrap_or("未命名输入");
    let kind = file_kind(path);
    let body = if matches!(kind, "markdown" | "text" | "json") && metadata.len() <= 10 * 1024 * 1024
    {
        fs::read_to_string(path).unwrap_or_default()
    } else {
        String::new()
    };
    Ok(json!({
        "name": path.file_name().and_then(|value| value.to_str()).unwrap_or("input"),
        "title": title,
        "kind": kind,
        "size_bytes": metadata.len(),
        "body": body,
    }))
}

fn preview_source(source: &Value) -> Result<Value, String> {
    let object = require_object(source, "import_preview")?;
    let (original, canonical) = source_path(source)?;
    let metadata =
        fs::metadata(&canonical).map_err(|error| format!("无法读取导入来源: {error}"))?;
    let mut items = Vec::new();
    let mut warnings = Vec::new();
    if metadata.is_dir() {
        for entry in
            fs::read_dir(&canonical).map_err(|error| format!("无法读取导入目录: {error}"))?
        {
            let entry = entry.map_err(|error| format!("无法读取导入目录条目: {error}"))?;
            let path = entry.path();
            reject_symlink(&path, "导入目录条目")?;
            if path.is_file() {
                items.push(import_item(&path)?);
            }
        }
        warnings.push("目录导入只读取第一层文件，脚本和宏不会执行".to_owned());
    } else if metadata.is_file() {
        items.push(import_item(&canonical)?);
    } else {
        return Err("导入来源不是文件或目录".into());
    }
    Ok(json!({
        "requires_confirmation": true,
        "project_dir": field(object, &["project_dir", "projectDir"]).cloned().unwrap_or(Value::Null),
        "source_path": original,
        "items": items,
        "warnings": warnings,
        "errors": [],
    }))
}

#[tauri::command]
fn import_preview(source: Value) -> Result<Value, String> {
    preview_source(&source)
}

#[tauri::command]
fn import_preview_release(input: Value) -> Result<Value, String> {
    let outer = require_object(&input, "import_preview_release")?;
    let payload = outer
        .get("input")
        .filter(|value| value.is_object())
        .cloned()
        .unwrap_or(input);
    let _ = require_object(&payload, "import_preview_release")?;
    // Native previews own no cached resources; the command is present so the
    // bridge can use one lifecycle contract across native and browser modes.
    Ok(json!({ "released": false }))
}

fn scan_mime_for(name: &str) -> Option<&'static str> {
    let mime = mime_for_filename(name);
    (mime != "application/octet-stream").then_some(mime)
}

fn scan_suggested_role(path: &Path, kind: &str, relative: &str) -> &'static str {
    if kind == "directory" {
        let normalized = relative.trim_matches(|c| c == '/' || c == '\\');
        if normalized.is_empty() {
            return "folder";
        }
        return if normalized.contains('/') || normalized.contains('\\') {
            "folder"
        } else {
            "stage"
        };
    }
    let ext = path
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    match ext.as_str() {
        "md" | "markdown" | "txt" | "text" | "tex" | "latex" => "lesson",
        "png" | "jpg" | "jpeg" | "gif" | "webp" | "svg" | "avif" | "mp4" | "webm" | "mov"
        | "m4v" | "mp3" | "wav" | "m4a" | "ogg" => "asset",
        "pdf" | "doc" | "docx" | "epub" | "odt" | "rtf" => "reference",
        _ => "unsupported",
    }
}

fn scan_relative(root: &Path, path: &Path) -> Result<String, String> {
    let rel = path
        .strip_prefix(root)
        .map_err(|_| "扫描路径越过了所选文件夹边界".to_string())?;
    Ok(rel.to_string_lossy().replace('\\', "/"))
}

fn push_scan_entry(
    entries: &mut Vec<Value>,
    path: &Path,
    relative: &str,
    kind: &str,
    size: Option<u64>,
    error: Option<String>,
) {
    let name = path
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("");
    let mime = if kind == "file" {
        scan_mime_for(name).map(Value::from).unwrap_or(Value::Null)
    } else {
        Value::Null
    };
    let role = if error.is_some() {
        "unsupported"
    } else {
        scan_suggested_role(path, kind, relative)
    };
    entries.push(json!({
        "path": path.to_string_lossy(),
        "relative_path": relative,
        "kind": kind,
        "mime": mime,
        "size": size,
        "suggested_role": role,
        "error": error,
    }));
}

fn walk_folder_scan(
    root: &Path,
    path: &Path,
    depth: usize,
    entries: &mut Vec<Value>,
    warnings: &mut Vec<String>,
    errors: &mut Vec<String>,
    visited: &mut std::collections::HashSet<PathBuf>,
) {
    let meta = match fs::symlink_metadata(path) {
        Ok(meta) => meta,
        Err(error) => {
            let relative =
                scan_relative(root, path).unwrap_or_else(|_| path.to_string_lossy().into());
            let message = format!("无法读取：{error}");
            push_scan_entry(
                entries,
                path,
                &relative,
                "file",
                None,
                Some(message.clone()),
            );
            errors.push(format!("{relative}: {message}"));
            return;
        }
    };
    if meta.file_type().is_symlink() {
        let relative = scan_relative(root, path).unwrap_or_else(|_| path.to_string_lossy().into());
        warnings.push(format!("{relative}: 已跳过符号链接，避免越过所选文件夹"));
        return;
    }
    if meta.is_dir() {
        let identity = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
        if !visited.insert(identity) {
            return;
        }
        let relative = match scan_relative(root, path) {
            Ok(value) => value,
            Err(message) => {
                errors.push(message);
                return;
            }
        };
        if !relative.is_empty() {
            push_scan_entry(entries, path, &relative, "directory", None, None);
            // Mapping previews expose only direct children. A subfolder must
            // be selected as a new root before its contents are considered.
            if depth > 0 {
                return;
            }
        }
        let reader = match fs::read_dir(path) {
            Ok(reader) => reader,
            Err(error) => {
                let message = format!("无法读取目录：{error}");
                if relative.is_empty() {
                    errors.push(message);
                    return;
                }
                if let Some(last) = entries.last_mut() {
                    if last.get("path").and_then(Value::as_str) == Some(&path.to_string_lossy()) {
                        last.as_object_mut().map(|object| {
                            object.insert("error".into(), json!(message));
                            object.insert("suggested_role".into(), json!("unsupported"));
                        });
                    }
                }
                errors.push(format!("{relative}: {message}"));
                return;
            }
        };
        let mut children: Vec<std::fs::DirEntry> = reader.filter_map(Result::ok).collect();
        children.sort_by_key(|entry| entry.file_name());
        for child in children {
            let name = child.file_name();
            let name = name.to_string_lossy();
            if name.starts_with('.') {
                continue;
            }
            if managed_import_name(&name) {
                let relative = if relative.is_empty() {
                    name.to_string()
                } else {
                    format!("{relative}/{name}")
                };
                warnings.push(format!("{relative}: 已跳过工作台管理文件或构建目录"));
                continue;
            }
            let child_path = child.path();
            if let Ok(child_meta) = fs::symlink_metadata(&child_path) {
                if child_meta.file_type().is_symlink() {
                    let child_rel = if relative.is_empty() {
                        name.to_string()
                    } else {
                        format!("{relative}/{name}")
                    };
                    warnings.push(format!("{child_rel}: 已跳过符号链接"));
                    continue;
                }
            }
            walk_folder_scan(
                root,
                &child_path,
                depth + 1,
                entries,
                warnings,
                errors,
                visited,
            );
        }
        return;
    }
    if !meta.is_file() {
        let relative = scan_relative(root, path).unwrap_or_else(|_| path.to_string_lossy().into());
        warnings.push(format!("{relative}: 已跳过非普通文件"));
        return;
    }
    let relative = match scan_relative(root, path) {
        Ok(value) => value,
        Err(message) => {
            errors.push(message);
            return;
        }
    };
    // Probe readability without loading content into Canonical.
    if let Err(error) = fs::File::open(path) {
        let message = format!("无法读取文件：{error}");
        push_scan_entry(
            entries,
            path,
            &relative,
            "file",
            None,
            Some(message.clone()),
        );
        errors.push(format!("{relative}: {message}"));
        return;
    }
    if meta.len() > 100 * 1024 * 1024 {
        warnings.push(format!(
            "{relative}: 文件较大（{} 字节），扫描仅记录元数据，不会读取内容",
            meta.len()
        ));
    }
    push_scan_entry(entries, path, &relative, "file", Some(meta.len()), None);
}

fn managed_import_name(name: &str) -> bool {
    let lower = name.to_ascii_lowercase();
    matches!(
        lower.as_str(),
        "project.json"
            | "project.json.bak"
            | "project.json.backup"
            | "project.bak"
            | "project.lock"
            | "project.lock.guard"
            | "providers.json"
            | "providers.bak"
            | "credentials.json"
            | ".workspace"
            | ".git"
            | ".svn"
            | ".hg"
            | "node_modules"
            | "vendor"
            | "target"
            | "dist"
            | "build"
            | "out"
            | "coverage"
            | ".next"
            | ".cache"
            | ".env"
            | "id_rsa"
            | "id_ed25519"
            | "backups"
            | "backup"
    ) || [".bak", ".backup", ".lock", ".tmp", "~"]
        .iter()
        .any(|suffix| lower.ends_with(suffix))
        || lower.starts_with(".env.")
        || ["credential", "secret", "token", "api_key", "api-key"]
            .iter()
            .any(|marker| lower.contains(marker))
        || [".pem", ".key", ".p12", ".pfx", ".orig", ".old", ".swp"]
            .iter()
            .any(|suffix| lower.ends_with(suffix))
}

/// Read-only folder scan for 导入已有文件夹 (V1-T04). Does not write project.json.
/// Accepts the same flat `{ path }` payload the bridge sends for non-project commands.
#[tauri::command]
fn folder_scan(
    path: Option<String>,
    folder_path: Option<String>,
    root: Option<String>,
) -> Result<Value, String> {
    let raw = path.or(folder_path).or(root).unwrap_or_default();
    let trimmed = raw.trim();
    let path = PathBuf::from(trimmed);
    if trimmed.is_empty() || !path.is_absolute() {
        return Err("导入文件夹必须是用户明确选择的绝对路径".into());
    }
    reject_symlink(&path, "导入文件夹")?;
    let metadata =
        fs::symlink_metadata(&path).map_err(|error| format!("无法打开所选文件夹：{error}"))?;
    if metadata.file_type().is_symlink() {
        return Err("为避免越过目录边界，导入不支持以符号链接作为根目录".into());
    }
    if !metadata.is_dir() {
        return Err("导入已有文件夹需要选择一个文件夹，而不是单个文件".into());
    }
    let root = fs::canonicalize(&path).unwrap_or(path.clone());
    reject_symlink(&root, "导入文件夹")?;
    let mut entries = Vec::new();
    let mut warnings = Vec::new();
    let mut errors = Vec::new();
    let mut visited = std::collections::HashSet::new();
    walk_folder_scan(
        &root,
        &root,
        0,
        &mut entries,
        &mut warnings,
        &mut errors,
        &mut visited,
    );
    entries.sort_by(|left, right| {
        let left_rel = left
            .get("relative_path")
            .and_then(Value::as_str)
            .unwrap_or("");
        let right_rel = right
            .get("relative_path")
            .and_then(Value::as_str)
            .unwrap_or("");
        left_rel.cmp(right_rel)
    });
    let scanned_videos: HashSet<(PathBuf, String)> = entries
        .iter()
        .filter_map(|entry| {
            if entry.get("kind").and_then(Value::as_str) != Some("file") {
                return None;
            }
            let relative_path = entry.get("relative_path")?.as_str()?;
            let name = Path::new(relative_path).file_name()?.to_str()?;
            let mime = mime_for_filename(name);
            (folder_preview_kind(name, Some(mime)) == "video")
                .then(|| (root.clone(), relative_path.to_owned()))
        })
        .collect();
    *SCANNED_FOLDER_VIDEOS
        .get_or_init(|| Mutex::new(HashSet::new()))
        .lock()
        .unwrap() = scanned_videos;
    Ok(json!({
        "root": root.to_string_lossy(),
        "entries": entries,
        "warnings": warnings,
        "errors": errors,
    }))
}

/// Scan only the direct supported-document children of selected stage/lesson folders.
/// The confirmed Mapping plan owns each child's role and destination.
#[tauri::command]
fn folder_scan_documents(root: Option<String>, plan: Value) -> Result<Value, String> {
    let plan_object = plan
        .as_object()
        .ok_or_else(|| "folder.scan_documents requires a mapping plan".to_string())?;
    if plan_object.get("confirmed").and_then(Value::as_bool) != Some(true) {
        return Err("只能扫描已确认映射计划中的文档候选".into());
    }
    let plan_root = plan_object
        .get("root")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim();
    let raw_root = root.as_deref().unwrap_or(plan_root).trim();
    if raw_root.is_empty() || !Path::new(raw_root).is_absolute() {
        return Err("文档扫描需要已选择的绝对路径".into());
    }
    let requested_root = PathBuf::from(raw_root);
    reject_symlink(&requested_root, "导入文件夹")?;
    let metadata = fs::symlink_metadata(&requested_root)
        .map_err(|error| format!("无法打开所选文件夹：{error}"))?;
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err("文档扫描需要已选择的文件夹根目录".into());
    }
    let resolved_root = fs::canonicalize(&requested_root)
        .map_err(|error| format!("无法解析所选文件夹：{error}"))?;
    let resolved_plan_root = fs::canonicalize(plan_root)
        .map_err(|error| format!("无法解析已确认计划的源文件夹：{error}"))?;
    if resolved_root != resolved_plan_root {
        return Err("文档扫描路径必须与已确认映射计划的源文件夹一致".into());
    }

    let mut groups = Vec::new();
    let mut warnings = Vec::new();
    let mut errors = Vec::new();
    let plan_items = plan_object
        .get("items")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    for parent in plan_items.iter().filter(|item| {
        item.get("kind").and_then(Value::as_str) == Some("directory")
            && item.get("selected").and_then(Value::as_bool) == Some(true)
            && item.get("error").map_or(true, Value::is_null)
            && matches!(
                item.get("mapping").and_then(Value::as_str),
                Some("stage" | "lesson")
            )
    }) {
        let directory = parent
            .get("relative_path")
            .and_then(Value::as_str)
            .unwrap_or("")
            .replace('\\', "/");
        if directory.is_empty()
            || directory.contains('/')
            || directory.contains('\0')
            || Path::new(&directory).is_absolute()
            || directory == "."
            || directory == ".."
        {
            warnings.push(format!("{directory}: 映射目录无效，未扫描直接子文件"));
            continue;
        }
        let mapping = parent
            .get("mapping")
            .and_then(Value::as_str)
            .unwrap_or("stage");
        let parent_destination = parent
            .get("destination")
            .cloned()
            .filter(|value| !value.is_null())
            .unwrap_or(Value::Null);
        let destination = if mapping == "lesson" {
            parent_destination.clone()
        } else {
            Value::Null
        };
        let mut items = Vec::new();
        let directory_path = resolved_root.join(&directory);
        if path_has_symlink_component(&resolved_root, &directory)? {
            warnings.push(format!("{directory}: 已跳过符号链接，避免越过所选文件夹"));
            groups.push(json!({
                "directory": directory,
                "mapping": mapping,
                "destination": parent_destination.clone(),
                "items": items,
            }));
            continue;
        }
        match fs::symlink_metadata(&directory_path) {
            Ok(value) if !value.file_type().is_symlink() && value.is_dir() => {}
            Ok(_) => {
                warnings.push(format!("{directory}: 映射目录已不是文件夹，未扫描"));
                groups.push(json!({
                    "directory": directory,
                    "mapping": mapping,
                    "destination": parent_destination.clone(),
                    "items": items,
                }));
                continue;
            }
            Err(error) => {
                let message = format!("无法读取映射目录：{error}");
                errors.push(format!("{directory}: {message}"));
                groups.push(json!({
                    "directory": directory,
                    "mapping": mapping,
                    "destination": parent_destination.clone(),
                    "items": items,
                }));
                continue;
            }
        };
        let resolved_directory = fs::canonicalize(&directory_path)
            .map_err(|error| format!("无法解析映射目录：{error}"))?;
        if !resolved_directory.starts_with(&resolved_root) {
            warnings.push(format!("{directory}: 映射目录超出所选文件夹，未扫描"));
            groups.push(json!({
                "directory": directory,
                "mapping": mapping,
                "destination": parent_destination.clone(),
                "items": items,
            }));
            continue;
        }
        let reader = match fs::read_dir(&resolved_directory) {
            Ok(reader) => reader,
            Err(error) => {
                let message = format!("无法读取目录：{error}");
                errors.push(format!("{directory}: {message}"));
                groups.push(json!({
                    "directory": directory,
                    "mapping": mapping,
                    "destination": parent_destination.clone(),
                    "items": items,
                }));
                continue;
            }
        };
        let mut children: Vec<std::fs::DirEntry> = reader.filter_map(Result::ok).collect();
        children.sort_by_key(|entry| entry.file_name());
        for child in children {
            let filename = child.file_name().to_string_lossy().into_owned();
            if filename.starts_with('.') {
                continue;
            }
            let relative_path = format!("{directory}/{filename}");
            if managed_import_name(&filename) {
                warnings.push(format!("{relative_path}: 已跳过工作台管理文件或构建目录"));
                continue;
            }
            if !documents::is_supported_document(&filename) {
                continue;
            }
            let path = child.path();
            let file_meta = match fs::symlink_metadata(&path) {
                Ok(value) if value.file_type().is_symlink() => {
                    warnings.push(format!(
                        "{relative_path}: 已跳过符号链接，避免越过所选文件夹"
                    ));
                    continue;
                }
                Ok(value) if value.is_file() => value,
                Ok(_) => continue,
                Err(error) => {
                    let message = format!("无法读取：{error}");
                    errors.push(format!("{relative_path}: {message}"));
                    items.push(json!({
                        "relative_path": relative_path,
                        "kind": "file",
                        "mime": mime_for_filename(&filename),
                        "size": Value::Null,
                        "suggested": "lesson",
                        "mapping": "lesson",
                        "selected": false,
                        "is_suggestion": true,
                        "error": message,
                        "destination": destination.clone(),
                    }));
                    continue;
                }
            };
            if let Err(message) = scan_relative(&resolved_root, &path) {
                warnings.push(format!("{relative_path}: {message}"));
                continue;
            }
            let error = fs::File::open(&path)
                .err()
                .map(|error| format!("无法读取文件：{error}"));
            if let Some(message) = &error {
                errors.push(format!("{relative_path}: {message}"));
            }
            items.push(json!({
                "relative_path": relative_path,
                "kind": "file",
                "mime": mime_for_filename(&filename),
                "size": file_meta.len(),
                "suggested": "lesson",
                "mapping": "lesson",
                "selected": error.is_none(),
                "is_suggestion": true,
                "error": error,
                "destination": destination.clone(),
            }));
        }
        groups.push(json!({
            "directory": directory,
            "mapping": mapping,
            "destination": parent_destination,
            "items": items,
        }));
    }
    Ok(json!({
        "root": resolved_root.to_string_lossy(),
        "groups": groups,
        "warnings": warnings,
        "errors": errors,
    }))
}

/// Visual-media classifier for one file name: image or video only. Documents,
/// text and audio stay out, so a directory sweep can never disagree with
/// `folder_scan`'s own classification.
fn media_descendant_kind(name: &str) -> Option<&'static str> {
    match folder_preview_kind(name, Some(mime_for_filename(name))) {
        "image" => Some("image"),
        "video" => Some("video"),
        _ => None,
    }
}

/// Recursively collect visual media under `dir`. Only reached for a directory
/// the user selected explicitly; the Mapping Preview listing stays flat.
fn walk_media_descendants(
    root: &Path,
    dir: &Path,
    relative_dir: &str,
    entries: &mut Vec<Value>,
    warnings: &mut Vec<String>,
    errors: &mut Vec<String>,
    visited: &mut HashSet<PathBuf>,
) {
    let reader = match fs::read_dir(dir) {
        Ok(reader) => reader,
        Err(error) => {
            let label = if relative_dir.is_empty() {
                "."
            } else {
                relative_dir
            };
            errors.push(format!("{label}: 无法读取目录：{error}"));
            return;
        }
    };
    let mut children: Vec<fs::DirEntry> = reader.filter_map(Result::ok).collect();
    children.sort_by_key(|entry| entry.file_name());
    for child in children {
        let name = child.file_name();
        let name = name.to_string_lossy().to_string();
        let rel = if relative_dir.is_empty() {
            name.clone()
        } else {
            format!("{relative_dir}/{name}")
        };
        if managed_import_name(&name) {
            warnings.push(format!("{rel}: 已跳过工作台管理文件或构建目录"));
            continue;
        }
        if name.starts_with('.') {
            continue;
        }
        let path = child.path();
        let meta = match fs::symlink_metadata(&path) {
            Ok(meta) => meta,
            Err(error) => {
                errors.push(format!("{rel}: 无法读取：{error}"));
                continue;
            }
        };
        if meta.file_type().is_symlink() {
            warnings.push(format!("{rel}: 已跳过符号链接，避免越过所选文件夹"));
            continue;
        }
        if meta.is_dir() {
            let identity = fs::canonicalize(&path).unwrap_or_else(|_| path.clone());
            if !visited.insert(identity.clone()) {
                warnings.push(format!("{rel}: 已跳过重复目录"));
                continue;
            }
            if !identity.starts_with(root) {
                warnings.push(format!("{rel}: 已跳过超出所选文件夹的目录"));
                continue;
            }
            walk_media_descendants(root, &path, &rel, entries, warnings, errors, visited);
            continue;
        }
        if !meta.is_file() {
            warnings.push(format!("{rel}: 已跳过非普通文件"));
            continue;
        }
        let Some(kind) = media_descendant_kind(&name) else {
            continue;
        };
        // One unreadable descendant must not fail the batch.
        if let Err(error) = fs::File::open(&path) {
            errors.push(format!("{rel}: 无法读取文件：{error}"));
            continue;
        }
        let mime = scan_mime_for(&name).unwrap_or(if kind == "image" {
            "image/*"
        } else {
            "video/*"
        });
        entries.push(json!({
            "relative_path": rel,
            "filename": name,
            "mime": mime,
            "kind": kind,
            "size": meta.len(),
        }));
    }
}

/// Recursive visual-media discovery for one SELECTED directory row. Read-only:
/// never writes project.json and never mutates the source files.
#[tauri::command]
fn folder_scan_media(
    root: Option<String>,
    folder_path: Option<String>,
    path: Option<String>,
    relative_dir: Option<String>,
    relative_path: Option<String>,
) -> Result<Value, String> {
    let raw = root.or(folder_path).or(path).unwrap_or_default();
    let trimmed = raw.trim();
    let candidate = PathBuf::from(trimmed);
    if trimmed.is_empty() || !candidate.is_absolute() {
        return Err("导入文件夹必须是用户明确选择的绝对路径".into());
    }
    reject_symlink(&candidate, "导入文件夹")?;
    let metadata =
        fs::symlink_metadata(&candidate).map_err(|error| format!("无法打开所选文件夹：{error}"))?;
    if metadata.file_type().is_symlink() {
        return Err("为避免越过目录边界，导入不支持以符号链接作为根目录".into());
    }
    if !metadata.is_dir() {
        return Err("导入已有文件夹需要选择一个文件夹，而不是单个文件".into());
    }
    let resolved_root = fs::canonicalize(&candidate).unwrap_or_else(|_| candidate.clone());
    reject_symlink(&resolved_root, "导入文件夹")?;

    let rel = relative_dir
        .or(relative_path)
        .unwrap_or_default()
        .trim()
        .replace('\\', "/");
    let rel = rel.trim_matches('/').to_string();
    let parts: Vec<&str> = rel.split('/').filter(|part| !part.is_empty()).collect();
    if rel.contains('\0')
        || Path::new(&rel).is_absolute()
        || parts.iter().any(|part| *part == ".." || *part == ".")
    {
        return Err("扫描路径无效".into());
    }
    if !parts.is_empty() && path_has_symlink_component(&resolved_root, &rel)? {
        return Err("已跳过符号链接，避免越过所选文件夹".into());
    }
    let mut target = resolved_root.clone();
    for part in &parts {
        target.push(part);
        reject_symlink(&target, "所选文件夹")?;
    }
    let _ = scan_relative(&resolved_root, &target)?;
    let target_meta =
        fs::symlink_metadata(&target).map_err(|error| format!("无法读取所选文件夹：{error}"))?;
    if target_meta.file_type().is_symlink() {
        return Err("已跳过符号链接，避免越过所选文件夹".into());
    }
    if !target_meta.is_dir() {
        return Err("选择媒体目录需要选择一个文件夹，而不是单个文件".into());
    }

    let mut entries = Vec::new();
    let mut warnings = Vec::new();
    let mut errors = Vec::new();
    let mut visited: HashSet<PathBuf> = HashSet::new();
    if let Ok(identity) = fs::canonicalize(&target) {
        visited.insert(identity);
    }
    walk_media_descendants(
        &resolved_root,
        &target,
        &rel,
        &mut entries,
        &mut warnings,
        &mut errors,
        &mut visited,
    );
    entries.sort_by(|left, right| {
        let left_rel = left
            .get("relative_path")
            .and_then(Value::as_str)
            .unwrap_or("");
        let right_rel = right
            .get("relative_path")
            .and_then(Value::as_str)
            .unwrap_or("");
        left_rel.cmp(right_rel)
    });

    // Range/byte serving for a folder video is gated by SCANNED_FOLDER_VIDEOS,
    // keyed (canonical root, relative path). folder_scan replaces that set with
    // its direct children only, so descendants found here must be merged in or
    // their previews would be refused after the scan.
    {
        let mut granted = SCANNED_FOLDER_VIDEOS
            .get_or_init(|| Mutex::new(HashSet::new()))
            .lock()
            .unwrap();
        for entry in &entries {
            if entry.get("kind").and_then(Value::as_str) == Some("video") {
                if let Some(relative) = entry.get("relative_path").and_then(Value::as_str) {
                    granted.insert((resolved_root.clone(), relative.to_string()));
                }
            }
        }
    }

    Ok(json!({
        "root": resolved_root.to_string_lossy(),
        "relative_dir": rel,
        "entries": entries,
        "warnings": warnings,
        "errors": errors,
    }))
}

/// §4.2/§4.3: a directory row the user selected contributes the visual media
/// found anywhere beneath it, as asset candidates. The Mapping Preview listing
/// stays flat (§4.1), so this runs when the confirmed plan is applied rather
/// than when the table is built. A descendant becomes an Asset only — never a
/// Lesson, and never an `AssetUsage` created merely because the folder was
/// selected. Paths the preview already lists keep the user's own mapping.
fn expand_selected_directory_media(
    source_root: &Path,
    items: &mut Vec<Value>,
    warnings: &mut Vec<String>,
) {
    let mut claimed: HashSet<String> = HashSet::new();
    for item in items.iter() {
        if let Some(rel) = item.get("relative_path").and_then(Value::as_str) {
            claimed.insert(rel.replace('\\', "/"));
        }
    }
    let selected_dirs: Vec<String> = items
        .iter()
        .filter(|item| adopt_item_included(item))
        .filter(|item| item.get("kind").and_then(Value::as_str) == Some("directory"))
        .filter_map(|item| item.get("relative_path").and_then(Value::as_str))
        .map(|rel| rel.replace('\\', "/").trim_matches('/').to_string())
        .filter(|rel| !rel.is_empty())
        .collect();

    let mut synthesized = Vec::new();
    for rel in selected_dirs {
        if rel.contains('\0')
            || Path::new(&rel).is_absolute()
            || rel.split('/').any(|part| part == ".." || part == ".")
        {
            warnings.push(format!("{rel}: 非法路径已跳过"));
            continue;
        }
        let mut target = source_root.to_path_buf();
        let mut unusable = false;
        for part in rel.split('/').filter(|part| !part.is_empty()) {
            target.push(part);
            match fs::symlink_metadata(&target) {
                Ok(meta) if meta.file_type().is_symlink() => {
                    warnings.push(format!("{rel}: 已跳过符号链接，避免越过所选文件夹"));
                    unusable = true;
                }
                Ok(_) => {}
                Err(error) => {
                    warnings.push(format!("{rel}: 无法读取目录（{error}）"));
                    unusable = true;
                }
            }
        }
        if unusable || !target.is_dir() {
            continue;
        }
        let mut found = Vec::new();
        let mut scanned_warnings = Vec::new();
        let mut scanned_errors = Vec::new();
        let mut visited: HashSet<PathBuf> = HashSet::new();
        if let Ok(identity) = fs::canonicalize(&target) {
            visited.insert(identity);
        }
        walk_media_descendants(
            source_root,
            &target,
            &rel,
            &mut found,
            &mut scanned_warnings,
            &mut scanned_errors,
            &mut visited,
        );
        warnings.extend(scanned_warnings);
        // One unreadable descendant degrades to a warning, like everywhere else
        // in the apply path: the rest of the folder still imports.
        warnings.extend(scanned_errors);
        for entry in found {
            let candidate = entry
                .get("relative_path")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string();
            if candidate.is_empty() || !claimed.insert(candidate.clone()) {
                continue;
            }
            let kind = entry
                .get("kind")
                .and_then(Value::as_str)
                .unwrap_or("image")
                .to_string();
            synthesized.push(json!({
                "relative_path": candidate,
                "filename": entry.get("filename").cloned().unwrap_or(Value::Null),
                "kind": kind,
                "mime": entry.get("mime").cloned().unwrap_or(Value::Null),
                "size": entry.get("size").cloned().unwrap_or(json!(0)),
                "suggested": "asset",
                "mapping": "asset",
                "selected": true,
                "is_suggestion": true,
            }));
        }
    }
    let count = synthesized.len();
    if count > 0 {
        items.extend(synthesized);
        warnings.push(format!(
            "已从所选文件夹递归收录 {count} 个图片/视频素材，仅作为素材入库，没有写入课时正文。"
        ));
    }
}

fn folder_preview_kind(name: &str, mime: Option<&str>) -> &'static str {
    let ext = Path::new(name)
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    let lower_mime = mime.unwrap_or("").to_ascii_lowercase();
    if lower_mime.starts_with("text/") || matches!(ext.as_str(), "md" | "markdown" | "txt" | "text")
    {
        return "text";
    }
    if lower_mime.starts_with("image/")
        || matches!(
            ext.as_str(),
            "png" | "jpg" | "jpeg" | "gif" | "webp" | "svg" | "avif"
        )
    {
        return "image";
    }
    if lower_mime.starts_with("video/") || matches!(ext.as_str(), "mp4" | "webm" | "mov" | "m4v") {
        return "video";
    }
    if lower_mime.starts_with("audio/") || matches!(ext.as_str(), "mp3" | "wav" | "m4a" | "ogg") {
        return "audio";
    }
    if lower_mime == "application/pdf" || ext == "pdf" {
        return "pdf";
    }
    if lower_mime.contains("word")
        || lower_mime.contains("document")
        || matches!(ext.as_str(), "doc" | "docx" | "odt" | "rtf")
    {
        return "reference";
    }
    "unsupported"
}

/// Read-only preview for Workspace Explorer. Never writes project.json.
#[tauri::command]
fn folder_read_preview(
    root: Option<String>,
    path: Option<String>,
    relative_path: Option<String>,
) -> Result<Value, String> {
    const TEXT_LIMIT: u64 = 512 * 1024;
    const MEDIA_LIMIT: u64 = 16 * 1024 * 1024;
    let root_raw = root.or(path).unwrap_or_default();
    let root_trimmed = root_raw.trim();
    let rel = relative_path.unwrap_or_default();
    let rel = rel.trim().trim_start_matches(|c| c == '/' || c == '\\');
    if root_trimmed.is_empty() {
        return Err("folder.read_preview requires the scanned root".into());
    }
    if rel.is_empty() || rel.contains('\0') || rel.split(['/', '\\']).any(|part| part == "..") {
        return Err("预览路径无效".into());
    }
    let root_path = PathBuf::from(root_trimmed);
    if !root_path.is_absolute() {
        return Err("导入文件夹必须是用户明确选择的绝对路径".into());
    }
    reject_symlink(&root_path, "导入文件夹")?;
    let root_meta =
        fs::symlink_metadata(&root_path).map_err(|error| format!("无法打开所选文件夹：{error}"))?;
    if root_meta.file_type().is_symlink() {
        return Err("为避免越过目录边界，导入不支持以符号链接作为根目录".into());
    }
    if !root_meta.is_dir() {
        return Err("导入已有文件夹需要选择一个文件夹，而不是单个文件".into());
    }
    let resolved_root = fs::canonicalize(&root_path).unwrap_or(root_path.clone());
    reject_symlink(&resolved_root, "导入文件夹")?;
    let mut absolute = resolved_root.clone();
    for part in rel.split(['/', '\\']).filter(|part| !part.is_empty()) {
        absolute.push(part);
    }
    let _ = scan_relative(&resolved_root, &absolute)?;
    if path_has_symlink_component(&resolved_root, rel)? {
        return Ok(json!({
            "relative_path": rel,
            "mime": Value::Null,
            "size": Value::Null,
            "preview_kind": "unsupported",
            "text": Value::Null,
            "bytes_base64": Value::Null,
            "note": Value::Null,
            "error": "已跳过符号链接，避免越过所选文件夹",
        }));
    }
    let name = absolute
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("")
        .to_string();
    let meta = match fs::symlink_metadata(&absolute) {
        Ok(value) => value,
        Err(error) => {
            return Ok(json!({
                "relative_path": rel,
                "mime": Value::Null,
                "size": Value::Null,
                "preview_kind": "unsupported",
                "text": Value::Null,
                "bytes_base64": Value::Null,
                "note": Value::Null,
                "error": format!("无法读取：{error}"),
            }));
        }
    };
    if meta.file_type().is_symlink() {
        return Ok(json!({
            "relative_path": rel,
            "mime": Value::Null,
            "size": Value::Null,
            "preview_kind": "unsupported",
            "text": Value::Null,
            "bytes_base64": Value::Null,
            "note": Value::Null,
            "error": "已跳过符号链接，避免越过所选文件夹",
        }));
    }
    if meta.is_dir() {
        return Ok(json!({
            "relative_path": rel,
            "mime": Value::Null,
            "size": Value::Null,
            "preview_kind": "directory",
            "text": Value::Null,
            "bytes_base64": Value::Null,
            "note": "文件夹",
        }));
    }
    let mime = scan_mime_for(&name);
    let kind = folder_preview_kind(&name, mime);
    let size = meta.len();
    if size == 0 {
        return Ok(json!({
            "relative_path": rel,
            "mime": mime,
            "size": size,
            "preview_kind": kind,
            "text": Value::Null,
            "bytes_base64": Value::Null,
            "note": Value::Null,
            "error": "文件为空，无法预览",
        }));
    }
    if kind == "reference" {
        return Ok(json!({
            "relative_path": rel,
            "mime": mime,
            "size": size,
            "preview_kind": "reference",
            "text": Value::Null,
            "bytes_base64": Value::Null,
            "note": "参考文件 · 仅显示文件信息",
        }));
    }
    if kind == "unsupported" {
        return Ok(json!({
            "relative_path": rel,
            "mime": mime,
            "size": size,
            "preview_kind": "unsupported",
            "text": Value::Null,
            "bytes_base64": Value::Null,
            "note": "当前版本暂不支持预览此类型",
        }));
    }
    let limit = if kind == "text" {
        TEXT_LIMIT
    } else {
        MEDIA_LIMIT
    };
    if size > limit {
        let limit_label = if kind == "text" { "512 KiB" } else { "16 MiB" };
        let message = format!("文件超过单文件预览上限（{limit_label}），无法在资源浏览器内读取");
        return Ok(json!({
            "relative_path": rel,
            "mime": mime,
            "size": size,
            "preview_kind": kind,
            "text": Value::Null,
            "bytes_base64": Value::Null,
            "note": message,
            "error": message,
        }));
    }
    let bytes = fs::read(&absolute).map_err(|error| format!("无法读取文件：{error}"))?;
    if kind == "text" {
        let text = String::from_utf8_lossy(&bytes).into_owned();
        return Ok(json!({
            "relative_path": rel,
            "mime": mime,
            "size": bytes.len(),
            "preview_kind": "text",
            "text": text,
            "bytes_base64": Value::Null,
            "note": Value::Null,
        }));
    }
    if kind == "pdf" && !bytes.starts_with(b"%PDF-") {
        return Ok(json!({
            "relative_path": rel,
            "mime": mime,
            "size": bytes.len(),
            "preview_kind": kind,
            "text": Value::Null,
            "bytes_base64": Value::Null,
            "note": Value::Null,
            "error": "PDF 文件内容无效或已损坏，无法预览",
        }));
    }
    Ok(json!({
        "relative_path": rel,
        "mime": mime,
        "size": bytes.len(),
        "preview_kind": kind,
        "text": Value::Null,
        "bytes_base64": BASE64.encode(&bytes),
        "note": Value::Null,
    }))
}

/// Read one explicitly selected UTF-8 source for the shared Markdown parser.
#[tauri::command]
fn folder_read_source(root: String, relative_path: String) -> Result<Value, String> {
    let root_path = PathBuf::from(root.trim());
    if !root_path.is_absolute() {
        return Err("导入文件夹必须是用户明确选择的绝对路径".into());
    }
    reject_symlink(&root_path, "导入文件夹")?;
    let root_meta =
        fs::symlink_metadata(&root_path).map_err(|error| format!("无法打开所选文件夹：{error}"))?;
    if root_meta.file_type().is_symlink() || !root_meta.is_dir() {
        return Err("Markdown源必须位于所选文件夹内".into());
    }
    let resolved_root =
        fs::canonicalize(&root_path).map_err(|error| format!("无法解析所选文件夹：{error}"))?;
    let rel = relative_path.trim().trim_start_matches(['/', '\\']);
    if rel.is_empty()
        || rel.contains('\0')
        || rel
            .split(['/', '\\'])
            .any(|part| part == ".." || part == ".")
    {
        return Err("导入源路径无效".into());
    }
    let mut absolute = resolved_root.clone();
    for part in rel.split(['/', '\\']).filter(|part| !part.is_empty()) {
        absolute.push(part);
        let meta = fs::symlink_metadata(&absolute)
            .map_err(|error| format!("无法读取Markdown源：{error}"))?;
        if meta.file_type().is_symlink() {
            return Err("Markdown源路径包含符号链接".into());
        }
    }
    let canonical =
        fs::canonicalize(&absolute).map_err(|error| format!("无法解析Markdown源：{error}"))?;
    if !canonical.starts_with(&resolved_root) {
        return Err("Markdown源超出所选文件夹".into());
    }
    let bytes = fs::read(&canonical).map_err(|error| format!("无法读取Markdown源：{error}"))?;
    let text =
        String::from_utf8(bytes.clone()).map_err(|_| "Markdown源必须是UTF-8文本".to_string())?;
    Ok(json!({
        "relative_path": rel,
        "size": bytes.len(),
        "sha256": sha256_hex(&bytes),
        "text": text,
    }))
}

#[tauri::command]
fn folder_markdown_image_status(
    root: String,
    markdown_relative_path: String,
    href: String,
) -> Result<Value, String> {
    let root_path = PathBuf::from(root.trim());
    if !root_path.is_absolute() {
        return Err("导入文件夹必须是用户明确选择的绝对路径".into());
    }
    reject_symlink(&root_path, "导入文件夹")?;
    let root_meta =
        fs::symlink_metadata(&root_path).map_err(|error| format!("无法打开所选文件夹：{error}"))?;
    if root_meta.file_type().is_symlink() || !root_meta.is_dir() {
        return Err("Markdown源必须位于所选文件夹内".into());
    }
    let resolved_root =
        fs::canonicalize(&root_path).map_err(|error| format!("无法解析所选文件夹：{error}"))?;
    let rel = markdown_relative_path
        .trim()
        .trim_start_matches(['/', '\\']);
    if rel.is_empty()
        || rel.contains('\0')
        || rel
            .split(['/', '\\'])
            .any(|part| part.is_empty() || part == ".." || part == ".")
    {
        return Err("导入源路径无效".into());
    }
    let mut markdown_path = resolved_root.clone();
    for part in rel.split(['/', '\\']) {
        markdown_path.push(part);
        let meta = fs::symlink_metadata(&markdown_path)
            .map_err(|error| format!("无法读取Markdown源：{error}"))?;
        if meta.file_type().is_symlink() {
            return Err("Markdown源路径包含符号链接".into());
        }
    }
    let canonical_markdown =
        fs::canonicalize(&markdown_path).map_err(|error| format!("无法解析Markdown源：{error}"))?;
    if !canonical_markdown.starts_with(&resolved_root)
        || !fs::metadata(&canonical_markdown)
            .map(|metadata| metadata.is_file())
            .unwrap_or(false)
    {
        return Err("Markdown源必须位于所选文件夹内".into());
    }

    match markdown_dependency_path(&resolved_root, rel, &href) {
        Ok(None) => Ok(json!({
            "status": "missing",
            "relative_path": Value::Null,
            "size": Value::Null,
            "mime": Value::Null,
        })),
        Ok(Some(path)) => match fs::metadata(&path) {
            Ok(metadata) if metadata.is_file() => Ok(json!({
                "status": "present",
                "relative_path": scan_relative(&resolved_root, &path)?,
                "size": metadata.len(),
                "mime": mime_for_filename(path.file_name().and_then(|name| name.to_str()).unwrap_or("")),
            })),
            Ok(_) => Ok(json!({
                "status": "unsafe",
                "relative_path": scan_relative(&resolved_root, &path).ok(),
                "size": Value::Null,
                "mime": Value::Null,
                "message": "图片依赖不是文件",
            })),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(json!({
                "status": "missing",
                "relative_path": Value::Null,
                "size": Value::Null,
                "mime": Value::Null,
            })),
            Err(_) => Ok(json!({
                "status": "error",
                "relative_path": scan_relative(&resolved_root, &path).ok(),
                "size": Value::Null,
                "mime": Value::Null,
                "message": "无法读取图片依赖信息",
            })),
        },
        Err(message) => {
            let unsafe_path = [
                "Markdown图片引用必须是所选目录内的相对路径",
                "Markdown图片路径编码无效",
                "Markdown图片路径无效",
                "Markdown图片引用超出所选目录",
                "Markdown图片依赖不能经过符号链接",
                "Markdown图片依赖超出所选目录或不是文件",
            ]
            .iter()
            .any(|prefix| message.starts_with(prefix));
            Ok(json!({
                "status": if unsafe_path { "unsafe" } else { "error" },
                "relative_path": Value::Null,
                "size": Value::Null,
                "mime": Value::Null,
                "message": message,
            }))
        }
    }
}

/// Strategy A in-place adoption after confirm (§§32–35).
/// Writes project.json + .workspace into the chosen folder; copies media into
/// assets/. Never moves/renames/deletes original user files.
///
/// Flat `{ plan, duplicate_choice?, project_title?, replace_invalid_project? }`
/// payload — same pattern as `folder_scan` / `folder_read_preview`. Do **not**
/// require `{ input: ... }` nesting; adoption runs before an open projectDir exists.
///
/// `replace_invalid_project` is §3.2 Case C: the user confirmed that the folder's
/// existing `project.json` is unusable and chose to re-import it. It never
/// licenses overwriting a readable project.
#[tauri::command]
fn folder_adopt(
    plan: Value,
    duplicate_choice: Option<String>,
    project_title: Option<String>,
    replace_invalid_project: Option<bool>,
) -> Result<Value, String> {
    folder_apply_import(
        plan,
        duplicate_choice,
        project_title,
        None,
        replace_invalid_project.unwrap_or(false),
    )
}

/// Append an explicitly confirmed mapping into the already open Canonical project.
/// The active lease remains held until media and the final manifest commit finish.
#[tauri::command]
fn folder_append(
    plan: Value,
    project_dir: String,
    duplicate_choice: Option<String>,
) -> Result<Value, String> {
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let _lease_guard = require_active_project_lock(&project_dir)?;
    let append_context =
        canonical_append_context(&project_dir, None, None, None, None, None, None)?;
    validate_project(&append_context.project)?;
    folder_apply_import(plan, duplicate_choice, None, Some(append_context), false)
}

/// Native command paired with the direct-child document chooser. The checked
/// paths remain separate from the confirmed root plan and are revalidated here.
#[tauri::command]
fn folder_adopt_with_documents(
    plan: Value,
    duplicate_choice: Option<String>,
    project_title: Option<String>,
    replace_invalid_project: Option<bool>,
    document_paths: Option<Vec<String>>,
    editor_generation: Option<u64>,
    operation_id: Option<String>,
    revision: Option<u64>,
) -> Result<Value, String> {
    let adoption_echo = adoption_operation_echo(editor_generation, operation_id, revision)?;
    let mut result = folder_apply_import_with_documents(
        plan,
        duplicate_choice,
        project_title,
        None,
        replace_invalid_project.unwrap_or(false),
        document_paths.as_deref().unwrap_or_default(),
    )?;
    if let Some(echo) = adoption_echo {
        result["mutation_ack"]["editor_generation"] = json!(echo.editor_generation);
        result["mutation_ack"]["operation_id"] = json!(echo.operation_id);
        result["mutation_ack"]["revision"] = json!(echo.revision);
    }
    Ok(result)
}

#[derive(Clone)]
struct AdoptionOperationEcho {
    editor_generation: u64,
    operation_id: String,
    revision: u64,
}

fn adoption_operation_echo(
    editor_generation: Option<u64>,
    operation_id: Option<String>,
    revision: Option<u64>,
) -> Result<Option<AdoptionOperationEcho>, String> {
    match (editor_generation, operation_id, revision) {
        (None, None, None) => Ok(None),
        (Some(editor_generation), Some(operation_id), Some(revision))
            if !operation_id.trim().is_empty() && valid_snapshot_id(&operation_id) =>
        {
            Ok(Some(AdoptionOperationEcho {
                editor_generation,
                operation_id,
                revision,
            }))
        }
        _ => Err(invalid_mutation_binding_error(
            "folder.adopt 需要完整且有效的编辑操作回显字段。",
        )),
    }
}

#[tauri::command]
fn folder_append_with_documents(
    plan: Value,
    project_dir: String,
    duplicate_choice: Option<String>,
    document_paths: Option<Vec<String>>,
    expected_project_id: Option<String>,
    expected_fingerprint: Option<FileFingerprint>,
    lease_generation: Option<String>,
    editor_generation: Option<u64>,
    operation_id: Option<String>,
    revision: Option<u64>,
) -> Result<Value, String> {
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let _lease_guard = require_active_project_lock(&project_dir)?;
    let append_context = canonical_append_context(
        &project_dir,
        expected_project_id,
        expected_fingerprint,
        lease_generation,
        editor_generation,
        operation_id,
        revision,
    )?;
    validate_project(&append_context.project)?;
    folder_apply_import_with_documents(
        plan,
        duplicate_choice,
        None,
        Some(append_context),
        false,
        document_paths.as_deref().unwrap_or_default(),
    )
}

fn local_markdown_image_href(href: &str) -> bool {
    let value = href.trim();
    if value.is_empty()
        || value.starts_with('#')
        || value.starts_with("//")
        || value.chars().any(|character| character.is_control())
    {
        return false;
    }
    let Some((scheme, _)) = value.split_once(':') else {
        return true;
    };
    let mut chars = scheme.chars();
    let scheme = chars
        .next()
        .map(|first| first.is_ascii_alphabetic())
        .unwrap_or(false)
        && chars.all(|character| {
            character.is_ascii_alphanumeric() || matches!(character, '+' | '.' | '-')
        })
        && !scheme.is_empty()
        && value.find(':').unwrap_or(0) == scheme.len();
    !scheme
}

/// Independently verify image refs against the source with the app's GFM-relevant
/// CommonMark extensions. The frontend parser still owns block projection; Rust
/// refuses any dependency href or occurrence absent from its own source parse.
fn verify_markdown_image_refs(
    source: &str,
    parsed_blocks: &Value,
    refs: &[Value],
) -> Result<(), String> {
    let options = MarkdownOptions::ENABLE_TABLES
        | MarkdownOptions::ENABLE_STRIKETHROUGH
        | MarkdownOptions::ENABLE_TASKLISTS;
    let mut expected = Vec::new();
    let mut occurrences: HashMap<String, u64> = HashMap::new();
    let mut token_index = 0_u64;
    for event in MarkdownParser::new_ext(source, options) {
        let MarkdownEvent::Start(MarkdownTag::Image { dest_url, .. }) = event else {
            continue;
        };
        let href = dest_url.to_string();
        let occurrence = *occurrences.get(&href).unwrap_or(&0);
        occurrences.insert(href.clone(), occurrence + 1);
        if local_markdown_image_href(&href) {
            expected.push((href, token_index, occurrence));
        }
        token_index += 1;
    }
    let blocks = parsed_blocks
        .as_array()
        .ok_or("Markdown解析结果缺少blocks")?;
    if refs.len() != expected.len() {
        return Err("Markdown图片解析结果不一致，请重新打开映射预览".into());
    }
    for (index, (reference, (expected_href, expected_token, expected_occurrence))) in
        refs.iter().zip(expected.iter()).enumerate()
    {
        let href = reference.get("href").and_then(Value::as_str).unwrap_or("");
        let token_index = reference.get("tokenIndex").and_then(Value::as_u64);
        let occurrence = reference.get("occurrence").and_then(Value::as_u64);
        let block_index = reference
            .get("blockIndex")
            .and_then(Value::as_u64)
            .and_then(|value| usize::try_from(value).ok());
        if href != expected_href
            || token_index != Some(*expected_token)
            || occurrence != Some(*expected_occurrence)
            || !local_markdown_image_href(href)
        {
            return Err("Markdown图片解析结果不一致，请重新打开映射预览".into());
        }
        let Some(block_index) = block_index.filter(|value| *value < blocks.len()) else {
            return Err("Markdown图片引用指向无效区块".into());
        };
        let in_block = blocks[block_index]
            .get("imageRefs")
            .and_then(Value::as_array)
            .map(|images| {
                images.iter().any(|image| {
                    image.get("href").and_then(Value::as_str) == Some(href)
                        && image.get("tokenIndex").and_then(Value::as_u64) == Some(*expected_token)
                        && image.get("occurrence").and_then(Value::as_u64)
                            == Some(*expected_occurrence)
                })
            })
            .unwrap_or(false);
        if !in_block {
            return Err(format!("Markdown图片解析区块不一致（引用 {}）", index + 1));
        }
    }
    Ok(())
}

#[derive(Default)]
struct MarkdownImportBlock {
    start: usize,
    end: usize,
    kind: String,
    level: Option<u64>,
    language: Option<String>,
    checked: Option<bool>,
    code_text: String,
    image_refs: Vec<Value>,
}

fn markdown_heading_level(level: pulldown_cmark::HeadingLevel) -> u64 {
    match level {
        pulldown_cmark::HeadingLevel::H1 => 1,
        pulldown_cmark::HeadingLevel::H2 => 2,
        pulldown_cmark::HeadingLevel::H3 => 3,
        pulldown_cmark::HeadingLevel::H4 => 4,
        pulldown_cmark::HeadingLevel::H5 => 5,
        pulldown_cmark::HeadingLevel::H6 => 6,
    }
}

fn markdown_import_block(source: &str, block: MarkdownImportBlock) -> Value {
    let start = block.start.min(source.len());
    let end = block.end.max(start).min(source.len());
    let raw = source.get(start..end).unwrap_or_default();
    let trimmed = raw.trim_end_matches(['\r', '\n']);
    let text = match block.kind.as_str() {
        "heading" => {
            let first = trimmed.lines().next().unwrap_or_default().trim_start();
            let hashes = first
                .chars()
                .take_while(|character| *character == '#')
                .count();
            if (1..=6).contains(&hashes) {
                first[hashes..]
                    .trim_start()
                    .trim_end_matches('#')
                    .trim_end()
                    .to_owned()
            } else {
                first.to_owned()
            }
        }
        "quote" => trimmed
            .lines()
            .map(|line| {
                let line = line.trim_start();
                line.strip_prefix('>')
                    .map(|value| value.strip_prefix(' ').unwrap_or(value))
                    .unwrap_or(line)
            })
            .collect::<Vec<_>>()
            .join("\n"),
        "code" => block.code_text.trim_end_matches(['\r', '\n']).to_owned(),
        "divider" => String::new(),
        "table" => raw.to_owned(),
        "list" | "paragraph" | "html" | "other" => trimmed.to_owned(),
        _ => trimmed.to_owned(),
    };
    json!({
        "type": block.kind,
        "raw": trimmed,
        "text": text,
        "level": block.level,
        "language": block.language,
        "checked": block.checked,
        "imageRefs": block.image_refs,
    })
}

/// Native Markdown counterpart to the shell's `parseMarkdown()`. It projects
/// only the selected source file at import time and retains GFM block order and
/// exact source slices for lists, tables, paragraphs and raw HTML.
fn parse_native_markdown(source: &str) -> Result<Value, String> {
    if source.len() > documents::MAX_SOURCE_BYTES {
        return Err("Markdown文件超过可解析大小上限".into());
    }
    let options = MarkdownOptions::ENABLE_TABLES
        | MarkdownOptions::ENABLE_STRIKETHROUGH
        | MarkdownOptions::ENABLE_TASKLISTS;
    let mut blocks = Vec::new();
    let mut all_refs = Vec::new();
    let mut local_refs = Vec::new();
    let mut occurrences: HashMap<String, u64> = HashMap::new();
    let mut token_index = 0_u64;
    let mut current: Option<MarkdownImportBlock> = None;
    let mut depth = 0_usize;
    let mut image: Option<(String, Option<String>, String, usize)> = None;
    let mut saw_html = false;

    for (event, range) in MarkdownParser::new_ext(source, options).into_offset_iter() {
        match &event {
            MarkdownEvent::Start(tag) => {
                if current.is_none() {
                    let (kind, level, language) = match tag {
                        MarkdownTag::Heading { level, .. } => {
                            ("heading", Some(markdown_heading_level(*level)), None)
                        }
                        MarkdownTag::Paragraph => ("paragraph", None, None),
                        MarkdownTag::BlockQuote(_) => ("quote", None, None),
                        MarkdownTag::CodeBlock(kind) => {
                            let language = match kind {
                                pulldown_cmark::CodeBlockKind::Fenced(info) => info
                                    .split(|character: char| {
                                        character.is_whitespace() || character == ','
                                    })
                                    .next()
                                    .filter(|value| !value.is_empty())
                                    .map(str::to_owned),
                                pulldown_cmark::CodeBlockKind::Indented => None,
                            };
                            ("code", None, language)
                        }
                        MarkdownTag::List(_) => ("list", None, None),
                        MarkdownTag::Table(_) => ("table", None, None),
                        MarkdownTag::HtmlBlock => ("html", None, None),
                        _ => ("other", None, None),
                    };
                    current = Some(MarkdownImportBlock {
                        start: range.start,
                        end: range.end,
                        kind: kind.to_owned(),
                        level,
                        language,
                        ..Default::default()
                    });
                    depth = 1;
                } else {
                    depth += 1;
                }
                if let MarkdownTag::Image {
                    dest_url, title, ..
                } = tag
                {
                    image = Some((
                        dest_url.to_string(),
                        (!title.is_empty()).then(|| title.to_string()),
                        String::new(),
                        blocks.len(),
                    ));
                }
            }
            MarkdownEvent::End(pulldown_cmark::TagEnd::Image) => {
                if let Some((href, title, alt, block_index)) = image.take() {
                    let occurrence = *occurrences.get(&href).unwrap_or(&0);
                    occurrences.insert(href.clone(), occurrence + 1);
                    let reference = json!({
                        "href": href,
                        "title": title,
                        "alt": alt,
                        "tokenIndex": token_index,
                        "occurrence": occurrence,
                        "blockIndex": block_index,
                    });
                    token_index += 1;
                    if local_markdown_image_href(&href) {
                        local_refs.push(reference.clone());
                        if let Some(block) = current.as_mut() {
                            block.image_refs.push(json!({
                                "href": href,
                                "title": title,
                                "alt": alt,
                                "tokenIndex": token_index - 1,
                                "occurrence": occurrence,
                            }));
                        }
                    }
                    all_refs.push(reference);
                }
            }
            MarkdownEvent::TaskListMarker(checked) => {
                if let Some(block) = current.as_mut() {
                    block.checked = Some(block.checked.unwrap_or(false) || *checked);
                }
            }
            MarkdownEvent::Text(value) if image.is_some() => {
                if let Some((_, _, alt, _)) = image.as_mut() {
                    alt.push_str(value);
                }
            }
            MarkdownEvent::Code(value) if image.is_some() => {
                if let Some((_, _, alt, _)) = image.as_mut() {
                    alt.push_str(value);
                }
            }
            MarkdownEvent::Text(value)
                if current.as_ref().is_some_and(|block| block.kind == "code") =>
            {
                if let Some(block) = current.as_mut() {
                    block.code_text.push_str(value);
                }
            }
            MarkdownEvent::Rule if current.is_none() => {
                blocks.push(markdown_import_block(
                    source,
                    MarkdownImportBlock {
                        start: range.start,
                        end: range.end,
                        kind: "divider".to_owned(),
                        ..Default::default()
                    },
                ));
            }
            MarkdownEvent::Html(_) | MarkdownEvent::InlineHtml(_) => saw_html = true,
            _ => {}
        }

        if let Some(block) = current.as_mut() {
            block.end = block.end.max(range.end);
        }

        if let MarkdownEvent::End(_) = event {
            if depth > 0 {
                depth -= 1;
                if depth == 0 {
                    if let Some(block) = current.take() {
                        blocks.push(markdown_import_block(source, block));
                    }
                }
            }
        }
    }
    if let Some(block) = current.take() {
        blocks.push(markdown_import_block(source, block));
    }

    let warnings = if saw_html {
        vec!["Markdown 中的原始 HTML 按纯文本显示，不会执行。"]
    } else {
        Vec::<&str>::new()
    };
    Ok(json!({
        "blocks": blocks,
        "imageRefs": all_refs,
        "explicitLocalImageRefs": local_refs,
        "warnings": warnings,
    }))
}

fn markdown_dependency_path(
    source_root: &Path,
    markdown_rel: &str,
    href: &str,
) -> Result<Option<PathBuf>, String> {
    let href = href.trim();
    if href.is_empty()
        || href.starts_with('/')
        || href.starts_with('\\')
        || href.contains(':')
        || href.starts_with("//")
    {
        return Err("Markdown图片引用必须是所选目录内的相对路径".into());
    }
    let path_part = href.split(['?', '#']).next().unwrap_or_default();
    let decoded = ai_percent_decode(path_part).ok_or("Markdown图片路径编码无效")?;
    if decoded.is_empty() || decoded.contains('\0') || decoded.contains('\\') {
        return Err("Markdown图片路径无效".into());
    }
    let mut relative = PathBuf::new();
    let parent = Path::new(markdown_rel)
        .parent()
        .unwrap_or_else(|| Path::new(""));
    for component in parent.join(decoded).components() {
        match component {
            Component::CurDir => {}
            Component::ParentDir => {
                if !relative.pop() {
                    return Err("Markdown图片引用超出所选目录".into());
                }
            }
            Component::Normal(value) => relative.push(value),
            _ => return Err("Markdown图片路径无效".into()),
        }
    }
    if relative.as_os_str().is_empty() {
        return Err("Markdown图片路径无效".into());
    }
    let mut candidate = source_root.to_path_buf();
    for component in relative.components() {
        let Component::Normal(value) = component else {
            continue;
        };
        candidate.push(value);
        let metadata = match fs::symlink_metadata(&candidate) {
            Ok(value) => value,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
            Err(error) => return Err(format!("无法读取Markdown图片依赖：{error}")),
        };
        if metadata.file_type().is_symlink() {
            return Err("Markdown图片依赖不能经过符号链接".into());
        }
    }
    let canonical = match fs::canonicalize(&candidate) {
        Ok(value) => value,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(format!("无法解析Markdown图片依赖：{error}")),
    };
    if !canonical.starts_with(source_root)
        || !fs::metadata(&canonical)
            .map(|m| m.is_file())
            .unwrap_or(false)
    {
        return Err("Markdown图片依赖超出所选目录或不是文件".into());
    }
    Ok(Some(canonical))
}

struct AdoptStagingGuard(PathBuf);

impl Drop for AdoptStagingGuard {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

struct MarkdownSourceMatch {
    state: &'static str,
    title: String,
    previous_hash: String,
    target_deleted: bool,
}

fn find_markdown_source_match(
    project: &Value,
    source_root: &Path,
    relative_path: &str,
    checksum: &str,
) -> Option<MarkdownSourceMatch> {
    let project_id = project.get("project")?.get("id")?.as_str()?;
    let documents = project.get("documents")?.as_array()?;
    let content_items = project.get("content_items")?.as_array()?;
    let blocks = project.get("blocks")?.as_array()?;
    let canonical_root = source_root.to_string_lossy();
    let mut changed_ledger_entry: Option<(String, MarkdownSourceMatch)> = None;
    if let Some(ledger) = project
        .get("project")
        .and_then(|value| value.get("settings"))
        .and_then(|value| value.get("markdown_import_sources"))
        .and_then(Value::as_array)
    {
        for source in ledger {
            let (Some(prior_root), Some(prior_path), Some(prior_hash), Some(content_id)) = (
                source.get("source_root").and_then(Value::as_str),
                source.get("relative_path").and_then(Value::as_str),
                source.get("source_hash").and_then(Value::as_str),
                source.get("content_item_id").and_then(Value::as_str),
            ) else {
                continue;
            };
            if content_id.is_empty()
                || prior_root.is_empty()
                || prior_path.is_empty()
                || prior_hash.len() != 64
                || !prior_hash.bytes().all(|byte| byte.is_ascii_hexdigit())
            {
                continue;
            }
            let content_item = content_items
                .iter()
                .find(|item| item.get("id").and_then(Value::as_str) == Some(content_id));
            if content_item.is_some_and(|item| {
                item.get("project_id").and_then(Value::as_str) != Some(project_id)
                    || item.get("type").and_then(Value::as_str) != Some("lesson")
            }) {
                continue;
            }
            let title = content_item
                .and_then(|item| item.get("title"))
                .and_then(Value::as_str)
                .or_else(|| source.get("title").and_then(Value::as_str))
                .unwrap_or("已删除的课时")
                .to_owned();
            let matched = MarkdownSourceMatch {
                state: "changed_source",
                title,
                previous_hash: prior_hash.to_owned(),
                target_deleted: content_item.is_none(),
            };
            if prior_hash == checksum {
                return Some(MarkdownSourceMatch {
                    state: "same_content",
                    ..matched
                });
            }
            if prior_root == canonical_root.as_ref() && prior_path == relative_path {
                let imported_at = source
                    .get("imported_at")
                    .and_then(Value::as_str)
                    .unwrap_or("")
                    .to_owned();
                let is_latest = changed_ledger_entry
                    .as_ref()
                    .map(|(latest, _)| imported_at.as_str() >= latest.as_str())
                    .unwrap_or(true);
                if is_latest {
                    changed_ledger_entry = Some((imported_at, matched));
                }
            }
        }
    }
    if let Some((_, matched)) = changed_ledger_entry {
        return Some(matched);
    }
    let mut changed_source = None;
    for block in blocks {
        let Some(source) = block
            .get("settings")
            .and_then(|settings| settings.get("markdown_import"))
        else {
            continue;
        };
        let (Some(prior_root), Some(prior_path), Some(prior_hash), Some(document_id)) = (
            source.get("source_root").and_then(Value::as_str),
            source.get("relative_path").and_then(Value::as_str),
            source.get("source_hash").and_then(Value::as_str),
            block.get("document_id").and_then(Value::as_str),
        ) else {
            continue;
        };
        let Some(content_id) = documents.iter().find_map(|document| {
            (document.get("id").and_then(Value::as_str) == Some(document_id))
                .then(|| document.get("content_item_id").and_then(Value::as_str))
                .flatten()
        }) else {
            continue;
        };
        let Some(content_item) = content_items.iter().find(|item| {
            item.get("id").and_then(Value::as_str) == Some(content_id)
                && item.get("project_id").and_then(Value::as_str) == Some(project_id)
                && item.get("type").and_then(Value::as_str) == Some("lesson")
                && !item
                    .get("archived")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
        }) else {
            continue;
        };
        let title = content_item
            .get("title")
            .and_then(Value::as_str)
            .unwrap_or("未命名课时");
        let matched = MarkdownSourceMatch {
            state: "same_content",
            title: title.to_owned(),
            previous_hash: prior_hash.to_owned(),
            target_deleted: false,
        };
        if prior_hash == checksum {
            return Some(matched);
        }
        if prior_root == canonical_root.as_ref()
            && prior_path == relative_path
            && changed_source.is_none()
        {
            changed_source = Some(MarkdownSourceMatch {
                state: "changed_source",
                title: title.to_owned(),
                previous_hash: prior_hash.to_owned(),
                target_deleted: false,
            });
        }
    }
    changed_source
}

struct AdoptLessonDestination {
    existing_lesson_id: Option<String>,
    stage_id: Option<String>,
}

fn adopt_lesson_destination(
    project: &Value,
    project_id: &str,
    item: &Value,
    fallback_stage_id: Option<String>,
) -> Result<AdoptLessonDestination, String> {
    let Some(destination) = item.get("destination").filter(|value| !value.is_null()) else {
        return Ok(AdoptLessonDestination {
            existing_lesson_id: None,
            stage_id: fallback_stage_id,
        });
    };
    let kind = destination
        .get("kind")
        .and_then(Value::as_str)
        .unwrap_or("");
    match kind {
        "unassigned_lesson" => Ok(AdoptLessonDestination {
            existing_lesson_id: None,
            stage_id: None,
        }),
        "existing_stage" => {
            let stage_id = destination
                .get("stage_id")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .ok_or("导入目标阶段缺少ID")?;
            let exists = project
                .get("stages")
                .and_then(Value::as_array)
                .map(|stages| {
                    stages.iter().any(|stage| {
                        stage.get("id").and_then(Value::as_str) == Some(stage_id)
                            && stage.get("project_id").and_then(Value::as_str) == Some(project_id)
                            && !stage
                                .get("archived")
                                .and_then(Value::as_bool)
                                .unwrap_or(false)
                    })
                })
                .unwrap_or(false);
            if !exists {
                return Err("导入目标阶段不属于当前课程或已不可用；请刷新目标列表后重试。".into());
            }
            Ok(AdoptLessonDestination {
                existing_lesson_id: None,
                stage_id: Some(stage_id.to_owned()),
            })
        }
        "existing_lesson" => {
            let content_item_id = destination
                .get("content_item_id")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .ok_or("导入目标课时缺少ID")?;
            let content_item = project
                .get("content_items")
                .and_then(Value::as_array)
                .and_then(|items| {
                    items.iter().find(|content| {
                        content.get("id").and_then(Value::as_str) == Some(content_item_id)
                            && content.get("project_id").and_then(Value::as_str) == Some(project_id)
                            && content.get("type").and_then(Value::as_str) == Some("lesson")
                            && !content
                                .get("archived")
                                .and_then(Value::as_bool)
                                .unwrap_or(false)
                    })
                })
                .ok_or("导入目标课时不属于当前课程或已不可用；请刷新目标列表后重试。")?;
            let document_id = content_item
                .get("document_id")
                .and_then(Value::as_str)
                .ok_or("目标课时正文文档无效，无法安全追加")?;
            let valid_document = project
                .get("documents")
                .and_then(Value::as_array)
                .map(|documents| {
                    documents.iter().any(|document| {
                        document.get("id").and_then(Value::as_str) == Some(document_id)
                            && document.get("content_item_id").and_then(Value::as_str)
                                == Some(content_item_id)
                    })
                })
                .unwrap_or(false);
            if !valid_document {
                return Err("目标课时正文文档无效，无法安全追加".into());
            }
            Ok(AdoptLessonDestination {
                existing_lesson_id: Some(content_item_id.to_owned()),
                stage_id: content_item
                    .get("stage_id")
                    .and_then(Value::as_str)
                    .map(ToOwned::to_owned),
            })
        }
        _ => Err("导入目标类型无效；请重新选择目标后重试。".into()),
    }
}

fn adopt_append_text_lesson(
    project: &mut Value,
    content_id: &str,
    text: &str,
) -> Result<(), String> {
    let document_id = project
        .get("content_items")
        .and_then(Value::as_array)
        .and_then(|items| {
            items
                .iter()
                .find(|item| item.get("id").and_then(Value::as_str) == Some(content_id))
        })
        .and_then(|item| item.get("document_id").and_then(Value::as_str))
        .ok_or("目标课时正文文档无效，无法安全追加")?
        .to_owned();
    let blocks = project
        .get_mut("blocks")
        .and_then(Value::as_array_mut)
        .ok_or("blocks 无效")?;
    let order_index = blocks
        .iter()
        .filter(|block| block.get("document_id").and_then(Value::as_str) == Some(&document_id))
        .count();
    blocks.push(json!({
        "id": uuid_v4()?,
        "document_id": document_id,
        "parent_block_id": Value::Null,
        "type": "paragraph",
        "order_index": order_index,
        "content": text,
        "settings": {},
        "created_at": rfc3339_now(),
        "updated_at": rfc3339_now(),
    }));
    Ok(())
}

fn adopt_markdown_blocks(
    project: &mut Value,
    content_id: &str,
    parsed_blocks: &Value,
    assets_by_block: &HashMap<usize, Vec<Value>>,
    source_provenance: Option<&Value>,
) -> Result<(), String> {
    let values = parsed_blocks
        .as_array()
        .ok_or("Markdown解析结果缺少blocks")?;
    let document_id = project
        .get("content_items")
        .and_then(Value::as_array)
        .and_then(|items| {
            items
                .iter()
                .find(|item| item["id"].as_str() == Some(content_id))
        })
        .and_then(|item| item["document_id"].as_str())
        .ok_or("Markdown课时缺少文档")?
        .to_owned();
    let blocks = project
        .get_mut("blocks")
        .and_then(Value::as_array_mut)
        .ok_or("blocks无效")?;
    let mut pending_usages: Vec<(String, String)> = Vec::new();
    for (index, value) in values.iter().enumerate() {
        let raw_type = value.get("type").and_then(Value::as_str).unwrap_or("other");
        let raw = value.get("raw").and_then(Value::as_str).unwrap_or("");
        let text = value.get("text").and_then(Value::as_str).unwrap_or(raw);
        if raw.len() > 2_000_000 || text.len() > 2_000_000 {
            return Err("Markdown区块超过可导入大小限制".into());
        }
        let (block_type, content) = match raw_type {
            "heading" => ("heading", text.to_owned()),
            "paragraph" => ("paragraph", text.to_owned()),
            "quote" => ("quote", text.to_owned()),
            "code" => ("code", text.to_owned()),
            "divider" => ("divider", String::new()),
            "table" => ("table", raw.to_owned()),
            "list" | "html" | "other" => ("paragraph", raw.to_owned()),
            _ => return Err("Markdown解析结果包含未知区块类型".into()),
        };
        let mut settings = json!({});
        if block_type == "heading" {
            let level = value
                .get("level")
                .and_then(Value::as_u64)
                .unwrap_or(1)
                .clamp(1, 6);
            settings["level"] = json!(level);
        }
        if block_type == "code" {
            if let Some(language) = value
                .get("language")
                .and_then(Value::as_str)
                .filter(|s| !s.is_empty())
            {
                settings["language"] = json!(language);
            }
        }
        if let Some(assets) = assets_by_block.get(&index) {
            settings["markdown_assets"] = Value::Array(assets.clone());
        }
        if index == 0 {
            if let Some(provenance) = source_provenance {
                settings["markdown_import"] = provenance.clone();
            }
        }
        let block_id = uuid_v4()?;
        let order_index = blocks
            .iter()
            .filter(|block| {
                block.get("document_id").and_then(Value::as_str) == Some(document_id.as_str())
            })
            .count();
        blocks.push(json!({
            "id": block_id,
            "document_id": document_id.clone(),
            "parent_block_id": Value::Null,
            "type": block_type,
            "order_index": order_index,
            "content": content,
            "settings": settings,
            "created_at": rfc3339_now(),
            "updated_at": rfc3339_now(),
        }));
        if let Some(assets) = assets_by_block.get(&index) {
            for asset in assets {
                if let Some(asset_id) = asset.get("asset_id").and_then(Value::as_str) {
                    pending_usages.push((block_id.clone(), asset_id.to_owned()));
                }
            }
        }
    }
    if values.is_empty() {
        if let Some(provenance) = source_provenance {
            let block_id = uuid_v4()?;
            let order_index = blocks
                .iter()
                .filter(|block| {
                    block.get("document_id").and_then(Value::as_str) == Some(document_id.as_str())
                })
                .count();
            blocks.push(json!({
                "id": block_id,
                "document_id": document_id.clone(),
                "parent_block_id": Value::Null,
                "type": "paragraph",
                "order_index": order_index,
                "content": "",
                "settings": { "markdown_import": provenance },
                "created_at": rfc3339_now(),
                "updated_at": rfc3339_now(),
            }));
        }
    }
    for (block_id, asset_id) in pending_usages {
        let input =
            json!({ "content_item_id": content_id, "block_id": block_id, "role": "content" });
        append_asset_usage(
            project,
            input.as_object().ok_or("素材引用格式无效")?,
            &asset_id,
        )?;
    }
    let updated_at = rfc3339_now();
    if let Some(document) = project
        .get_mut("documents")
        .and_then(Value::as_array_mut)
        .and_then(|documents| {
            documents.iter_mut().find(|document| {
                document.get("id").and_then(Value::as_str) == Some(document_id.as_str())
            })
        })
    {
        document["updated_at"] = json!(updated_at);
    }
    if let Some(content_item) = project
        .get_mut("content_items")
        .and_then(Value::as_array_mut)
        .and_then(|items| {
            items
                .iter_mut()
                .find(|item| item.get("id").and_then(Value::as_str) == Some(content_id))
        })
    {
        content_item["updated_at"] = json!(updated_at);
    }
    if let Some(project_object) = project.get_mut("project") {
        project_object["updated_at"] = json!(updated_at);
    }
    Ok(())
}

fn record_markdown_import_source(
    project: &mut Value,
    content_id: &str,
    title: &str,
    provenance: &Value,
) -> Result<(), String> {
    let settings = project
        .get_mut("project")
        .and_then(Value::as_object_mut)
        .ok_or("项目缺少project对象")?
        .entry("settings")
        .or_insert_with(|| json!({}))
        .as_object_mut()
        .ok_or("项目settings无效")?;
    let ledger = settings
        .entry("markdown_import_sources")
        .or_insert_with(|| json!([]))
        .as_array_mut()
        .ok_or("Markdown导入来源记录无效")?;
    let source_root = provenance
        .get("source_root")
        .and_then(Value::as_str)
        .unwrap_or("");
    let relative_path = provenance
        .get("relative_path")
        .and_then(Value::as_str)
        .unwrap_or("");
    let source_hash = provenance
        .get("source_hash")
        .and_then(Value::as_str)
        .unwrap_or("");
    if ledger.iter().any(|entry| {
        entry.get("source_root").and_then(Value::as_str) == Some(source_root)
            && entry.get("relative_path").and_then(Value::as_str) == Some(relative_path)
            && entry.get("source_hash").and_then(Value::as_str) == Some(source_hash)
            && entry.get("content_item_id").and_then(Value::as_str) == Some(content_id)
    }) {
        return Ok(());
    }
    let mut record = provenance.clone();
    record["content_item_id"] = json!(content_id);
    record["title"] = json!(title);
    record["imported_at"] = json!(rfc3339_now());
    ledger.push(record);
    Ok(())
}

/// §28 outcome of one text/document file inside an import batch. These four
/// strings are the frontend contract for `document_import.files[*].outcome`.
#[derive(Clone, Copy, PartialEq, Eq)]
enum DocumentOutcome {
    /// Imported with all the structure the source actually carries.
    Succeeded,
    /// Imported, but structure was lost (math stored as code, unknown macros kept
    /// verbatim, an unsupported filter, an embedded image that could not resolve).
    Degraded,
    /// Deliberately not imported (duplicate by SHA-256, no usable text layer,
    /// unchecked by the user, or refused by a containment check).
    Skipped,
    /// The file could not be read, parsed or committed.
    Failed,
}

impl DocumentOutcome {
    fn as_str(self) -> &'static str {
        match self {
            Self::Succeeded => "succeeded",
            Self::Degraded => "degraded",
            Self::Skipped => "skipped",
            Self::Failed => "failed",
        }
    }
}

/// The per-file tally `folder_apply_import` returns as `document_import`, so both
/// `folder.adopt` and `folder.append` expose it. Counts are always derived from
/// `files`, never incremented separately, so they cannot drift apart.
#[derive(Default)]
struct DocumentImportTally {
    files: Vec<Value>,
}

impl DocumentImportTally {
    fn record(&mut self, relative_path: &str, outcome: DocumentOutcome, reason: &str) {
        self.files.push(json!({
            "relative_path": relative_path,
            "outcome": outcome.as_str(),
            "reason": reason,
        }));
    }

    /// Only rows the text/document pipeline owns are tallied: a listed file whose
    /// extension the parser layer supports. Media (image / video) never enters it.
    fn record_file(
        &mut self,
        kind: &str,
        relative_path: &str,
        filename: &str,
        outcome: DocumentOutcome,
        reason: &str,
    ) {
        if !ADOPTABLE_FILE_KINDS.contains(&kind) || !documents::is_supported_document(filename) {
            return;
        }
        self.record(relative_path, outcome, reason);
    }

    fn count(&self, outcome: DocumentOutcome) -> usize {
        self.files
            .iter()
            .filter(|entry| entry["outcome"] == json!(outcome.as_str()))
            .count()
    }

    fn to_value(&self) -> Value {
        json!({
            "succeeded": self.count(DocumentOutcome::Succeeded),
            "degraded": self.count(DocumentOutcome::Degraded),
            "skipped": self.count(DocumentOutcome::Skipped),
            "failed": self.count(DocumentOutcome::Failed),
            "files": self.files,
        })
    }
}

/// The mutable state one import transaction accumulates. Grouping it lets a
/// single file be rolled back (§28) without threading eight `&mut` arguments
/// through every helper.
#[derive(Default)]
struct AdoptAccumulator {
    warnings: Vec<String>,
    stage_ids: Vec<String>,
    content_item_ids: Vec<String>,
    asset_ids: Vec<String>,
    source_ids: Vec<String>,
    reused_asset_ids: Vec<String>,
    copied_files: Vec<String>,
    staged_pairs: Vec<(String, String)>,
}

/// Everything a single file item may append, captured before it is processed so a
/// failure leaves no half-imported lesson, asset, usage or provenance record.
struct AdoptItemSnapshot {
    stages: usize,
    content_items: usize,
    documents: usize,
    blocks: usize,
    assets: usize,
    asset_usages: usize,
    inbox_items: usize,
    ledger: usize,
    warnings: usize,
    content_item_ids: usize,
    asset_ids: usize,
    source_ids: usize,
    reused_asset_ids: usize,
    copied_files: usize,
    staged_pairs: usize,
}

impl AdoptItemSnapshot {
    fn capture(project: &Value, acc: &AdoptAccumulator) -> Self {
        let length = |key: &str| {
            project
                .get(key)
                .and_then(Value::as_array)
                .map(Vec::len)
                .unwrap_or(0)
        };
        Self {
            stages: length("stages"),
            content_items: length("content_items"),
            documents: length("documents"),
            blocks: length("blocks"),
            assets: length("assets"),
            asset_usages: length("asset_usages"),
            inbox_items: length("inbox_items"),
            ledger: project
                .get("project")
                .and_then(|value| value.get("settings"))
                .and_then(|value| value.get("markdown_import_sources"))
                .and_then(Value::as_array)
                .map(Vec::len)
                .unwrap_or(0),
            warnings: acc.warnings.len(),
            content_item_ids: acc.content_item_ids.len(),
            asset_ids: acc.asset_ids.len(),
            source_ids: acc.source_ids.len(),
            reused_asset_ids: acc.reused_asset_ids.len(),
            copied_files: acc.copied_files.len(),
            staged_pairs: acc.staged_pairs.len(),
        }
    }

    fn restore(self, project: &mut Value, acc: &mut AdoptAccumulator) {
        for (key, length) in [
            ("stages", self.stages),
            ("content_items", self.content_items),
            ("documents", self.documents),
            ("blocks", self.blocks),
            ("assets", self.assets),
            ("asset_usages", self.asset_usages),
            ("inbox_items", self.inbox_items),
        ] {
            if let Some(values) = project.get_mut(key).and_then(Value::as_array_mut) {
                values.truncate(length);
            }
        }
        if let Some(values) = project
            .get_mut("project")
            .and_then(|value| value.get_mut("settings"))
            .and_then(|value| value.get_mut("markdown_import_sources"))
            .and_then(Value::as_array_mut)
        {
            values.truncate(self.ledger);
        }
        acc.warnings.truncate(self.warnings);
        acc.content_item_ids.truncate(self.content_item_ids);
        acc.asset_ids.truncate(self.asset_ids);
        acc.source_ids.truncate(self.source_ids);
        acc.reused_asset_ids.truncate(self.reused_asset_ids);
        acc.copied_files.truncate(self.copied_files);
        // The staged bytes themselves go with the transaction's own staging
        // directory, which `AdoptStagingGuard` removes on the way out.
        acc.staged_pairs.truncate(self.staged_pairs);
    }
}

/// Read-only facts about where this transaction runs.
struct AdoptRoots<'a> {
    resolved_source_root: &'a Path,
    resolved_root: &'a Path,
    project_id: &'a str,
    duplicate_choice: &'a str,
    staging_relative_root: &'a str,
}

/// One file row of the confirmed Mapping Plan, already resolved, read and hashed
/// by `folder_apply_import`.
struct AdoptFile<'a> {
    item: &'a Value,
    rel: &'a str,
    absolute: &'a Path,
    bytes: &'a [u8],
    checksum: &'a str,
    filename: &'a str,
    file_title: &'a str,
}

/// `files[*].reason` renders next to the path in the frontend, so the `{rel}: `
/// prefix the warning stream needs would only be duplicated there.
fn document_reason(rel: &str, message: &str) -> String {
    message
        .strip_prefix(&format!("{rel}: "))
        .unwrap_or(message)
        .to_string()
}

/// §30 duplicate rule, shared by the Markdown path and the native document path so
/// both speak exactly one language about the same SHA-256.
///
/// `Some((true, warning))` refuses the file until the plan says `allow_duplicate`;
/// `Some((false, warning))` records the user's explicit re-import choice; `None`
/// means nothing on record matches this source.
fn adopt_duplicate_check(
    project: &Value,
    resolved_source_root: &Path,
    rel: &str,
    checksum: &str,
    allow_duplicate: bool,
) -> Option<(bool, String)> {
    let source_match = find_markdown_source_match(project, resolved_source_root, rel, checksum)?;
    if !allow_duplicate {
        let message = if source_match.state == "same_content" {
            if source_match.target_deleted {
                format!(
                    "{rel}: SHA-256与曾导入来源「{}」一致，但目标课时已删除；项目仍保留来源记录，默认跳过。",
                    source_match.title
                )
            } else {
                format!(
                    "{rel}: SHA-256与已导入课时「{}」一致；默认跳过，已有编辑内容保持不变。",
                    source_match.title
                )
            }
        } else {
            format!(
                "{rel}: 来源路径已有较旧导入「{}」{}（SHA-256 {}）；默认跳过以避免静默替换，请明确选择“作为新版本导入”。",
                source_match.title,
                if source_match.target_deleted { "（目标课时已删除）" } else { "" },
                source_match.previous_hash.chars().take(12).collect::<String>()
            )
        };
        return Some((true, message));
    }
    let message = if source_match.state == "same_content" {
        if source_match.target_deleted {
            format!(
                "{rel}: 用户已明确重新导入曾删除课时「{}」的相同Markdown；按当前目标新建或追加。",
                source_match.title
            )
        } else {
            format!(
                "{rel}: 用户已明确选择再次导入与「{}」内容相同的Markdown；原课时正文不会被覆盖。",
                source_match.title
            )
        }
    } else if source_match.target_deleted {
        format!(
            "{rel}: 用户已明确导入曾删除课时「{}」的来源新版本；按当前目标新建或追加。",
            source_match.title
        )
    } else {
        format!(
            "{rel}: 用户已明确选择导入来源的新版本；「{}」及其编辑内容保持不变。",
            source_match.title
        )
    };
    Some((false, message))
}

/// The managed `assets/<uuid>-<name>` path of an asset, used to turn a parser's
/// stable `document-image-N.png` reference into a project-owned href.
fn asset_storage_path(project: &Value, asset_id: &str) -> Option<String> {
    project
        .get("assets")
        .and_then(Value::as_array)
        .and_then(|assets| {
            assets
                .iter()
                .find(|asset| asset.get("id").and_then(Value::as_str) == Some(asset_id))
        })
        .and_then(|asset| asset.get("storage_path").and_then(Value::as_str))
        .map(str::to_owned)
}

/// Rewrites one image href inside a block body. The parser emits `![alt](ref)`
/// with `](` … `)` as the only occurrence shape, so the delimiters are matched
/// literally and nothing else in the imported text is touched.
fn rewrite_block_image_href(block: &mut Value, from: &str, to: &str) {
    let previous = format!("]({from})");
    let managed = format!("]({to})");
    for key in ["raw", "text"] {
        let replaced = match block.get(key).and_then(Value::as_str) {
            Some(value) if value.contains(previous.as_str()) => {
                Some(value.replace(previous.as_str(), managed.as_str()))
            }
            Some(value) if value.contains(from) => Some(value.replace(from, to)),
            _ => None,
        };
        if let Some(value) = replaced {
            block[key] = json!(value);
        }
    }
}

/// Registers a file as a Source / Reference inbox item. Never creates a lesson,
/// which is what keeps a file with no importable body out of the content chain.
fn adopt_source_inbox(
    project: &mut Value,
    project_id: &str,
    source_type: &str,
    title: &str,
    body: &str,
    asset_id: Value,
) -> Result<String, String> {
    let inbox_id = native_id("inbox");
    project
        .as_object_mut()
        .ok_or("项目数据必须是 JSON 对象")?
        .get_mut("inbox_items")
        .and_then(Value::as_array_mut)
        .ok_or("inbox_items 无效")?
        .push(json!({
            "id": inbox_id,
            "project_id": project_id,
            "source_type": source_type,
            "title": title,
            "body": body,
            "asset_id": asset_id,
            "content_item_id": Value::Null,
            "status": "open",
            "created_at": rfc3339_now(),
            "updated_at": rfc3339_now(),
        }));
    Ok(inbox_id)
}

/// Keeps a document that has no importable body (a scanned PDF) as a managed
/// Source Reference: the original file is never moved (§29).
fn adopt_keep_source_reference(
    project: &mut Value,
    acc: &mut AdoptAccumulator,
    roots: &AdoptRoots,
    file: &AdoptFile,
) -> Result<(), String> {
    let mut asset_id = Value::Null;
    if let Some(id) = adopt_import_asset(
        project,
        roots.resolved_root,
        roots.project_id,
        file.filename,
        file.bytes,
        file.checksum,
        Some(file.absolute),
        roots.duplicate_choice,
        Some("document"),
        &mut acc.warnings,
        &mut acc.reused_asset_ids,
        &mut acc.copied_files,
        &mut acc.staged_pairs,
        roots.staging_relative_root,
    )? {
        if !acc.asset_ids.contains(&id) {
            acc.asset_ids.push(id.clone());
        }
        asset_id = Value::String(id);
    }
    let inbox_id = adopt_source_inbox(
        project,
        roots.project_id,
        "source",
        file.file_title,
        &format!("源资料：{}", file.rel),
        asset_id,
    )?;
    acc.source_ids.push(inbox_id);
    Ok(())
}

/// §15–§20: a `.txt .tex .docx .epub .pdf` (anything but Markdown, which stays on
/// the shared JS parse) becomes lesson body from the shell's own parse of the
/// bytes it read from the canonicalized path.
///
/// A client-supplied `parsed_markdown` is deliberately not consulted for these
/// formats: the shell parsing the file it opened itself is strictly harder to
/// forge than accepting blocks the renderer sent. Blocks, destination rules and
/// provenance all go through the same `adopt_markdown_blocks` /
/// `adopt_lesson_destination` path as Markdown (§19), and every `ParsedImage`
/// becomes a managed Asset whose href is written back into the body.
fn adopt_native_document_lesson(
    project: &mut Value,
    acc: &mut AdoptAccumulator,
    roots: &AdoptRoots,
    file: &AdoptFile,
    destination: &AdoptLessonDestination,
) -> Result<(DocumentOutcome, String, Option<String>), String> {
    let mut parsed = documents::parse_document(file.filename, file.bytes)
        .map_err(|error| format!("{}: 文档解析失败（{error}）", file.rel))?;
    let latex = matches!(
        documents::extension_of(file.filename).as_str(),
        "tex" | "latex"
    );
    if latex {
        // The LaTeX parser emits direct `\includegraphics{path}` commands as
        // Markdown image links. Reparse each emitted block with the same GFM
        // parser used for Markdown so image position, alt text and occurrence
        // metadata use the shared adoption contract.
        let mut token_index = 0_u64;
        let mut occurrences: HashMap<String, u64> = HashMap::new();
        for (block_index, block) in parsed.blocks.iter_mut().enumerate() {
            let raw = block.get("raw").and_then(Value::as_str).unwrap_or_default();
            let generated = parse_native_markdown(raw)?;
            let mut references = Vec::new();
            for mut reference in generated["imageRefs"]
                .as_array()
                .cloned()
                .unwrap_or_default()
            {
                let href = reference
                    .get("href")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .to_owned();
                let occurrence = *occurrences.get(&href).unwrap_or(&0);
                occurrences.insert(href.clone(), occurrence + 1);
                if let Some(object) = reference.as_object_mut() {
                    object.insert("tokenIndex".to_owned(), json!(token_index));
                    object.insert("occurrence".to_owned(), json!(occurrence));
                    object.insert("blockIndex".to_owned(), json!(block_index));
                }
                token_index += 1;
                references.push(reference);
            }
            block["imageRefs"] = Value::Array(references);
        }
    }
    if !parsed.usable_text {
        // A scanned PDF: never an empty lesson body, only a Source Reference.
        let reason = "没有文字层，已保留为来源参考";
        adopt_keep_source_reference(project, acc, roots, file)?;
        acc.warnings.push(format!(
            "{}: 该文件没有文字层（扫描件），未创建课时，{reason}。",
            file.rel
        ));
        return Ok((DocumentOutcome::Skipped, reason.to_string(), None));
    }
    // Nothing the parser noticed may be silently dropped (§28 "不得静默丢失").
    for warning in &parsed.warnings {
        acc.warnings.push(format!("{}: {warning}", file.rel));
    }
    if let Some((skip, message)) = adopt_duplicate_check(
        project,
        roots.resolved_source_root,
        file.rel,
        file.checksum,
        file.item
            .get("allow_duplicate")
            .and_then(Value::as_bool)
            .unwrap_or(false),
    ) {
        acc.warnings.push(message.clone());
        if skip {
            return Ok((
                DocumentOutcome::Skipped,
                document_reason(file.rel, &message),
                None,
            ));
        }
    }

    let mut assets_by_block: HashMap<usize, Vec<Value>> = HashMap::new();
    let mut managed: HashMap<String, (String, String)> = HashMap::new();
    let mut unresolved: Vec<String> = Vec::new();
    if latex {
        for (block_index, block) in parsed.blocks.iter().enumerate() {
            for reference in block
                .get("imageRefs")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
            {
                let href = reference
                    .get("href")
                    .and_then(Value::as_str)
                    .unwrap_or_default();
                if href.is_empty()
                    || managed.contains_key(href)
                    || unresolved.iter().any(|item| item == href)
                {
                    continue;
                }
                let resolved =
                    match markdown_dependency_path(roots.resolved_source_root, file.rel, href) {
                        Ok(Some(path)) => path,
                        Ok(None) => {
                            acc.warnings.push(format!(
                                "{}: LaTeX 图片引用「{href}」未找到；已保留正文原文。",
                                file.rel
                            ));
                            unresolved.push(href.to_owned());
                            continue;
                        }
                        Err(error) => {
                            acc.warnings.push(format!(
                            "{}: LaTeX 图片引用「{href}」无法安全读取（{error}）；已保留正文原文。",
                            file.rel
                        ));
                            unresolved.push(href.to_owned());
                            continue;
                        }
                    };
                let bytes = match fs::read(&resolved) {
                    Ok(bytes) => bytes,
                    Err(error) => {
                        acc.warnings.push(format!(
                            "{}: LaTeX 图片引用「{href}」读取失败（{error}）；已保留正文原文。",
                            file.rel
                        ));
                        unresolved.push(href.to_owned());
                        continue;
                    }
                };
                let filename = resolved
                    .file_name()
                    .and_then(|name| name.to_str())
                    .unwrap_or("latex-image");
                let checksum = sha256_hex(&bytes);
                let asset_id = match adopt_import_asset(
                    project,
                    roots.resolved_root,
                    roots.project_id,
                    &safe_asset_filename(filename),
                    &bytes,
                    &checksum,
                    Some(&resolved),
                    roots.duplicate_choice,
                    None,
                    &mut acc.warnings,
                    &mut acc.reused_asset_ids,
                    &mut acc.copied_files,
                    &mut acc.staged_pairs,
                    roots.staging_relative_root,
                )? {
                    Some(id) => id,
                    None => {
                        acc.warnings.push(format!(
                            "{}: LaTeX 图片引用「{href}」未纳入素材库；已保留正文原文。",
                            file.rel
                        ));
                        unresolved.push(href.to_owned());
                        continue;
                    }
                };
                let Some(storage_path) = asset_storage_path(project, &asset_id) else {
                    acc.warnings.push(format!(
                        "{}: LaTeX 图片引用「{href}」没有可用的素材路径；已保留正文原文。",
                        file.rel
                    ));
                    unresolved.push(href.to_owned());
                    continue;
                };
                if !acc.asset_ids.contains(&asset_id) {
                    acc.asset_ids.push(asset_id.clone());
                }
                managed.insert(href.to_owned(), (storage_path, asset_id));
                let _ = block_index;
            }
        }
    }
    for image in &parsed.images {
        let bytes = match decode_base64(&image.base64) {
            Ok(bytes) => bytes,
            Err(error) => {
                acc.warnings.push(format!(
                    "{}: 内嵌图片「{}」无法解码（{error}）；已保留正文原文，未创建素材。",
                    file.rel, image.ref_name
                ));
                unresolved.push(image.ref_name.clone());
                continue;
            }
        };
        let name = safe_asset_filename(&image.ref_name);
        let asset_id = match adopt_import_asset(
            project,
            roots.resolved_root,
            roots.project_id,
            &name,
            &bytes,
            &sha256_hex(&bytes),
            None,
            roots.duplicate_choice,
            None,
            &mut acc.warnings,
            &mut acc.reused_asset_ids,
            &mut acc.copied_files,
            &mut acc.staged_pairs,
            roots.staging_relative_root,
        ) {
            Ok(Some(id)) => id,
            Ok(None) => {
                acc.warnings.push(format!(
                    "{}: 内嵌图片「{}」未纳入素材库；已保留正文原文。",
                    file.rel, image.ref_name
                ));
                unresolved.push(image.ref_name.clone());
                continue;
            }
            Err(error) => {
                // The document's own assets are part of its transaction; a media
                // write that fails is this file's failure, not the batch's.
                return Err(error);
            }
        };
        match asset_storage_path(project, &asset_id) {
            Some(storage_path) => {
                if !acc.asset_ids.contains(&asset_id) {
                    acc.asset_ids.push(asset_id.clone());
                }
                managed.insert(image.ref_name.clone(), (storage_path, asset_id));
            }
            None => {
                acc.warnings.push(format!(
                    "{}: 内嵌图片「{}」没有可用的素材路径；已保留正文原文。",
                    file.rel, image.ref_name
                ));
                unresolved.push(image.ref_name.clone());
            }
        }
    }

    let mut blocks: Vec<Value> = Vec::with_capacity(parsed.blocks.len());
    for (index, block) in parsed.blocks.iter().enumerate() {
        let mut block = block.clone();
        let references = block
            .get("imageRefs")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        if references.is_empty() {
            blocks.push(block);
            continue;
        }
        let mut rewritten: Vec<Value> = Vec::with_capacity(references.len());
        for reference in references {
            let href = reference.get("href").and_then(Value::as_str).unwrap_or("");
            match managed.get(href) {
                Some((storage_path, asset_id)) => {
                    rewrite_block_image_href(&mut block, href, storage_path);
                    let occurrence = reference
                        .get("occurrence")
                        .and_then(Value::as_u64)
                        .unwrap_or(0);
                    let mut entry = reference.clone();
                    if let Some(object) = entry.as_object_mut() {
                        object.insert("href".to_owned(), json!(storage_path));
                    }
                    rewritten.push(entry);
                    assets_by_block
                        .entry(index)
                        .or_default()
                        .push(json!({ "href": storage_path, "asset_id": asset_id, "occurrence": occurrence }));
                }
                None => {
                    if !href.is_empty() && !unresolved.iter().any(|pending| pending == href) {
                        acc.warnings.push(format!(
                            "{}: 图片引用「{href}」未能纳入素材库；已保留正文原文。",
                            file.rel
                        ));
                        unresolved.push(href.to_owned());
                    }
                    rewritten.push(reference);
                }
            }
        }
        block["imageRefs"] = Value::Array(rewritten);
        blocks.push(block);
    }
    let degraded = parsed.degraded || !unresolved.is_empty();
    let mut reason = if parsed.degraded {
        match parsed.warnings.first() {
            Some(first) => format!("结构有降级：{first}"),
            None => "结构有降级".to_string(),
        }
    } else {
        String::new()
    };
    if !unresolved.is_empty() {
        let text = format!("内嵌图片未能纳入素材库：{}", unresolved.join("、"));
        reason = if reason.is_empty() {
            text
        } else {
            format!("{reason}；{text}")
        };
    }
    let content_id = if let Some(existing_id) = destination.existing_lesson_id.clone() {
        existing_id
    } else {
        adopt_add_lesson(
            project,
            roots.project_id,
            destination.stage_id.as_deref(),
            file.file_title,
            "",
            false,
        )?
    };
    let provenance = json!({
        "source_root": roots.resolved_source_root.to_string_lossy(),
        "relative_path": file.rel,
        "source_hash": file.checksum,
    });
    adopt_markdown_blocks(
        project,
        &content_id,
        &Value::Array(blocks),
        &assets_by_block,
        Some(&provenance),
    )?;
    let imported_title = project["content_items"]
        .as_array()
        .and_then(|items| items.iter().find(|item| item["id"] == json!(content_id)))
        .and_then(|item| item["title"].as_str())
        .unwrap_or(file.file_title)
        .to_owned();
    record_markdown_import_source(project, &content_id, &imported_title, &provenance)?;
    Ok((
        if degraded {
            DocumentOutcome::Degraded
        } else {
            DocumentOutcome::Succeeded
        },
        reason,
        Some(content_id),
    ))
}

/// Item kinds `folder_apply_import` treats as files. `image` / `video` come from
/// the recursive media scan under a directory the user selected and follow the
/// exact same asset path as `file`; directories never enter here. Mirrors
/// `ADOPTABLE_FILE_KINDS` in src/service/folder_scan.ts.
const ADOPTABLE_FILE_KINDS: [&str; 3] = ["file", "image", "video"];

fn folder_apply_import(
    plan: Value,
    duplicate_choice: Option<String>,
    project_title: Option<String>,
    append_target: Option<CanonicalAppendContext>,
    allow_invalid_replacement: bool,
) -> Result<Value, String> {
    folder_apply_import_with_documents(
        plan,
        duplicate_choice,
        project_title,
        append_target,
        allow_invalid_replacement,
        &[],
    )
}

fn selected_folder_document_items(
    source_root: &Path,
    plan_items: &[Value],
    document_paths: &[String],
    warnings: &mut Vec<String>,
) -> Vec<Value> {
    let mut selected_parents: HashMap<String, (String, Value)> = HashMap::new();
    for item in plan_items {
        if item.get("kind").and_then(Value::as_str) != Some("directory")
            || item.get("selected").and_then(Value::as_bool) != Some(true)
            || item.get("error").is_some_and(|error| !error.is_null())
        {
            continue;
        }
        let mapping = item.get("mapping").and_then(Value::as_str).unwrap_or("");
        if !matches!(mapping, "stage" | "lesson") {
            continue;
        }
        let relative = item
            .get("relative_path")
            .and_then(Value::as_str)
            .unwrap_or("")
            .replace('\\', "/");
        if relative.is_empty()
            || relative.contains('/')
            || relative.contains('\0')
            || relative == "."
            || relative == ".."
        {
            continue;
        }
        let destination = if mapping == "lesson" {
            item.get("destination").cloned().unwrap_or(Value::Null)
        } else {
            Value::Null
        };
        selected_parents.insert(relative, (mapping.to_owned(), destination));
    }

    let mut paths: Vec<String> = document_paths
        .iter()
        .map(|path| path.replace('\\', "/"))
        .collect();
    paths.sort();
    paths.dedup();
    let mut selected = Vec::new();
    for relative in paths {
        let parts: Vec<&str> = relative.split('/').collect();
        if relative.is_empty()
            || relative.contains('\0')
            || Path::new(&relative).is_absolute()
            || parts.len() != 2
            || parts
                .iter()
                .any(|part| part.is_empty() || *part == "." || *part == "..")
        {
            warnings.push(format!(
                "{relative}: 只允许导入已选根级文件夹中的直接子文档"
            ));
            continue;
        }
        let (directory, filename) = (parts[0], parts[1]);
        let Some((parent_mapping, destination)) = selected_parents.get(directory) else {
            warnings.push(format!(
                "{relative}: 父文件夹未按当前映射选入阶段或课时，已跳过"
            ));
            continue;
        };
        if filename.starts_with('.') || managed_import_name(filename) {
            warnings.push(format!("{relative}: 已跳过隐藏或工作台管理文件"));
            continue;
        }
        if !documents::is_supported_document(filename) {
            warnings.push(format!("{relative}: 不是支持的正文文档格式，已跳过"));
            continue;
        }
        match path_has_symlink_component(source_root, &relative) {
            Ok(false) => {}
            Ok(true) => {
                warnings.push(format!("{relative}: 已跳过符号链接，避免越过所选文件夹"));
                continue;
            }
            Err(error) => {
                warnings.push(format!(
                    "{relative}: 无法安全检查文档路径（{error}），已跳过"
                ));
                continue;
            }
        }
        let path = source_root.join(&relative);
        let metadata = match fs::symlink_metadata(&path) {
            Ok(metadata) if !metadata.file_type().is_symlink() && metadata.is_file() => metadata,
            Ok(_) => {
                warnings.push(format!("{relative}: 不是普通文档文件，已跳过"));
                continue;
            }
            Err(error) => {
                warnings.push(format!("{relative}: 无法读取文档（{error}），已跳过"));
                continue;
            }
        };
        let canonical = match fs::canonicalize(&path) {
            Ok(path) if path.starts_with(source_root) => path,
            _ => {
                warnings.push(format!("{relative}: 文档路径超出所选文件夹，已跳过"));
                continue;
            }
        };
        let relative = match scan_relative(source_root, &canonical) {
            Ok(relative) => relative,
            Err(error) => {
                warnings.push(format!("{relative}: {error}"));
                continue;
            }
        };
        let shares_new_lesson = parent_mapping == "lesson"
            && destination.get("kind").and_then(Value::as_str) != Some("existing_lesson");
        selected.push(json!({
            "relative_path": relative,
            "kind": "file",
            "mime": mime_for_filename(filename),
            "size": metadata.len(),
            "suggested": "lesson",
            "mapping": "lesson",
            "selected": true,
            "is_suggestion": true,
            "error": Value::Null,
            "destination": if parent_mapping == "lesson" { destination.clone() } else { Value::Null },
            "folder_lesson_group": if shares_new_lesson { json!(directory) } else { Value::Null },
            "folder_lesson_title": if shares_new_lesson { json!(directory) } else { Value::Null },
            "allow_duplicate": false,
        }));
    }
    selected
}

fn folder_apply_import_with_documents(
    plan: Value,
    duplicate_choice: Option<String>,
    project_title: Option<String>,
    append_target: Option<CanonicalAppendContext>,
    allow_invalid_replacement: bool,
    document_paths: &[String],
) -> Result<Value, String> {
    let plan_obj = plan
        .as_object()
        .ok_or_else(|| "folder.adopt requires a mapping plan object".to_string())?;
    let confirmed = plan_obj
        .get("confirmed")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    if !confirmed {
        return Err("只能对已确认的导入计划执行文件夹接管".into());
    }
    let root_raw = plan_obj
        .get("root")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim()
        .to_string();
    if root_raw.is_empty() {
        return Err("接管需要有效的文件夹路径".into());
    }
    let root_path = PathBuf::from(&root_raw);
    if !root_path.is_absolute() {
        return Err("导入文件夹必须是用户明确选择的绝对路径".into());
    }
    reject_symlink(&root_path, "导入文件夹")?;
    let root_meta =
        fs::symlink_metadata(&root_path).map_err(|error| format!("无法打开所选文件夹：{error}"))?;
    if root_meta.file_type().is_symlink() || !root_meta.is_dir() {
        return Err("导入已有文件夹需要选择一个文件夹，而不是单个文件".into());
    }
    let resolved_source_root = fs::canonicalize(&root_path).unwrap_or(root_path.clone());
    reject_symlink(&resolved_source_root, "导入文件夹")?;
    let resolved_root = append_target
        .as_ref()
        .map(|context| context.directory.clone())
        .unwrap_or_else(|| resolved_source_root.clone());

    // Refuse to clobber an existing Canonical project silently on first adoption.
    let existing_manifest = resolved_root.join("project.json");
    let mut quarantine_manifest = false;
    if append_target.is_none() && existing_manifest.exists() {
        if !allow_invalid_replacement {
            return Err("该文件夹已有 project.json，不能重复原地接管。请先打开现有项目。".into());
        }
        // The confirmation says "the file here is broken", not "overwrite whatever
        // is here": a readable or migratable project must still be opened, and a
        // file we cannot even read is never ours to move.
        let diagnosis = inspect_project_directory(&resolved_root);
        match diagnosis["status"].as_str().unwrap_or("unreadable") {
            "invalid" | "malformed_json" => {
                let code = diagnosis["problem"]["code"].as_str().unwrap_or("");
                if code == "unsupported_schema" {
                    // A newer project is not a broken one: the fix is to upgrade,
                    // not to let an older build rearrange someone's course.
                    return Err(
                        "这个项目由更高版本的 Workbench 创建，当前版本不会改写它。请升级后再打开；若确实要把它当作资料文件夹导入，请先自行改名或移除其中的 project.json。"
                            .into(),
                    );
                }
                quarantine_manifest = true;
            }
            "valid" | "migratable" => {
                return Err(
                    "这个文件夹里的 project.json 是一个可用的课程项目。请直接「打开现有项目」，不要重新导入。"
                        .into(),
                )
            }
            _ => {
                return Err(format!(
                    "无法确认这个文件夹里的 project.json：{}",
                    diagnosis["problem"]["message"]
                        .as_str()
                        .unwrap_or("文件不可读")
                ))
            }
        }
    }

    let duplicate_choice = duplicate_choice
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("existing");
    let title = project_title
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| {
            resolved_source_root
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or("未命名课程")
                .to_string()
        });

    let mut project = if let Some(context) = append_target.as_ref() {
        context.project.clone()
    } else {
        blank_adopt_project(&title)?
    };
    let project_id = project
        .get("project")
        .and_then(|value| value.get("id"))
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string();

    let mut acc = AdoptAccumulator::default();
    let mut tally = DocumentImportTally::default();
    let mut items = plan_obj
        .get("items")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let selected_documents = selected_folder_document_items(
        &resolved_source_root,
        &items,
        document_paths,
        &mut acc.warnings,
    );
    for item in &mut items {
        if let Some(object) = item.as_object_mut() {
            object.remove("folder_lesson_group");
            object.remove("folder_lesson_title");
        }
    }
    items.extend(selected_documents);
    expand_selected_directory_media(&resolved_source_root, &mut items, &mut acc.warnings);

    // §28: every supported document that did not reach the body pipeline is still
    // accounted for, so "unchecked" shows up as a deliberate skip rather than
    // vanishing from the report.
    for item in &items {
        if adopt_item_included(item) {
            continue;
        }
        let kind = item.get("kind").and_then(Value::as_str).unwrap_or("file");
        if !ADOPTABLE_FILE_KINDS.contains(&kind) {
            continue;
        }
        let rel = item
            .get("relative_path")
            .and_then(Value::as_str)
            .unwrap_or("")
            .replace('\\', "/");
        let filename = safe_asset_filename(
            Path::new(&rel)
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or("unnamed"),
        );
        if !documents::is_supported_document(&filename) {
            continue;
        }
        let mapping = item
            .get("mapping")
            .and_then(Value::as_str)
            .unwrap_or("ignore");
        if !matches!(mapping, "lesson" | "ignore") {
            continue;
        }
        let reason = if item
            .get("error")
            .and_then(|value| value.as_str())
            .map(|value| !value.is_empty())
            .unwrap_or(false)
        {
            item.get("error")
                .and_then(|value| value.as_str())
                .unwrap_or_default()
                .to_owned()
        } else if mapping == "ignore" {
            "未选择导入正文".to_string()
        } else {
            "未勾选，未导入正文".to_string()
        };
        tally.record_file(kind, &rel, &filename, DocumentOutcome::Skipped, &reason);
    }

    let mut stage_by_rel: std::collections::HashMap<String, String> =
        std::collections::HashMap::new();
    let mut folder_lesson_targets: HashMap<String, String> = HashMap::new();

    // Pass 1: stages
    for item in &items {
        if !adopt_item_included(item) {
            continue;
        }
        let mapping = item
            .get("mapping")
            .and_then(Value::as_str)
            .unwrap_or("ignore");
        let kind = item.get("kind").and_then(Value::as_str).unwrap_or("file");
        let rel = item
            .get("relative_path")
            .and_then(Value::as_str)
            .unwrap_or("")
            .replace('\\', "/");
        if mapping != "stage" || kind != "directory" || rel.is_empty() {
            continue;
        }
        let stage_id = uuid_v4()?;
        let title = Path::new(&rel)
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or(&rel)
            .to_string();
        let order = project
            .get("stages")
            .and_then(Value::as_array)
            .map(Vec::len)
            .unwrap_or(0);
        let stage = json!({
            "id": stage_id,
            "project_id": project_id,
            "parent_stage_id": Value::Null,
            "code": format!("S{:02}", order + 1),
            "title": title,
            "description": "",
            "learning_action": "",
            "order_index": order,
            "archived": false,
            "created_at": rfc3339_now(),
            "updated_at": rfc3339_now(),
        });
        project
            .as_object_mut()
            .unwrap()
            .get_mut("stages")
            .and_then(Value::as_array_mut)
            .unwrap()
            .push(stage);
        stage_by_rel.insert(rel.clone(), stage_id.clone());
        acc.stage_ids.push(stage_id);
    }

    fs::create_dir_all(resolved_root.join(".workspace"))
        .map_err(|error| format!("无法创建 .workspace：{error}"))?;
    fs::create_dir_all(resolved_root.join(".workspace/adopt-staging"))
        .map_err(|error| format!("无法创建素材暂存目录：{error}"))?;
    let staging_relative_root = format!(".workspace/adopt-staging/{}", uuid_v4()?);
    let staging_absolute_root = resolved_root.join(&staging_relative_root);
    fs::create_dir(&staging_absolute_root)
        .map_err(|error| format!("无法创建素材暂存目录：{error}"))?;
    let staging_cleanup = AdoptStagingGuard(staging_absolute_root);
    let roots = AdoptRoots {
        resolved_source_root: &resolved_source_root,
        resolved_root: &resolved_root,
        project_id: &project_id,
        duplicate_choice,
        staging_relative_root: &staging_relative_root,
    };

    // Pass 2: files, including the image/video rows `expand_selected_directory_media`
    // appended for directories the user selected. Directories stay in pass 1 as
    // stages and are never swept in as documents here.
    for item in &items {
        if !adopt_item_included(item) {
            continue;
        }
        let mapping = item
            .get("mapping")
            .and_then(Value::as_str)
            .unwrap_or("ignore");
        let kind = item.get("kind").and_then(Value::as_str).unwrap_or("file");
        let rel = item
            .get("relative_path")
            .and_then(Value::as_str)
            .unwrap_or("")
            .replace('\\', "/");
        if !ADOPTABLE_FILE_KINDS.contains(&kind) || rel.is_empty() {
            continue;
        }
        let filename = safe_asset_filename(
            Path::new(&rel)
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or("unnamed"),
        );
        let file_title = Path::new(&filename)
            .file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or(&filename)
            .to_string();
        let file_title = item
            .get("folder_lesson_title")
            .and_then(Value::as_str)
            .filter(|title| !title.is_empty())
            .unwrap_or(&file_title)
            .to_owned();
        // The containment checks below refuse a path before it is ever opened. For
        // the text/document rows that refusal is also a §28 "skipped" line, so the
        // user sees why a listed file produced nothing.
        if Path::new(&rel).is_absolute() || rel.split('/').any(|part| part == ".." || part == ".") {
            acc.warnings.push(format!("{rel}: 非法路径已跳过"));
            tally.record_file(
                kind,
                &rel,
                &filename,
                DocumentOutcome::Skipped,
                "非法路径，未导入",
            );
            continue;
        }
        let mut absolute = resolved_source_root.clone();
        let mut invalid_path = false;
        for part in rel.split('/').filter(|part| !part.is_empty()) {
            absolute.push(part);
            match fs::symlink_metadata(&absolute) {
                Ok(meta) if meta.file_type().is_symlink() => {
                    invalid_path = true;
                    break;
                }
                Ok(_) => {}
                Err(_) => break,
            }
        }
        if invalid_path {
            acc.warnings.push(format!("{rel}: 已跳过符号链接"));
            tally.record_file(
                kind,
                &rel,
                &filename,
                DocumentOutcome::Skipped,
                "符号链接目标未跟随，未导入",
            );
            continue;
        }
        let meta = match fs::symlink_metadata(&absolute) {
            Ok(value) => value,
            Err(error) => {
                acc.warnings.push(format!("{rel}: 无法读取（{error}）"));
                tally.record_file(
                    kind,
                    &rel,
                    &filename,
                    DocumentOutcome::Failed,
                    "无法读取文件",
                );
                continue;
            }
        };
        if meta.file_type().is_symlink() {
            acc.warnings.push(format!("{rel}: 已跳过符号链接"));
            tally.record_file(
                kind,
                &rel,
                &filename,
                DocumentOutcome::Skipped,
                "符号链接目标未跟随，未导入",
            );
            continue;
        }
        let canonical_absolute = match fs::canonicalize(&absolute) {
            Ok(path) if path.starts_with(&resolved_source_root) => path,
            _ => {
                acc.warnings.push(format!("{rel}: 导入路径超出所选文件夹"));
                tally.record_file(
                    kind,
                    &rel,
                    &filename,
                    DocumentOutcome::Skipped,
                    "导入路径超出所选文件夹，未导入",
                );
                continue;
            }
        };
        absolute = canonical_absolute;
        let bytes = match fs::read(&absolute) {
            Ok(value) => value,
            Err(error) => {
                acc.warnings.push(format!("{rel}: 无法读取（{error}）"));
                tally.record_file(
                    kind,
                    &rel,
                    &filename,
                    DocumentOutcome::Failed,
                    "无法读取文件",
                );
                continue;
            }
        };
        let checksum = sha256_hex(&bytes);
        let stage_id = adopt_parent_stage(&rel, &stage_by_rel);

        // §28: everything that can fail because of *this* file lives in the block
        // below. A `?` here means "this document failed", the transaction records
        // it, rolls the file's own partial work back and moves on — a 15-file batch
        // must not collapse over one broken file. Real transaction failures
        // (locked project, unwritable manifest, journal/atomic write) still `Err`.
        let file = AdoptFile {
            item,
            rel: &rel,
            absolute: &absolute,
            bytes: &bytes,
            checksum: &checksum,
            filename: &filename,
            file_title: &file_title,
        };
        let content_item_count_before = acc.content_item_ids.len();
        let snapshot = AdoptItemSnapshot::capture(&project, &acc);
        let report: Result<Option<(DocumentOutcome, String)>, String> = (|| {
            let mut report: Option<(DocumentOutcome, String)> = None;
            'item: {
                match mapping {
                    "lesson" => {
                        let grouped_item = item
                            .get("folder_lesson_group")
                            .and_then(Value::as_str)
                            .and_then(|group| {
                                folder_lesson_targets.get(group).map(|id| (group, id))
                            })
                            .map(|(_, content_item_id)| {
                                let mut clone = item.clone();
                                clone["destination"] = json!({
                                    "kind": "existing_lesson",
                                    "content_item_id": content_item_id
                                });
                                clone
                            });
                        let destination_item = grouped_item.as_ref().unwrap_or(item);
                        let markdown = matches!(
                            Path::new(&filename)
                                .extension()
                                .and_then(|value| value.to_str())
                                .unwrap_or_default()
                                .to_ascii_lowercase()
                                .as_str(),
                            "md" | "markdown"
                        );
                        // §15–§20: a format the parser layer supports becomes body content
                        // through the shell's own parse of the bytes it read from the
                        // canonicalized path. `.md` / `.markdown` keep the shared JS parse
                        // and its `source_hash` check exactly as before.
                        let native = !markdown && documents::is_supported_document(&filename);
                        let mut unresolved_images = 0_usize;
                        let content_id = if native {
                            let destination = adopt_lesson_destination(
                                &project,
                                &project_id,
                                destination_item,
                                stage_id.clone(),
                            )?;
                            let (outcome, reason, content_id) = adopt_native_document_lesson(
                                &mut project,
                                &mut acc,
                                &roots,
                                &file,
                                &destination,
                            )?;
                            report = Some((outcome, reason));
                            content_id
                        } else if markdown {
                            let source_text = std::str::from_utf8(&bytes)
                                .map_err(|_| format!("{rel}: Markdown源不是UTF-8文本"))?;
                            let parsed = match item
                                .get("parsed_markdown")
                                .filter(|value| value.is_object())
                            {
                                Some(parsed) => parsed.clone(),
                                None => {
                                    let generated = parse_native_markdown(source_text)?;
                                    // Retain the existing common downstream path while
                                    // making client parser output optional.
                                    let parsed_value = json!({
                                        "source_hash": checksum,
                                        "blocks": generated["blocks"].clone(),
                                        "explicitLocalImageRefs": generated["explicitLocalImageRefs"].clone(),
                                    });
                                    parsed_value
                                }
                            };
                            let expected_hash = parsed
                                .get("source_hash")
                                .and_then(Value::as_str)
                                .unwrap_or("");
                            if expected_hash != checksum {
                                return Err(format!("{rel}: 源文件在解析后发生变化，未提交导入"));
                            }
                            let parsed_blocks =
                                parsed.get("blocks").ok_or("Markdown解析结果缺少blocks")?;
                            let refs = parsed
                                .get("explicitLocalImageRefs")
                                .and_then(Value::as_array)
                                .cloned()
                                .unwrap_or_default();
                            verify_markdown_image_refs(source_text, parsed_blocks, &refs)?;
                            if let Some((skip, message)) = adopt_duplicate_check(
                                &project,
                                &resolved_source_root,
                                &rel,
                                &checksum,
                                item.get("allow_duplicate")
                                    .and_then(Value::as_bool)
                                    .unwrap_or(false),
                            ) {
                                acc.warnings.push(message.clone());
                                if skip {
                                    report = Some((
                                        DocumentOutcome::Skipped,
                                        document_reason(&rel, &message),
                                    ));
                                    break 'item;
                                }
                            }
                            let destination = adopt_lesson_destination(
                                &project,
                                &project_id,
                                destination_item,
                                stage_id.clone(),
                            )?;
                            let mut assets_by_block: HashMap<usize, Vec<Value>> = HashMap::new();
                            for reference in refs {
                                let block_index = reference
                                    .get("blockIndex")
                                    .and_then(Value::as_u64)
                                    .and_then(|value| usize::try_from(value).ok())
                                    .ok_or("Markdown图片引用缺少区块索引")?;
                                let href = reference
                                    .get("href")
                                    .and_then(Value::as_str)
                                    .ok_or("Markdown图片引用缺少路径")?;
                                let occurrence = reference
                                    .get("occurrence")
                                    .and_then(Value::as_u64)
                                    .unwrap_or(0);
                                let parser_block = parsed_blocks
                                    .as_array()
                                    .and_then(|blocks| blocks.get(block_index))
                                    .ok_or("Markdown图片引用指向不存在区块")?;
                                let in_block = parser_block
                                    .get("imageRefs")
                                    .and_then(Value::as_array)
                                    .map(|images| {
                                        images.iter().any(|image| {
                                            image.get("href").and_then(Value::as_str) == Some(href)
                                                && image.get("occurrence").and_then(Value::as_u64)
                                                    == Some(occurrence)
                                        })
                                    })
                                    .unwrap_or(false);
                                if !in_block {
                                    return Err("Markdown图片引用与解析区块不一致".into());
                                }
                                let dependency = match markdown_dependency_path(
                                    &resolved_source_root,
                                    &rel,
                                    href,
                                )? {
                                    Some(path) => path,
                                    None => {
                                        unresolved_images += 1;
                                        acc.warnings.push(format!(
                                    "{rel}: 图片依赖「{href}」不存在；已保留正文原文，未创建素材。"
                                ));
                                        continue;
                                    }
                                };
                                let dependency_bytes = match fs::read(&dependency) {
                                    Ok(bytes) => bytes,
                                    Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                                        unresolved_images += 1;
                                        acc.warnings.push(format!(
                                    "{rel}: 图片依赖「{href}」不存在；已保留正文原文，未创建素材。"
                                ));
                                        continue;
                                    }
                                    Err(error) => {
                                        return Err(format!(
                                            "无法读取Markdown图片依赖「{href}」：{error}"
                                        ))
                                    }
                                };
                                let dependency_name = safe_asset_filename(
                                    dependency
                                        .file_name()
                                        .and_then(|value| value.to_str())
                                        .unwrap_or("image"),
                                );
                                let dependency_checksum = sha256_hex(&dependency_bytes);
                                let asset_id = adopt_import_asset(
                                    &mut project,
                                    &resolved_root,
                                    &project_id,
                                    &dependency_name,
                                    &dependency_bytes,
                                    &dependency_checksum,
                                    Some(&dependency),
                                    duplicate_choice,
                                    None,
                                    &mut acc.warnings,
                                    &mut acc.reused_asset_ids,
                                    &mut acc.copied_files,
                                    &mut acc.staged_pairs,
                                    &staging_relative_root,
                                )?
                                .ok_or("Markdown图片依赖没有生成素材")?;
                                if !acc.asset_ids.contains(&asset_id) {
                                    acc.asset_ids.push(asset_id.clone());
                                }
                                assets_by_block.entry(block_index).or_default().push(json!({
                                    "href": href,
                                    "asset_id": asset_id,
                                    "occurrence": occurrence,
                                }));
                            }
                            let content_id =
                                if let Some(existing_id) = destination.existing_lesson_id {
                                    existing_id
                                } else {
                                    adopt_add_lesson(
                                        &mut project,
                                        &project_id,
                                        destination.stage_id.as_deref(),
                                        &file_title,
                                        "",
                                        false,
                                    )?
                                };
                            let provenance = json!({
                                "source_root": resolved_source_root.to_string_lossy(),
                                "relative_path": rel,
                                "source_hash": checksum,
                            });
                            adopt_markdown_blocks(
                                &mut project,
                                &content_id,
                                parsed_blocks,
                                &assets_by_block,
                                Some(&provenance),
                            )?;
                            let imported_title = project["content_items"]
                                .as_array()
                                .and_then(|items| {
                                    items.iter().find(|item| item["id"] == content_id)
                                })
                                .and_then(|item| item["title"].as_str())
                                .unwrap_or(&file_title)
                                .to_owned();
                            record_markdown_import_source(
                                &mut project,
                                &content_id,
                                &imported_title,
                                &provenance,
                            )?;
                            Some(content_id)
                        } else {
                            let destination = adopt_lesson_destination(
                                &project,
                                &project_id,
                                destination_item,
                                stage_id.clone(),
                            )?;
                            let text = String::from_utf8_lossy(&bytes).into_owned();
                            let content_id =
                                if let Some(existing_id) = destination.existing_lesson_id {
                                    adopt_append_text_lesson(&mut project, &existing_id, &text)?;
                                    existing_id
                                } else {
                                    adopt_add_lesson(
                                        &mut project,
                                        &project_id,
                                        destination.stage_id.as_deref(),
                                        &file_title,
                                        &text,
                                        false,
                                    )?
                                };
                            Some(content_id)
                        };
                        if let Some(content_id) = content_id {
                            if !acc.content_item_ids.contains(&content_id) {
                                acc.content_item_ids.push(content_id);
                            }
                        }
                        if report.is_none() {
                            let (outcome, reason) = if unresolved_images > 0 {
                                (
                            DocumentOutcome::Degraded,
                            format!("{unresolved_images} 处图片依赖未纳入素材库，正文已保留原文"),
                        )
                            } else {
                                (DocumentOutcome::Succeeded, String::new())
                            };
                            report = Some((outcome, reason));
                        }
                    }
                    "asset" => {
                        if let Some(asset_id) = adopt_import_asset(
                            &mut project,
                            &resolved_root,
                            &project_id,
                            &filename,
                            &bytes,
                            &checksum,
                            Some(&absolute),
                            duplicate_choice,
                            None,
                            &mut acc.warnings,
                            &mut acc.reused_asset_ids,
                            &mut acc.copied_files,
                            &mut acc.staged_pairs,
                            &staging_relative_root,
                        )? {
                            acc.asset_ids.push(asset_id);
                        }
                    }
                    "reference" | "source" => {
                        let source_type = if mapping == "reference" {
                            "reference"
                        } else {
                            "source"
                        };
                        let ext = Path::new(&filename)
                            .extension()
                            .and_then(|value| value.to_str())
                            .unwrap_or("")
                            .to_ascii_lowercase();
                        let is_text = matches!(ext.as_str(), "md" | "markdown" | "txt");
                        let mut asset_id = Value::Null;
                        if !is_text || mapping == "reference" {
                            if let Some(id) = adopt_import_asset(
                                &mut project,
                                &resolved_root,
                                &project_id,
                                &filename,
                                &bytes,
                                &checksum,
                                Some(&absolute),
                                duplicate_choice,
                                Some("document"),
                                &mut acc.warnings,
                                &mut acc.reused_asset_ids,
                                &mut acc.copied_files,
                                &mut acc.staged_pairs,
                                &staging_relative_root,
                            )? {
                                acc.asset_ids.push(id.clone());
                                asset_id = Value::String(id);
                            }
                        }
                        let body = if is_text && mapping == "source" {
                            format!("源资料：{rel}\n\n{}", String::from_utf8_lossy(&bytes))
                        } else if mapping == "reference" {
                            format!("参考资料：{rel}")
                        } else {
                            format!("源资料：{rel}")
                        };
                        let inbox_id = adopt_source_inbox(
                            &mut project,
                            &project_id,
                            source_type,
                            &file_title,
                            &body,
                            asset_id,
                        )?;
                        acc.source_ids.push(inbox_id);
                    }
                    other => {
                        acc.warnings
                            .push(format!("{rel}: 映射「{other}」在文件上已跳过"));
                    }
                }
            }
            Ok(report)
        })();
        match report {
            Ok(Some((outcome, reason))) => {
                tally.record_file(kind, &rel, &filename, outcome, &reason)
            }
            Ok(None) => {}
            // The user cancelled duplicates for the whole run: honour that as a
            // transaction-level abort instead of quietly moving to the next file.
            Err(error) if error == "已取消重复素材导入" => return Err(error),
            Err(error) => {
                let reason = document_reason(&rel, &error);
                snapshot.restore(&mut project, &mut acc);
                acc.warnings.push(format!(
                    "{rel}: 该文件导入失败，已跳过并继续处理其余文件（{reason}）"
                ));
                tally.record_file(kind, &rel, &filename, DocumentOutcome::Failed, &reason);
            }
        }
        if let Some(group) = item
            .get("folder_lesson_group")
            .and_then(Value::as_str)
            .filter(|group| !folder_lesson_targets.contains_key(*group))
        {
            if let Some(content_item_id) = acc.content_item_ids.get(content_item_count_before) {
                folder_lesson_targets.insert(group.to_owned(), content_item_id.clone());
            }
        }
    }

    // §28 + §29: an append that imported nothing rewrites nothing — the existing
    // manifest keeps the exact bytes it had, so a batch whose every file failed
    // cannot touch a project the user did not change. A first adoption still creates
    // the project the dialog asked for.
    let imported_anything = !acc.stage_ids.is_empty()
        || !acc.content_item_ids.is_empty()
        || !acc.asset_ids.is_empty()
        || !acc.source_ids.is_empty()
        || !acc.reused_asset_ids.is_empty()
        || !acc.copied_files.is_empty()
        || !acc.staged_pairs.is_empty()
        || quarantine_manifest;
    let root_str = resolved_root.to_string_lossy().into_owned();
    let mut commit_report = None;
    if append_target.is_none() || imported_anything {
        commit_report = Some(adopt_commit_transaction(
            &mut project,
            &mut acc,
            &resolved_root,
            &root_str,
            append_target.as_ref(),
            quarantine_manifest,
            &existing_manifest,
        )?);
    }
    if let Some(report) = commit_report.as_ref() {
        if let Some(warning) = report.durability_warning.as_ref() {
            acc.warnings.push(warning.clone());
        }
        if let Some(warning) = report.recovery_warning.as_ref() {
            acc.warnings.push(warning.clone());
        }
    }
    let staging_parent = resolved_root.join(".workspace/adopt-staging");
    drop(staging_cleanup);
    let _ = fs::remove_dir(staging_parent);

    let (fingerprint, lease_generation, mutation_binding, outcome) =
        if let Some(context) = append_target.as_ref() {
            (
                commit_report
                    .as_ref()
                    .map(|report| report.fingerprint.clone())
                    .unwrap_or_else(|| context.fingerprint.clone()),
                context.lease_generation.clone(),
                context.mutation_binding.as_ref(),
                if commit_report.is_some() {
                    "written"
                } else {
                    "unchanged"
                },
            )
        } else {
            (
                commit_report
                    .as_ref()
                    .map(|report| report.fingerprint.clone())
                    .ok_or("folder adoption did not produce a Canonical write report")?,
                active_lease_generation(&resolved_root)?,
                None,
                "written",
            )
        };
    let durability_warning = commit_report
        .as_ref()
        .and_then(|report| report.durability_warning.as_deref());
    let recovery_warning = commit_report
        .as_ref()
        .and_then(|report| report.recovery_warning.as_deref());
    let mut result = json!({
        "data": project.clone(),
        "root": root_str,
        "source_root": resolved_source_root.to_string_lossy(),
        "stage_ids": acc.stage_ids,
        "content_item_ids": acc.content_item_ids,
        "asset_ids": acc.asset_ids,
        "source_ids": acc.source_ids,
        "reused_asset_ids": acc.reused_asset_ids,
        "warnings": acc.warnings,
        "copied_files": acc.copied_files,
        "copied_original_paths": [],
        "document_import": tally.to_value(),
    });
    attach_canonical_mutation_ack(
        &mut result,
        mutation_binding,
        &project,
        &fingerprint,
        &resolved_root,
        &lease_generation,
        outcome,
        durability_warning,
        recovery_warning,
    );
    Ok(result)
}

/// Promotes this transaction's UUID-owned media first, then atomically writes the
/// Canonical manifest as the final commit. Existing assets and originals are never
/// replaced or removed; every failure here is a transaction-level error, because
/// it is about the project on disk rather than one source file.
fn adopt_commit_transaction(
    project: &mut Value,
    acc: &mut AdoptAccumulator,
    resolved_root: &Path,
    root_str: &str,
    append_context: Option<&CanonicalAppendContext>,
    quarantine_manifest: bool,
    existing_manifest: &Path,
) -> Result<ProjectWriteReport, String> {
    let mut promoted = Vec::new();
    let promotion = (|| -> Result<(), String> {
        if !acc.staged_pairs.is_empty() {
            reject_symlink(&resolved_root.join("assets"), "素材目录")?;
            fs::create_dir_all(resolved_root.join("assets"))
                .map_err(|error| format!("无法创建 assets：{error}"))?;
        }
        for (staging, final_path) in &acc.staged_pairs {
            let from = resolved_root.join(staging);
            let to = resolved_root.join(final_path);
            if let Some(parent) = to.parent() {
                reject_symlink(parent, "素材目录")?;
                fs::create_dir_all(parent).map_err(|error| format!("无法创建素材目录：{error}"))?;
            }
            let mut output = fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&to)
                .map_err(|error| format!("素材提升失败，课程清单尚未提交（{error}）"))?;
            promoted.push(to.clone());
            let mut input =
                fs::File::open(&from).map_err(|error| format!("无法读取素材暂存文件：{error}"))?;
            std::io::copy(&mut input, &mut output)
                .map_err(|error| format!("素材提升失败，课程清单尚未提交（{error}）"))?;
            output
                .sync_all()
                .map_err(|error| format!("素材落盘失败，课程清单尚未提交（{error}）"))?;
            fs::remove_file(&from)
                .map_err(|error| format!("素材暂存清理失败，课程清单尚未提交（{error}）"))?;
        }
        Ok(())
    })();
    if let Err(error) = promotion {
        for path in &promoted {
            let _ = fs::remove_file(path);
        }
        for (staging, _) in &acc.staged_pairs {
            let _ = fs::remove_file(resolved_root.join(staging));
        }
        return Err(error);
    }

    if let Some(project_object) = project.get_mut("project").and_then(Value::as_object_mut) {
        project_object.insert("updated_at".into(), json!(rfc3339_now()));
    }
    // Case C: the unusable manifest is moved aside — never deleted — under a
    // name the folder scan already ignores, and only now, after every earlier
    // step succeeded. An aborted import leaves the folder exactly as it was.
    let mut quarantined: Option<PathBuf> = None;
    if quarantine_manifest {
        let stamp: String = rfc3339_now()
            .chars()
            .filter(|character| character.is_ascii_alphanumeric())
            .collect();
        let mut backup = resolved_root.join(format!("project.json.{stamp}.invalid.backup"));
        let mut attempt = 1_u32;
        while backup.exists() {
            backup = resolved_root.join(format!("project.json.{stamp}-{attempt}.invalid.backup"));
            attempt += 1;
            if attempt > 99 {
                return Err("无法为原有的 project.json 找到可用的备份文件名，导入已中止。".into());
            }
        }
        if let Err(error) = fs::rename(existing_manifest, &backup) {
            for path in &promoted {
                let _ = fs::remove_file(path);
            }
            for (staging, _) in &acc.staged_pairs {
                let _ = fs::remove_file(resolved_root.join(staging));
            }
            return Err(format!(
                "无法把原有的 project.json 移到「{}」，导入已中止，原文件保持不动：{error}",
                backup.display()
            ));
        }
        quarantined = Some(backup);
    }
    let commit = if let Some(context) = append_context {
        write_canonical_mutation_report_unlocked(
            resolved_root,
            project,
            &context.fingerprint,
            context.mutation_binding.as_ref(),
        )
    } else {
        project_create_report(root_str.to_owned(), project)
    };
    let report = match commit {
        Ok(report) => report,
        Err(error) => {
            let outcome_uncertain = serde_json::from_str::<Value>(&error)
                .ok()
                .and_then(|value| value["error"]["commit_state"].as_str().map(str::to_owned))
                .is_some_and(|state| state == "outcome_uncertain");
            if !outcome_uncertain {
                for path in &promoted {
                    let _ = fs::remove_file(path);
                }
                for (staging, _) in &acc.staged_pairs {
                    let _ = fs::remove_file(resolved_root.join(staging));
                }
                if let Some(backup) = &quarantined {
                    let _ = fs::rename(backup, existing_manifest);
                }
            }
            return Err(error);
        }
    };
    if let Some(backup) = &quarantined {
        acc.warnings.push(format!(
            "原有的 project.json 已完整保留为「{}」，没有删除任何文件。",
            backup
                .file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("备份文件")
        ));
    }
    Ok(report)
}

fn adopt_item_included(item: &Value) -> bool {
    let mapping = item
        .get("mapping")
        .and_then(Value::as_str)
        .unwrap_or("ignore");
    if mapping == "ignore" {
        return false;
    }
    if item.get("selected").and_then(Value::as_bool) != Some(true) {
        return false;
    }
    if item
        .get("error")
        .and_then(|value| value.as_str())
        .map(|value| !value.is_empty())
        .unwrap_or(false)
    {
        return false;
    }
    true
}

fn adopt_parent_stage(
    rel: &str,
    stage_by_rel: &std::collections::HashMap<String, String>,
) -> Option<String> {
    let parts: Vec<&str> = rel.split('/').filter(|part| !part.is_empty()).collect();
    if parts.len() < 2 {
        return None;
    }
    for end in (1..parts.len()).rev() {
        let prefix = parts[..end].join("/");
        if let Some(id) = stage_by_rel.get(&prefix) {
            return Some(id.clone());
        }
    }
    None
}

fn blank_adopt_project(title: &str) -> Result<Value, String> {
    let project_id = uuid_v4()?;
    let now = rfc3339_now();
    let mut status_dimensions = Vec::new();
    let mut status_options = Vec::new();
    let dims = [
        ("content", "正文"),
        ("media", "媒体"),
        ("layout", "排版"),
        ("review", "审核"),
        ("publish", "发布"),
        ("update", "更新"),
    ];
    for (index, (key, name)) in dims.iter().enumerate() {
        let dim_id = uuid_v4()?;
        status_dimensions.push(json!({
            "id": dim_id,
            "project_id": project_id,
            "key": key,
            "name": name,
            "order_index": index,
            "allow_custom": true,
        }));
        for (opt_index, label) in ["未开始", "进行中", "已完成"].iter().enumerate() {
            status_options.push(json!({
                "id": uuid_v4()?,
                "dimension_id": dim_id,
                "key": format!("{key}_{opt_index}"),
                "name": label,
                "order_index": opt_index,
                "is_terminal": opt_index == 2,
            }));
        }
    }
    Ok(json!({
        "schema_version": "1.0.0",
        "project": {
            "id": project_id,
            "title": title,
            "description": "",
            "language": "zh-CN",
            "schema_version": "1.0.0",
            "created_at": now,
            "updated_at": now,
            "archived": false,
            "settings": {},
        },
        "stages": [],
        "content_items": [],
        "documents": [],
        "blocks": [],
        "groups": [],
        "requirements": [],
        "assets": [],
        "asset_usages": [],
        "status_dimensions": status_dimensions,
        "status_options": status_options,
        "status_assignments": [],
        "layout_templates": [],
        "layout_instances": [],
        "layout_sections": [],
        "placements": [],
        "inbox_items": [],
        "export_presets": [],
        "course_seeds": [],
        "blueprint_drafts": [],
        "blueprint_nodes": [],
        "conversation_sources": [],
        "conversations": [],
        "messages": [],
        "context_packs": [],
        "context_pack_items": [],
        "suggestions": [],
        "change_drafts": [],
        "snapshots": [],
        "publications": [],
    }))
}

fn adopt_add_lesson(
    project: &mut Value,
    project_id: &str,
    stage_id: Option<&str>,
    title: &str,
    text: &str,
    markdown: bool,
) -> Result<String, String> {
    let content_id = uuid_v4()?;
    let document_id = uuid_v4()?;
    let order = project
        .get("content_items")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter(|item| {
                    !item
                        .get("archived")
                        .and_then(Value::as_bool)
                        .unwrap_or(false)
                        && item.get("stage_id").and_then(Value::as_str) == stage_id
                })
                .count()
        })
        .unwrap_or(0);
    let code = if let Some(stage_id) = stage_id {
        let stage_code = project
            .get("stages")
            .and_then(Value::as_array)
            .and_then(|stages| {
                stages.iter().find_map(|stage| {
                    if stage.get("id").and_then(Value::as_str) == Some(stage_id) {
                        stage
                            .get("code")
                            .and_then(Value::as_str)
                            .map(str::to_string)
                    } else {
                        None
                    }
                })
            })
            .unwrap_or_else(|| "S01".into());
        format!("{stage_code}-{:02}", order + 1)
    } else {
        format!("C{:02}", order + 1)
    };
    let map = project.as_object_mut().ok_or("项目数据必须是 JSON 对象")?;
    map.get_mut("documents")
        .and_then(Value::as_array_mut)
        .ok_or("documents 无效")?
        .push(json!({
            "id": document_id,
            "content_item_id": content_id,
            "created_at": rfc3339_now(),
            "updated_at": rfc3339_now(),
        }));
    map.get_mut("content_items")
        .and_then(Value::as_array_mut)
        .ok_or("content_items 无效")?
        .push(json!({
            "id": content_id,
            "project_id": project_id,
            "stage_id": stage_id,
            "code": code,
            "title": title,
            "type": "lesson",
            "description": "",
            "order_index": order,
            "document_id": document_id,
            "archived": false,
            "created_at": rfc3339_now(),
            "updated_at": rfc3339_now(),
        }));
    let blocks = map
        .get_mut("blocks")
        .and_then(Value::as_array_mut)
        .ok_or("blocks 无效")?;
    let mut order_index = 0;
    for line in text.replace("\r\n", "\n").replace('\r', "\n").lines() {
        let value = line.trim();
        if value.is_empty() {
            continue;
        }
        let (block_type, content, settings) = if markdown {
            if let Some(rest) = value.strip_prefix("###### ") {
                ("heading", rest.to_string(), json!({"level": 6}))
            } else if let Some(rest) = value.strip_prefix("##### ") {
                ("heading", rest.to_string(), json!({"level": 5}))
            } else if let Some(rest) = value.strip_prefix("#### ") {
                ("heading", rest.to_string(), json!({"level": 4}))
            } else if let Some(rest) = value.strip_prefix("### ") {
                ("heading", rest.to_string(), json!({"level": 3}))
            } else if let Some(rest) = value.strip_prefix("## ") {
                ("heading", rest.to_string(), json!({"level": 2}))
            } else if let Some(rest) = value.strip_prefix("# ") {
                ("heading", rest.to_string(), json!({"level": 1}))
            } else if let Some(rest) = value.strip_prefix("> ") {
                ("quote", rest.to_string(), json!({}))
            } else {
                ("paragraph", value.to_string(), json!({}))
            }
        } else {
            ("paragraph", value.to_string(), json!({}))
        };
        blocks.push(json!({
            "id": uuid_v4()?,
            "document_id": document_id,
            "parent_block_id": Value::Null,
            "type": block_type,
            "order_index": order_index,
            "content": content,
            "settings": settings,
            "created_at": rfc3339_now(),
            "updated_at": rfc3339_now(),
        }));
        order_index += 1;
    }
    Ok(content_id)
}

fn adopt_import_asset(
    project: &mut Value,
    root: &Path,
    project_id: &str,
    filename: &str,
    bytes: &[u8],
    checksum: &str,
    source_abs: Option<&Path>,
    duplicate_choice: &str,
    force_type: Option<&str>,
    warnings: &mut Vec<String>,
    reused_asset_ids: &mut Vec<String>,
    copied_files: &mut Vec<String>,
    staged_pairs: &mut Vec<(String, String)>,
    staging_root: &str,
) -> Result<Option<String>, String> {
    if let Some(existing) = project
        .get("assets")
        .and_then(Value::as_array)
        .and_then(|assets| {
            assets.iter().find(|asset| {
                asset.get("project_id").and_then(Value::as_str) == Some(project_id)
                    && asset.get("checksum").and_then(Value::as_str) == Some(checksum)
                    && asset.get("archived").and_then(Value::as_bool) != Some(true)
            })
        })
    {
        if duplicate_choice == "cancel" {
            return Err("已取消重复素材导入".into());
        }
        if duplicate_choice == "existing" {
            let id = existing
                .get("id")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string();
            reused_asset_ids.push(id.clone());
            warnings.push(format!("素材「{filename}」checksum 已存在，已复用现有素材"));
            return Ok(Some(id));
        }
    }

    let asset_id = uuid_v4()?;
    let storage_path = format!("assets/{asset_id}-{filename}");
    let staging_path = format!("{staging_root}/{asset_id}-{filename}");
    let dest = root.join(&staging_path);
    if let Some(parent) = dest.parent() {
        fs::create_dir_all(parent).map_err(|error| format!("无法创建素材暂存目录：{error}"))?;
    }
    // Stage under .workspace so a failed Canonical write does not leave a
    // half-adopted assets/ tree. Originals are only read, never truncated.
    // Bytes that exist only inside a parsed document (an embedded image) have no
    // source path and go straight into staging.
    let copied = match source_abs {
        Some(path) => fs::copy(path, &dest).is_ok(),
        None => false,
    };
    if !copied {
        fs::write(&dest, bytes).map_err(|error| format!("无法写入素材暂存：{error}"))?;
    }
    staged_pairs.push((staging_path, storage_path.clone()));
    copied_files.push(storage_path.clone());
    let mime = mime_for_filename(filename);
    let asset_type = force_type
        .map(str::to_string)
        .unwrap_or_else(|| normalize_asset_type(None, filename, mime));
    project
        .as_object_mut()
        .unwrap()
        .get_mut("assets")
        .and_then(Value::as_array_mut)
        .unwrap()
        .push(json!({
            "id": asset_id,
            "project_id": project_id,
            "type": asset_type,
            "filename": filename,
            "storage_path": storage_path,
            "mime_type": mime,
            "width": Value::Null,
            "height": Value::Null,
            "duration_ms": Value::Null,
            "file_size": bytes.len(),
            "checksum": checksum,
            "title": filename,
            "description": "",
            "source_type": "imported",
            "source_url": Value::Null,
            "copyright_note": Value::Null,
            "created_at": rfc3339_now(),
            "archived": false,
        }));
    Ok(Some(asset_id))
}

fn append_inbox_item(project: &mut Value, item: Value) -> Result<String, String> {
    let project_id = project
        .get("project")
        .and_then(|value| value.get("id"))
        .cloned()
        .unwrap_or(Value::Null);
    let object = project.as_object_mut().ok_or("项目数据必须是 JSON 对象")?;
    let list = object
        .entry("inbox_items")
        .or_insert_with(|| Value::Array(Vec::new()));
    let items = list.as_array_mut().ok_or("项目的收件箱数据格式无效")?;
    let id = native_id("inbox");
    let title = item
        .get("title")
        .cloned()
        .unwrap_or_else(|| json!("未命名输入"));
    let body = item.get("body").cloned().unwrap_or_else(|| json!(""));
    items.push(json!({
        "id": id,
        "project_id": project_id,
        "source_type": "file",
        "title": title,
        "body": body,
        "asset_id": null,
        "content_item_id": null,
        "status": "open",
        "created_at": unix_millis().to_string(),
        "updated_at": unix_millis().to_string(),
    }));
    Ok(id)
}

/// The Domain owns the seed/blueprint semantics (`src/domain/course.ts`), and
/// the browser shell reaches them through the service. The desktop shell has no
/// service process, so the two commands below mirror that module instead of
/// inventing a second product behaviour: same node derivation, same
/// content-type inference, and the same rule that a draft writes no formal
/// Stage/ContentItem rows.
fn uuid_v4() -> Result<String, String> {
    let mut bytes = [0_u8; 16];
    getrandom::fill(&mut bytes).map_err(|error| format!("无法生成标识: {error}"))?;
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    let hex: String = bytes.iter().map(|byte| format!("{byte:02x}")).collect();
    Ok(format!(
        "{}-{}-{}-{}-{}",
        &hex[0..8],
        &hex[8..12],
        &hex[12..16],
        &hex[16..20],
        &hex[20..32]
    ))
}

fn seed_content_type(title: &str) -> &'static str {
    let normalized = title.to_lowercase();
    if normalized.contains("练习") || normalized.contains("exercise") {
        return "exercise";
    }
    if normalized.contains("案例") || normalized.contains("case") {
        return "case";
    }
    if normalized.contains("总结") || normalized.contains("summary") {
        return "summary";
    }
    if normalized.contains("测验")
        || normalized.contains("考试")
        || normalized.contains("assessment")
    {
        return "assessment";
    }
    if normalized.contains("参考") || normalized.contains("reference") {
        return "reference";
    }
    "lesson"
}

/// Mirrors `^(#{1,6}|\d+[.)])\s*(.+)$` from the Domain.
fn heading_title(line: &str) -> Option<String> {
    let hashes = line.chars().take_while(|value| *value == '#').count();
    if hashes >= 1 {
        let rest = line[hashes.min(6)..].trim_start();
        if !rest.is_empty() {
            return Some(rest.trim().to_string());
        }
    }
    let digits = line.chars().take_while(char::is_ascii_digit).count();
    if digits > 0 {
        let rest = &line[digits..];
        let mut chars = rest.chars();
        if matches!(chars.next(), Some('.') | Some(')')) {
            let tail = chars.as_str().trim_start();
            if !tail.is_empty() {
                return Some(tail.trim().to_string());
            }
        }
    }
    None
}

fn strip_list_marker(line: &str) -> String {
    let trimmed = line.trim();
    let mut chars = trimmed.chars();
    if let Some(first) = chars.next() {
        if matches!(first, '-' | '*' | '+') {
            return chars.as_str().trim_start().trim().to_string();
        }
    }
    trimmed.to_string()
}

fn first_meaningful_line(raw_text: &str) -> String {
    raw_text
        .split('\n')
        .map(|line| line.trim().trim_start_matches('#').trim())
        .find(|line| !line.is_empty())
        .unwrap_or_default()
        .to_string()
}

fn seed_lines_to_nodes(raw_text: &str) -> Vec<Value> {
    let lines: Vec<&str> = raw_text
        .split('\n')
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .collect();
    if lines.is_empty() {
        return vec![
            json!({
                "node_type": "stage",
                "title": "开始",
                "suggested_type": "stage_intro",
                "parent_index": Value::Null,
            }),
            json!({
                "node_type": "content",
                "title": "第一课",
                "suggested_type": "lesson",
                "parent_index": 0,
            }),
        ];
    }
    let mut nodes: Vec<Value> = Vec::new();
    let mut current_stage: Option<usize> = None;
    for line in lines {
        if let Some(title) = heading_title(line) {
            current_stage = Some(nodes.len());
            nodes.push(json!({
                "node_type": "stage",
                "title": title,
                "suggested_type": "stage_intro",
                "parent_index": Value::Null,
            }));
            continue;
        }
        let stage_index = match current_stage {
            Some(index) => index,
            None => {
                let index = nodes.len();
                nodes.push(json!({
                    "node_type": "stage",
                    "title": "课程内容",
                    "suggested_type": "stage_intro",
                    "parent_index": Value::Null,
                }));
                current_stage = Some(index);
                index
            }
        };
        nodes.push(json!({
            "node_type": "content",
            "title": strip_list_marker(line),
            "suggested_type": seed_content_type(line),
            "parent_index": stage_index,
        }));
    }
    nodes
}

#[tauri::command]
fn course_seed_create(input: Value) -> Result<Value, String> {
    let object = require_object(&input, "course_seed_create")?;
    let project_dir = required_string(object, &["project_dir", "projectDir"], "项目目录")?;
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let _lease_guard = require_active_project_lock(&project_dir)?;
    let mutation_binding = parse_canonical_mutation_binding(object)?;
    let active_generation = verify_lease_generation(
        &project_dir,
        mutation_binding
            .as_ref()
            .map(|binding| binding.lease_generation.as_str()),
    )?;
    let source_type = required_string(object, &["source_type", "sourceType"], "课程输入类型")?;
    let raw_text = field(object, &["raw_text", "rawText"])
        .and_then(Value::as_str)
        .map(str::to_string);
    let (mut project, current_fingerprint) = read_project_state(&project_dir)?;
    validate_canonical_mutation_binding(
        mutation_binding.as_ref(),
        &project,
        &current_fingerprint,
        &active_generation,
    )?;
    let seed = json!({
        "id": uuid_v4()?,
        // The Domain keeps the pointer empty until the map is confirmed.
        "project_id": Value::Null,
        "source_type": source_type,
        "raw_text": raw_text,
        "source_files": [],
        "metadata": {},
        "created_at": rfc3339_now(),
    });
    {
        let map = project.as_object_mut().ok_or("项目数据必须是 JSON 对象")?;
        map.entry("course_seeds")
            .or_insert_with(|| Value::Array(Vec::new()))
            .as_array_mut()
            .ok_or("项目的课程输入数据格式无效")?
            .push(seed.clone());
    }
    touch_project_updated_at(&mut project)?;
    let report = write_canonical_mutation_report_unlocked(
        &project_dir,
        &project,
        &current_fingerprint,
        mutation_binding.as_ref(),
    )?;
    let mut result = seed;
    attach_canonical_mutation_ack(
        &mut result,
        mutation_binding.as_ref(),
        &project,
        &report.fingerprint,
        &project_dir,
        &active_generation,
        "written",
        report.durability_warning.as_deref(),
        report.recovery_warning.as_deref(),
    );
    Ok(result)
}

#[tauri::command]
fn blueprint_build(input: Value) -> Result<Value, String> {
    let object = require_object(&input, "blueprint_build")?;
    let project_dir = required_string(object, &["project_dir", "projectDir"], "项目目录")?;
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let _lease_guard = require_active_project_lock(&project_dir)?;
    let mutation_binding = parse_canonical_mutation_binding(object)?;
    let active_generation = verify_lease_generation(
        &project_dir,
        mutation_binding
            .as_ref()
            .map(|binding| binding.lease_generation.as_str()),
    )?;
    let course_seed_id = required_string(object, &["course_seed_id", "courseSeedId"], "课程输入")?;
    let (mut project, current_fingerprint) = read_project_state(&project_dir)?;
    validate_canonical_mutation_binding(
        mutation_binding.as_ref(),
        &project,
        &current_fingerprint,
        &active_generation,
    )?;
    let seed = project
        .get("course_seeds")
        .and_then(Value::as_array)
        .and_then(|seeds| {
            seeds.iter().find(|seed| {
                seed.get("id").and_then(Value::as_str) == Some(course_seed_id.as_str())
            })
        })
        .cloned()
        .ok_or_else(|| format!("找不到课程输入: {course_seed_id}"))?;
    let raw_text = seed
        .get("raw_text")
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string();
    let metadata_title = seed
        .get("metadata")
        .and_then(|value| value.get("title"))
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim()
        .to_string();
    let title = if !metadata_title.is_empty() {
        metadata_title
    } else {
        let first = first_meaningful_line(&raw_text);
        if first.is_empty() {
            "未命名课程".to_string()
        } else {
            first
        }
    };
    let draft_id = uuid_v4()?;
    let draft = json!({
        "id": draft_id.clone(),
        "course_seed_id": course_seed_id,
        "title": title,
        "status": "draft",
        "created_at": rfc3339_now(),
        "confirmed_at": Value::Null,
    });
    let mut node_ids: Vec<Value> = Vec::new();
    let mut nodes: Vec<Value> = Vec::new();
    for (index, node) in seed_lines_to_nodes(&raw_text).iter().enumerate() {
        let parent_id = node
            .get("parent_index")
            .and_then(Value::as_u64)
            .map(|parent| {
                node_ids
                    .get(parent as usize)
                    .cloned()
                    .unwrap_or(Value::Null)
            })
            .unwrap_or(Value::Null);
        let node_id = uuid_v4()?;
        nodes.push(json!({
            "id": node_id,
            "blueprint_id": draft_id,
            "parent_id": parent_id,
            "node_type": node.get("node_type").cloned().unwrap_or_else(|| json!("content")),
            "title": node.get("title").cloned().unwrap_or_else(|| json!("")),
            "suggested_type": node.get("suggested_type").cloned().unwrap_or_else(|| json!("lesson")),
            "order_index": index,
        }));
        node_ids.push(json!(node_id));
    }
    {
        let map = project.as_object_mut().ok_or("项目数据必须是 JSON 对象")?;
        map.entry("blueprint_drafts")
            .or_insert_with(|| Value::Array(Vec::new()))
            .as_array_mut()
            .ok_or("项目的课程草稿数据格式无效")?
            .push(draft.clone());
        map.entry("blueprint_nodes")
            .or_insert_with(|| Value::Array(Vec::new()))
            .as_array_mut()
            .ok_or("项目的课程节点数据格式无效")?
            .extend(nodes.iter().cloned());
    }
    touch_project_updated_at(&mut project)?;
    let report = write_canonical_mutation_report_unlocked(
        &project_dir,
        &project,
        &current_fingerprint,
        mutation_binding.as_ref(),
    )?;
    let mut result = json!({ "draft": draft, "nodes": nodes });
    attach_canonical_mutation_ack(
        &mut result,
        mutation_binding.as_ref(),
        &project,
        &report.fingerprint,
        &project_dir,
        &active_generation,
        "written",
        report.durability_warning.as_deref(),
        report.recovery_warning.as_deref(),
    );
    Ok(result)
}

#[tauri::command]
fn import_confirm(preview: Value) -> Result<Value, String> {
    let object = require_object(&preview, "import_confirm")?;
    if !object
        .get("confirmed")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return Err("导入必须先确认预览结果".into());
    }
    let project_dir = required_string(object, &["project_dir", "projectDir"], "项目目录")?;
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let _lease_guard = require_active_project_lock(&project_dir)?;
    let source = preview_source(&json!({
        "project_dir": project_dir,
        "path": required_string(object, &["source_path", "path"], "导入文件")?,
    }))?;
    let source_path_value = source
        .get("source_path")
        .and_then(Value::as_str)
        .ok_or("导入来源缺失")?;
    let (_, canonical) = source_path(&json!({ "path": source_path_value }))?;
    let metadata =
        fs::metadata(&canonical).map_err(|error| format!("无法读取导入来源: {error}"))?;
    let mut project = read_project_value(&project_dir)?;
    let mut imported = Vec::new();
    if metadata.is_dir() {
        for entry in
            fs::read_dir(&canonical).map_err(|error| format!("无法读取导入目录: {error}"))?
        {
            let entry = entry.map_err(|error| format!("无法读取导入目录条目: {error}"))?;
            let path = entry.path();
            reject_symlink(&path, "导入目录条目")?;
            if path.is_file() {
                imported.push(append_inbox_item(&mut project, import_item(&path)?)?);
            }
        }
    } else {
        imported.push(append_inbox_item(&mut project, import_item(&canonical)?)?);
    }
    write_project_value_unlocked(&project_dir, &project)?;
    Ok(json!({ "status": "confirmed", "imported_ids": imported, "count": imported.len() }))
}

fn export_format(preset: &Value) -> Result<String, String> {
    let object = preset.as_object().ok_or("导出预设必须是结构化对象")?;
    let format = field(object, &["format", "output_type", "target_type"])
        .and_then(Value::as_str)
        .unwrap_or("json")
        .to_ascii_lowercase();
    let format = match format.as_str() {
        "json" | "project_json" | "json_project" => "json",
        "md" | "markdown" => "markdown",
        "html" | "semantic_html" => "html",
        "web" | "static_web" | "web_package" => "web",
        "wechat" | "wechat_html" | "rich_text" => "wechat",
        "pdf" => "pdf",
        "pptx" | "powerpoint" => "pptx",
        "asset" | "assets" | "asset_package" => "asset_package",
        "package" | "full_package" | "full_project" => "full_project",
        _ => return Err("当前原生导出不支持这个格式".into()),
    };
    Ok(format.into())
}

fn output_filename(preset: &Value, project: &Value, format: &str) -> String {
    let requested = preset
        .get("filename")
        .or_else(|| preset.get("name"))
        .and_then(Value::as_str)
        .unwrap_or_else(|| {
            project
                .get("project")
                .and_then(|value| value.get("title"))
                .and_then(Value::as_str)
                .unwrap_or("course")
        });
    let mut filename = String::new();
    for character in requested.chars() {
        if character.is_ascii_alphanumeric()
            || matches!(character, '-' | '_' | '.' | ' ' | '中'..='龥')
        {
            filename.push(character);
        } else {
            filename.push('_');
        }
    }
    let filename = filename.trim().trim_matches('.');
    let filename = if filename.is_empty() {
        "course"
    } else {
        filename
    };
    let extension = match format {
        "json" | "full_project" | "asset_package" => "json",
        "markdown" => "md",
        "pdf" => "pdf",
        "pptx" => "pptx",
        "web" => "web",
        _ => "html",
    };
    if filename.ends_with(&format!(".{extension}")) {
        filename.to_owned()
    } else {
        format!("{filename}.{extension}")
    }
}

fn text_value(value: Option<&Value>) -> String {
    match value {
        Some(Value::String(text)) => text.clone(),
        Some(Value::Null) | None => String::new(),
        Some(other) => serde_json::to_string(other).unwrap_or_default(),
    }
}

fn block_content(block: &Value) -> String {
    match block.get("content") {
        Some(Value::Object(object)) => field(object, &["text", "value", "markdown", "url"])
            .map(|value| text_value(Some(value)))
            .unwrap_or_else(|| serde_json::to_string(object).unwrap_or_default()),
        value => text_value(value),
    }
}

fn is_layout_only_requirement(project: &Value, block_id: &str) -> bool {
    project
        .get("requirements")
        .and_then(Value::as_array)
        .map(|requirements| {
            requirements.iter().any(|requirement| {
                requirement.get("scope").and_then(Value::as_str) == Some("layout")
                    && requirement.get("anchor_block_id").and_then(Value::as_str) == Some(block_id)
            })
        })
        .unwrap_or(false)
}

fn project_blocks<'a>(project: &'a Value, document_id: &str) -> Vec<&'a Value> {
    let mut blocks: Vec<&Value> = project
        .get("blocks")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(|block| block.get("document_id").and_then(Value::as_str) == Some(document_id))
        .collect();
    blocks.sort_by_key(|block| {
        block
            .get("order_index")
            .and_then(Value::as_i64)
            .unwrap_or(0)
    });
    blocks
}

fn asset_selected_for_content(
    project: &Value,
    asset_id: &str,
    content_item_id: Option<&str>,
) -> bool {
    let used_by_content = project
        .get("asset_usages")
        .and_then(Value::as_array)
        .map(|usages| {
            usages.iter().any(|usage| {
                usage.get("asset_id").and_then(Value::as_str) == Some(asset_id)
                    && content_item_id.is_none_or(|content_item_id| {
                        usage.get("content_item_id").and_then(Value::as_str)
                            == Some(content_item_id)
                    })
            })
        })
        .unwrap_or(false);
    let resolved_by_content = project
        .get("requirements")
        .and_then(Value::as_array)
        .map(|requirements| {
            requirements.iter().any(|requirement| {
                requirement.get("resolved_asset_id").and_then(Value::as_str) == Some(asset_id)
                    && content_item_id.is_none_or(|content_item_id| {
                        requirement.get("content_item_id").and_then(Value::as_str)
                            == Some(content_item_id)
                    })
            })
        })
        .unwrap_or(false);
    used_by_content || resolved_by_content
}

fn block_asset<'a>(project: &'a Value, block: &Value) -> Option<&'a Value> {
    let linked = block
        .get("settings")
        .and_then(|value| value.get("asset_id"))
        .and_then(Value::as_str);
    let content = block_content(block);
    project
        .get("assets")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .find(|asset| {
            !asset
                .get("archived")
                .and_then(Value::as_bool)
                .unwrap_or(false)
                && (linked.is_some_and(|id| asset.get("id").and_then(Value::as_str) == Some(id))
                    || asset.get("filename").and_then(Value::as_str) == Some(content.as_str())
                    || asset.get("storage_path").and_then(Value::as_str) == Some(content.as_str()))
        })
}

fn asset_is_inline(project: &Value, document_id: &str, asset_id: &str) -> bool {
    project_blocks(project, document_id).iter().any(|block| {
        block_asset(project, block)
            .and_then(|asset| asset.get("id"))
            .and_then(Value::as_str)
            == Some(asset_id)
    })
}

fn referenced_assets_for_content<'a>(project: &'a Value, content_item_id: &str) -> Vec<&'a Value> {
    let mut assets: Vec<&Value> = project
        .get("assets")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(|asset| {
            !asset
                .get("archived")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        })
        .filter(|asset| {
            asset
                .get("id")
                .and_then(Value::as_str)
                .map(|asset_id| {
                    asset_selected_for_content(project, asset_id, Some(content_item_id))
                })
                .unwrap_or(false)
        })
        .filter(|asset| {
            asset
                .get("storage_path")
                .and_then(Value::as_str)
                .map(|path| {
                    let path = Path::new(path);
                    !path.is_absolute()
                        && path
                            .components()
                            .all(|component| matches!(component, Component::Normal(_)))
                })
                .unwrap_or(false)
        })
        .collect();
    assets.sort_by_key(|asset| {
        (
            asset
                .get("filename")
                .and_then(Value::as_str)
                .unwrap_or_default(),
            asset.get("id").and_then(Value::as_str).unwrap_or_default(),
        )
    });
    assets
}

fn markdown_for_project(project: &Value, content_item_id: Option<&str>) -> String {
    let mut lines = Vec::new();
    let title = project
        .get("project")
        .and_then(|value| value.get("title"))
        .and_then(Value::as_str)
        .unwrap_or("未命名课程");
    lines.push(format!("# {title}"));
    lines.push(String::new());
    if let Some(items) = project.get("content_items").and_then(Value::as_array) {
        let mut items: Vec<&Value> = items
            .iter()
            .filter(|item| {
                !item
                    .get("archived")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                    && content_item_id.map_or(true, |id| {
                        item.get("id").and_then(Value::as_str) == Some(id)
                    })
            })
            .collect();
        items.sort_by_key(|item| item.get("order_index").and_then(Value::as_i64).unwrap_or(0));
        for item in items {
            let item_title = item
                .get("title")
                .and_then(Value::as_str)
                .unwrap_or("未命名内容");
            lines.push(format!("## {item_title}"));
            lines.push(String::new());
            if let Some(document_id) = item.get("document_id").and_then(Value::as_str) {
                for block in project_blocks(project, document_id) {
                    if block
                        .get("id")
                        .and_then(Value::as_str)
                        .map(|id| is_layout_only_requirement(project, id))
                        .unwrap_or(false)
                    {
                        continue;
                    }
                    let content = block_content(block);
                    if content.is_empty() {
                        continue;
                    }
                    let block_type = block
                        .get("type")
                        .and_then(Value::as_str)
                        .unwrap_or("paragraph");
                    match block_type {
                        "heading" => {
                            let level = block
                                .get("settings")
                                .and_then(|value| value.get("level"))
                                .and_then(Value::as_i64)
                                .unwrap_or(3)
                                .clamp(1, 6);
                            lines.push(format!("{} {content}", "#".repeat(level as usize)));
                        }
                        "quote" => lines.push(format!("> {content}")),
                        "code" => {
                            lines.push("```".into());
                            lines.push(content);
                            lines.push("```".into());
                        }
                        "divider" => lines.push("---".into()),
                        "placeholder" => continue,
                        "image" | "gif" | "video" | "audio" | "embed" => {
                            if let Some(asset) = block_asset(project, block) {
                                let title = asset
                                    .get("title")
                                    .or_else(|| asset.get("filename"))
                                    .and_then(Value::as_str)
                                    .unwrap_or("素材")
                                    .replace('[', "\\[")
                                    .replace(']', "\\]");
                                let path = asset
                                    .get("storage_path")
                                    .and_then(Value::as_str)
                                    .unwrap_or_default();
                                let image = matches!(
                                    asset.get("type").and_then(Value::as_str),
                                    Some("image" | "gif")
                                );
                                lines.push(format!(
                                    "{}[{title}]({path})",
                                    if image { "!" } else { "" }
                                ));
                            } else if !content.is_empty() {
                                lines.push(content);
                            }
                        }
                        _ => lines.push(content),
                    }
                    lines.push(String::new());
                }
            }
            if let Some(item_id) = item.get("id").and_then(Value::as_str) {
                let assets: Vec<&Value> =
                    referenced_assets_for_content(project, item_id)
                        .into_iter()
                        .filter(|asset| {
                            !item.get("document_id").and_then(Value::as_str).is_some_and(
                                |document_id| {
                                    asset.get("id").and_then(Value::as_str).is_some_and(
                                        |asset_id| asset_is_inline(project, document_id, asset_id),
                                    )
                                },
                            )
                        })
                        .collect();
                if !assets.is_empty() {
                    lines.push("### 素材".into());
                    lines.push(String::new());
                    for asset in assets {
                        let title = asset
                            .get("title")
                            .or_else(|| asset.get("filename"))
                            .and_then(Value::as_str)
                            .unwrap_or("素材");
                        let path = asset
                            .get("storage_path")
                            .and_then(Value::as_str)
                            .unwrap_or_default();
                        let is_image = matches!(
                            asset.get("type").and_then(Value::as_str),
                            Some("image" | "gif")
                        );
                        lines.push(format!(
                            "{}[{}]({path})",
                            if is_image { "!" } else { "" },
                            title.replace('[', "\\[").replace(']', "\\]")
                        ));
                        lines.push(String::new());
                    }
                }
            }
        }
    }
    format!("{}\n", lines.join("\n").trim())
}

fn escape_html(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#39;")
}

fn html_for_project(project: &Value, content_item_id: Option<&str>) -> String {
    let title = project
        .get("project")
        .and_then(|value| value.get("title"))
        .and_then(Value::as_str)
        .unwrap_or("未命名课程");
    let mut body = String::new();
    if let Some(items) = project.get("content_items").and_then(Value::as_array) {
        let mut items: Vec<&Value> = items
            .iter()
            .filter(|item| {
                !item
                    .get("archived")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                    && content_item_id.map_or(true, |id| {
                        item.get("id").and_then(Value::as_str) == Some(id)
                    })
            })
            .collect();
        items.sort_by_key(|item| item.get("order_index").and_then(Value::as_i64).unwrap_or(0));
        for item in items {
            let item_title = item
                .get("title")
                .and_then(Value::as_str)
                .unwrap_or("未命名内容");
            body.push_str(&format!("<section><h2>{}</h2>", escape_html(item_title)));
            if let Some(document_id) = item.get("document_id").and_then(Value::as_str) {
                for block in project_blocks(project, document_id) {
                    if block
                        .get("id")
                        .and_then(Value::as_str)
                        .map(|id| is_layout_only_requirement(project, id))
                        .unwrap_or(false)
                    {
                        continue;
                    }
                    let content = block_content(block);
                    let escaped = escape_html(&content);
                    let block_type = block
                        .get("type")
                        .and_then(Value::as_str)
                        .unwrap_or("paragraph");
                    match block_type {
                        "heading" => {
                            let level = block
                                .get("settings")
                                .and_then(|value| value.get("level"))
                                .and_then(Value::as_i64)
                                .unwrap_or(3)
                                .clamp(1, 6);
                            body.push_str(&format!("<h{level}>{escaped}</h{level}>"));
                        }
                        "quote" => body.push_str(&format!("<blockquote>{escaped}</blockquote>")),
                        "code" => body.push_str(&format!("<pre><code>{escaped}</code></pre>")),
                        "divider" => body.push_str("<hr>"),
                        "placeholder" => continue,
                        "image" | "gif" | "video" | "audio" | "embed" => {
                            if let Some(asset) = block_asset(project, block) {
                                let title = escape_html(
                                    asset
                                        .get("title")
                                        .or_else(|| asset.get("filename"))
                                        .and_then(Value::as_str)
                                        .unwrap_or("素材"),
                                );
                                let path = escape_html(
                                    asset
                                        .get("storage_path")
                                        .and_then(Value::as_str)
                                        .unwrap_or_default(),
                                );
                                match asset.get("type").and_then(Value::as_str) {
                                    Some("image" | "gif") => body.push_str(&format!(
                                        "<figure><img src=\"{path}\" alt=\"{title}\"><figcaption>{title}</figcaption></figure>"
                                    )),
                                    Some("video") => body.push_str(&format!(
                                        "<figure><video controls src=\"{path}\"></video><figcaption>{title}</figcaption></figure>"
                                    )),
                                    Some("audio") => body.push_str(&format!(
                                        "<figure><audio controls src=\"{path}\"></audio><figcaption>{title}</figcaption></figure>"
                                    )),
                                    _ => body.push_str(&format!(
                                        "<aside><strong>附件：{title}</strong> <a href=\"{path}\">打开</a></aside>"
                                    )),
                                }
                            } else if !content.is_empty() {
                                body.push_str(&format!("<p>{escaped}</p>"));
                            }
                        }
                        _ => body.push_str(&format!("<p>{escaped}</p>")),
                    }
                }
            }
            if let Some(item_id) = item.get("id").and_then(Value::as_str) {
                let assets: Vec<&Value> =
                    referenced_assets_for_content(project, item_id)
                        .into_iter()
                        .filter(|asset| {
                            !item.get("document_id").and_then(Value::as_str).is_some_and(
                                |document_id| {
                                    asset.get("id").and_then(Value::as_str).is_some_and(
                                        |asset_id| asset_is_inline(project, document_id, asset_id),
                                    )
                                },
                            )
                        })
                        .collect();
                if !assets.is_empty() {
                    body.push_str("<div class=\"assets\"><h3>素材</h3>");
                    for asset in assets {
                        let title = escape_html(
                            asset
                                .get("title")
                                .or_else(|| asset.get("filename"))
                                .and_then(Value::as_str)
                                .unwrap_or("素材"),
                        );
                        let path = escape_html(
                            asset
                                .get("storage_path")
                                .and_then(Value::as_str)
                                .unwrap_or_default(),
                        );
                        match asset.get("type").and_then(Value::as_str) {
                            Some("image" | "gif") => body.push_str(&format!(
                                "<figure><img src=\"{path}\" alt=\"{title}\"><figcaption>{title}</figcaption></figure>"
                            )),
                            Some("video") => body.push_str(&format!(
                                "<figure><video controls src=\"{path}\"></video><figcaption>{title}</figcaption></figure>"
                            )),
                            Some("audio") => body.push_str(&format!(
                                "<figure><audio controls src=\"{path}\"></audio><figcaption>{title}</figcaption></figure>"
                            )),
                            _ => body.push_str(&format!(
                                "<p><a href=\"{path}\">{title}</a></p>"
                            )),
                        }
                    }
                    body.push_str("</div>");
                }
            }
            body.push_str("</section>");
        }
    }
    format!(
        "<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>{}</title><style>body{{max-width:760px;margin:2rem auto;padding:0 1rem;font:16px/1.7 system-ui,sans-serif}}section{{margin:2rem 0}}blockquote{{border-left:3px solid #bbb;padding-left:1rem}}.待补内容{{padding:.75rem;background:#fff5dc}}</style></head><body><h1>{}</h1>{}</body></html>\n",
        escape_html(title),
        escape_html(title),
        body
    )
}

fn structured_boundary_error(code: &str, user_message: &str, details: Value) -> String {
    structured_ai_error(code, user_message, None, details)
}

/// 与 [`structured_boundary_error`] 完全同一形状，另外允许给出「下一步怎么做」的建议。
fn structured_ai_error(
    code: &str,
    user_message: &str,
    recommended_action: Option<&str>,
    details: Value,
) -> String {
    json!({
        "error": {
            "code": code,
            "user_message": user_message,
            "technical_message": user_message,
            "severity": "blocking",
            "recoverable": false,
            "recommended_action": recommended_action,
            "details": details,
        }
    })
    .to_string()
}

fn export_content_item_id(
    project: &Value,
    preset_object: &Map<String, Value>,
    options: Option<&Value>,
) -> Result<Option<String>, String> {
    let options_object = match options {
        None | Some(Value::Null) => None,
        Some(value) => Some(require_object(value, "export_options")?),
    };
    let raw = field(preset_object, &["content_item_id", "contentItemId"])
        .filter(|value| !value.is_null())
        .or_else(|| {
            options_object
                .and_then(|object| field(object, &["content_item_id", "contentItemId"]))
                .filter(|value| !value.is_null())
        });
    let Some(raw) = raw else {
        return Ok(None);
    };
    let Some(content_item_id) = raw
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Err(structured_boundary_error(
            "invalid_content_item_id",
            "导出内容项 ID 必须是非空字符串。",
            json!({}),
        ));
    };
    let exists = project
        .get("content_items")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .any(|item| item.get("id").and_then(Value::as_str) == Some(content_item_id))
        })
        .unwrap_or(false);
    if !exists {
        return Err(structured_boundary_error(
            "content_item_not_found",
            "指定的导出内容项不存在。",
            json!({ "content_item_id": content_item_id }),
        ));
    }
    Ok(Some(content_item_id.to_owned()))
}

const PPTX_IMAGE_READ_LIMIT: u64 = 64 * 1024 * 1024;

fn export_revision(project: &Value) -> &str {
    project
        .get("project")
        .and_then(|value| value.get("updated_at"))
        .and_then(Value::as_str)
        .unwrap_or("")
}

fn has_paged_layout(project: &Value, content_item_id: Option<&str>) -> bool {
    project
        .get("layout_instances")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .any(|layout| {
            layout.get("pagination_mode").and_then(Value::as_str) == Some("paged")
                && content_item_id.map_or(true, |id| {
                    layout.get("content_item_id").and_then(Value::as_str) == Some(id)
                })
        })
}

fn canonical_export_asset_path(
    project: &Value,
    project_dir: &Path,
    asset_id: &str,
) -> Result<PathBuf, String> {
    let asset = project
        .get("assets")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .find(|asset| asset.get("id").and_then(Value::as_str) == Some(asset_id))
        .ok_or_else(|| format!("投影引用了不存在的素材：{asset_id}"))?;
    if asset.get("archived").and_then(Value::as_bool) == Some(true) {
        return Err(format!("投影引用了已归档的素材：{asset_id}"));
    }
    let storage_path = asset
        .get("storage_path")
        .and_then(Value::as_str)
        .ok_or_else(|| format!("素材缺少项目内路径：{asset_id}"))?;
    let relative = Path::new(storage_path);
    let mut components = relative.components();
    if relative.is_absolute()
        || !matches!(components.next(), Some(Component::Normal(name)) if name == "assets")
        || components.any(|component| !matches!(component, Component::Normal(_)))
    {
        return Err(format!("素材路径不安全：{asset_id}"));
    }
    let mut target = project_dir.to_path_buf();
    for component in relative.components() {
        target.push(component.as_os_str());
        reject_symlink(&target, "项目素材")?;
    }
    let real_root =
        fs::canonicalize(project_dir).map_err(|error| format!("无法解析项目目录：{error}"))?;
    let real_target =
        fs::canonicalize(&target).map_err(|error| format!("无法读取项目素材：{error}"))?;
    if !real_target.starts_with(&real_root) {
        return Err("项目素材路径超出项目目录".into());
    }
    let metadata =
        fs::metadata(&real_target).map_err(|error| format!("无法读取项目素材：{error}"))?;
    if !metadata.is_file() {
        return Err("项目素材路径不是文件".into());
    }
    Ok(real_target)
}

fn projection_media<'a>(projection: &'a Value, id: &str) -> Option<&'a Value> {
    projection
        .get("media")
        .and_then(Value::as_array)
        .and_then(|media| {
            media
                .iter()
                .find(|item| item.get("id").and_then(Value::as_str) == Some(id))
        })
}

fn projection_matches_options(projection: &Value, options: Option<&Value>) -> bool {
    let Some(options) = options.and_then(Value::as_object) else {
        return true;
    };
    let selection = projection.get("selection").unwrap_or(&Value::Null);
    for (option_key, projection_key) in [
        ("layout_instance_id", "layout_instance_id"),
        ("page_ids", "page_ids"),
    ] {
        if let Some(expected) = options.get(option_key) {
            let actual = selection.get(projection_key).unwrap_or(&Value::Null);
            if actual != expected {
                return false;
            }
        }
    }
    if let Some(expected) = options.get("target_page_size") {
        if projection.get("target_page_size").unwrap_or(&Value::Null) != expected {
            return false;
        }
    }
    true
}

fn validate_projection_media(
    projection: &Value,
    project: &Value,
    project_dir: &Path,
    format: &str,
) -> Vec<Value> {
    let mut errors = Vec::new();
    for id in paged_export::selected_media_ids(projection) {
        let media = projection_media(projection, &id);
        let resolved = canonical_export_asset_path(project, project_dir, &id);
        match resolved {
            Ok(path) if format == "pptx" => {
                let kind = media
                    .and_then(|value| value.get("type"))
                    .and_then(Value::as_str)
                    .unwrap_or("");
                if matches!(kind, "image" | "gif") {
                    match fs::metadata(&path) {
                        Ok(metadata) if metadata.len() <= PPTX_IMAGE_READ_LIMIT => {}
                        Ok(_) => errors.push(json!({
                            "code": "asset_too_large",
                            "asset_id": id,
                            "message": "PPTX 图片超过 64 MB 的原生读取上限。"
                        })),
                        Err(error) => errors.push(json!({
                            "code": "missing_asset",
                            "asset_id": id,
                            "message": format!("无法读取 PPTX 图片：{error}")
                        })),
                    }
                }
            }
            Ok(_) => {}
            Err(error) => errors.push(json!({
                "code": "missing_asset",
                "asset_id": id,
                "message": error
            })),
        }
    }
    errors
}

fn export_preflight_report(
    preset: &Value,
    options: Option<&Value>,
) -> Result<(Value, Value, PathBuf, String), String> {
    let object = require_object(preset, "export_preflight")?;
    let project_dir = required_string(object, &["project_dir", "projectDir"], "项目目录")?;
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let project = read_project_value(&project_dir)?;
    let content_item_id = export_content_item_id(&project, object, options)?;
    let format = export_format(preset)?;
    let filename = output_filename(preset, &project, &format);
    let output_path = if let Some(raw) = field(
        object,
        &["output_path", "outputPath", "target_path", "targetPath"],
    )
    .and_then(Value::as_str)
    .map(str::trim)
    .filter(|value| !value.is_empty())
    {
        let path = PathBuf::from(raw);
        if !path.is_absolute() {
            return Err("导出目标必须是用户明确选择的绝对路径".into());
        }
        let parent = path.parent().ok_or("导出目标父目录无效")?;
        let parent = ensure_directory(parent, "导出目标目录")?;
        if path.exists()
            && fs::metadata(&path)
                .map_err(|error| format!("无法读取导出目标: {error}"))?
                .is_dir()
        {
            return Err("导出目标必须是文件路径".into());
        }
        let target = parent.join(path.file_name().ok_or("导出目标文件名无效")?);
        reject_symlink(&target, "导出目标")?;
        target
    } else {
        let output_dir = required_string(object, &["output_dir", "outputDir"], "导出目录")?;
        explicit_project_dir(&output_dir, true)?.join(filename)
    };
    reject_symlink(&output_path, "导出目标")?;
    let mut errors = Vec::new();
    let mut warnings = Vec::new();
    let revision = export_revision(&project);
    let option_object = options.and_then(Value::as_object);
    let projection = option_object
        .and_then(|object| object.get("projection"))
        .filter(|value| value.is_object());
    let page_aware_format = matches!(format.as_str(), "pdf" | "html" | "web" | "pptx");
    if page_aware_format {
        let selected_layout_id = option_object
            .and_then(|object| object.get("layout_instance_id"))
            .and_then(Value::as_str)
            .or_else(|| {
                field(object, &["layout_instance_id", "layoutInstanceId"]).and_then(Value::as_str)
            });
        match paged_export::legacy_grid_section_notices(
            &project,
            content_item_id.as_deref(),
            selected_layout_id,
        ) {
            Ok(notices) => {
                for notice in notices {
                    errors.push(json!({
                        "code": "legacy_grid_sections_require_pagination",
                        "layout_instance_id": notice.get("layout_instance_id"),
                        "section_ids": notice.get("section_ids"),
                        "includes_unsectioned": notice.get("includes_unsectioned"),
                        "message": notice.get("message")
                    }));
                }
            }
            Err(message) => errors.push(json!({
                "code": "canonical_invalid",
                "message": message
            })),
        }
    }
    let require_projection = page_aware_format
        && (format == "pptx" || has_paged_layout(&project, content_item_id.as_deref()));
    if page_aware_format && projection.is_none() && require_projection {
        errors.push(json!({
            "code": "missing_projection",
            "message": "分页导出缺少冻结的页面投影，请重新打开预检后再试。"
        }));
    }
    if let Some(snapshot_revision) = option_object
        .and_then(|object| object.get("snapshot_revision"))
        .and_then(Value::as_str)
    {
        if snapshot_revision != revision {
            errors.push(json!({
                "code": "stale_projection",
                "message": "课程内容在预检后发生变化，请重新预检并确认导出警告。"
            }));
        }
    }
    let mut projected_media_ids = HashSet::new();
    if let Some(projection) = projection.filter(|_| page_aware_format) {
        if !projection_matches_options(projection, options) {
            errors.push(json!({
                "code": "projection_selection_mismatch",
                "message": "冻结的页面范围与当前导出选择不一致，请重新预检。"
            }));
        }
        match paged_export::validate_projection(
            projection,
            &project,
            content_item_id.as_deref(),
            &format,
        ) {
            Ok(()) => {}
            Err(message) => {
                let needs_target_page_size =
                    message == paged_export::EXPLICIT_TARGET_PAGE_SIZE_REQUIRED;
                errors.push(json!({
                    "code": if needs_target_page_size {
                        paged_export::EXPLICIT_TARGET_PAGE_SIZE_REQUIRED
                    } else {
                        "invalid_projection"
                    },
                    "message": if needs_target_page_size {
                        "所选课时页面尺寸不同；请指定统一的输出页面尺寸后重试。"
                    } else {
                        message.as_str()
                    }
                }));
            }
        }
        projected_media_ids = paged_export::selected_media_ids(projection)
            .into_iter()
            .collect::<HashSet<_>>();
        errors.extend(validate_projection_media(
            projection,
            &project,
            &project_dir,
            &format,
        ));
        let unplaced = paged_export::unplaced_block_ids(projection);
        let unplaced_attachments = if format == "pptx" {
            paged_export::unplaced_attachment_ids(projection)
        } else {
            Vec::new()
        };
        if !unplaced.is_empty() || !unplaced_attachments.is_empty() {
            let count = unplaced.len() + unplaced_attachments.len();
            let message = if unplaced_attachments.is_empty() {
                format!(
                    "仍有 {} 块正文尚未放置；本次仅输出已排版内容。",
                    unplaced.len()
                )
            } else {
                format!(
                    "仍有 {} 块正文与 {} 个素材附件尚未放入页面；本次仅输出已排版内容。",
                    unplaced.len(),
                    unplaced_attachments.len()
                )
            };
            warnings.push(json!({
                "code": "unplaced_content",
                "count": count,
                "block_ids": unplaced,
                "attachment_ids": unplaced_attachments,
                "message": message
            }));
        }
        if format == "pptx" && paged_export::has_simplified_pptx_semantics(projection) {
            warnings.push(json!({
                "code": "rich_text_structure_simplified",
                "message": "PPTX 会保留可编辑文字、行内强调与图片；Markdown 表格及嵌套列表将展平为可编辑文本，结构布局可能简化。"
            }));
        }
        if let Some(assets) = project.get("assets").and_then(Value::as_array) {
            for asset in assets {
                if !asset
                    .get("id")
                    .and_then(Value::as_str)
                    .is_some_and(|id| projected_media_ids.contains(id))
                {
                    continue;
                }
                let asset_type = asset.get("type").and_then(Value::as_str).unwrap_or("other");
                let downgraded = (format == "pdf"
                    && matches!(asset_type, "video" | "audio" | "document" | "other" | "gif"))
                    || (format == "pptx"
                        && matches!(asset_type, "gif" | "video" | "audio" | "document" | "other"));
                if downgraded {
                    warnings.push(json!({
                        "code": "media_downgrade",
                        "asset_id": asset.get("id"),
                        "message": "该媒体在当前格式中将以附件卡片呈现"
                    }));
                }
            }
        }
    }
    if let Some(requirements) = project.get("requirements").and_then(Value::as_array) {
        let open_content = requirements
            .iter()
            .filter(|requirement| {
                requirement.get("status").and_then(Value::as_str) == Some("open")
                    && requirement.get("scope").and_then(Value::as_str) == Some("content")
                    && content_item_id.as_deref().map_or(true, |id| {
                        requirement.get("content_item_id").and_then(Value::as_str) == Some(id)
                    })
            })
            .count();
        if open_content > 0 {
            warnings.push(json!({
                "code": "open_content_requirements",
                "count": open_content,
                "message": "仍有待补正文要求"
            }));
        }
        let open_layout = requirements
            .iter()
            .filter(|requirement| {
                requirement.get("status").and_then(Value::as_str) == Some("open")
                    && requirement.get("scope").and_then(Value::as_str) == Some("layout")
                    && content_item_id.as_deref().map_or(true, |id| {
                        requirement.get("content_item_id").and_then(Value::as_str) == Some(id)
                    })
            })
            .count();
        if open_layout > 0 {
            warnings.push(json!({
                "code": "open_layout_requirements",
                "count": open_layout,
                "message": "仍有待补排版要求"
            }));
        }
    }
    if let Some(assets) = project.get("assets").and_then(Value::as_array) {
        let include_all_assets = matches!(format.as_str(), "asset_package" | "full_project");
        for asset in assets {
            let Some(asset_id) = asset.get("id").and_then(Value::as_str) else {
                continue;
            };
            if page_aware_format && projection.is_some() && !projected_media_ids.contains(asset_id)
            {
                continue;
            }
            if !include_all_assets
                && !asset_selected_for_content(&project, asset_id, content_item_id.as_deref())
            {
                continue;
            }
            let asset_type = asset.get("type").and_then(Value::as_str).unwrap_or("other");
            let downgraded = !(page_aware_format && projection.is_some())
                && matches!(format.as_str(), "markdown" | "pdf" | "wechat")
                && (matches!(asset_type, "video" | "audio" | "document" | "other")
                    || (format == "pdf" && asset_type == "gif"));
            if downgraded {
                warnings.push(json!({
                    "code": "media_downgrade",
                    "asset_id": asset_id,
                    "message": "该媒体在当前格式中将以非交互附件说明呈现"
                }));
            }
            if asset
                .get("source_url")
                .and_then(Value::as_str)
                .is_some_and(|url| url.starts_with("http://") || url.starts_with("https://"))
            {
                warnings.push(json!({
                    "code": "external_references",
                    "asset_id": asset_id,
                    "message": "外部素材链接不会被验证"
                }));
            }
            if page_aware_format && projection.is_some() {
                continue;
            }
            let Some(storage_path) = asset.get("storage_path").and_then(Value::as_str) else {
                continue;
            };
            let path = Path::new(storage_path);
            if path.is_absolute()
                || path
                    .components()
                    .any(|component| !matches!(component, Component::Normal(_)))
            {
                errors.push(json!({ "code": "invalid_asset_path", "message": "项目素材必须使用项目内相对路径" }));
            } else {
                let resolved = project_dir.join(path);
                if reject_symlink(&resolved, "项目素材").is_err() || !resolved.exists() {
                    errors.push(json!({ "code": "missing_asset", "message": "项目素材文件不存在", "path": storage_path }));
                }
            }
        }
    }
    let acknowledgement_value =
        option_object.and_then(|object| object.get("acknowledged_warnings"));
    if acknowledgement_value.is_some_and(|value| !value.is_array()) {
        errors.push(json!({
            "code": "invalid_warning_acknowledgement",
            "message": "导出警告确认格式无效，请重新预检。"
        }));
    }
    let ack_values = acknowledgement_value
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let acknowledged = ack_values
        .iter()
        .filter_map(Value::as_str)
        .collect::<HashSet<_>>();
    if acknowledged.len() != ack_values.len() {
        errors.push(json!({
            "code": "invalid_warning_acknowledgement",
            "message": "导出警告确认包含无效项目。"
        }));
    }
    if !acknowledged.is_empty() {
        if option_object
            .and_then(|object| object.get("snapshot_revision"))
            .and_then(Value::as_str)
            != Some(revision)
        {
            errors.push(json!({
                "code": "stale_warning_acknowledgement",
                "message": "导出警告确认没有绑定到当前课程版本，请重新预检。"
            }));
        }
        let current_codes = warnings
            .iter()
            .filter_map(|warning| warning.get("code").and_then(Value::as_str))
            .collect::<HashSet<_>>();
        const KNOWN_CODES: &[&str] = &[
            "open_content_requirements",
            "open_layout_requirements",
            "empty_text",
            "external_references",
            "media_downgrade",
            "unplaced_content",
            "layout_linearized",
            "open_requirements",
            "external_reference",
            "rich_text_structure_simplified",
        ];
        if acknowledged
            .iter()
            .any(|code| !current_codes.contains(code) && !KNOWN_CODES.contains(code))
        {
            errors.push(json!({
                "code": "invalid_warning_acknowledgement",
                "message": "导出警告确认与当前预检结果不一致，请重新预检。"
            }));
        }
    }
    let report = json!({
        "ok": errors.is_empty(),
        "errors": errors,
        "warnings": warnings,
        "format": format,
        "content_item_id": content_item_id,
        "snapshot_revision": revision,
        "output_path": output_path,
        "target_path": output_path,
    });
    Ok((project, report, output_path, format))
}

#[tauri::command]
fn export_preflight(preset: Value, options: Option<Value>) -> Result<Value, String> {
    let (_, report, _, _) = export_preflight_report(&preset, options.as_ref())?;
    Ok(report)
}

fn selected_export_assets<'a>(
    project: &'a Value,
    content_item_id: Option<&str>,
    include_all: bool,
) -> Vec<&'a Value> {
    project
        .get("assets")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(|asset| {
            !asset
                .get("archived")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        })
        .filter(|asset| {
            include_all
                || asset
                    .get("id")
                    .and_then(Value::as_str)
                    .map(|id| {
                        if let Some(content_item_id) = content_item_id {
                            asset_selected_for_content(project, id, Some(content_item_id))
                        } else {
                            project
                                .get("asset_usages")
                                .and_then(Value::as_array)
                                .is_some_and(|usages| {
                                    usages.iter().any(|usage| {
                                        usage.get("asset_id").and_then(Value::as_str) == Some(id)
                                    })
                                })
                                || project
                                    .get("requirements")
                                    .and_then(Value::as_array)
                                    .is_some_and(|requirements| {
                                        requirements.iter().any(|requirement| {
                                            requirement
                                                .get("resolved_asset_id")
                                                .and_then(Value::as_str)
                                                == Some(id)
                                        })
                                    })
                        }
                    })
                    .unwrap_or(false)
        })
        .collect()
}

fn copy_export_assets(
    project: &Value,
    project_dir: &Path,
    destination_root: &Path,
    content_item_id: Option<&str>,
    include_all: bool,
) -> Result<Vec<String>, String> {
    let mut copied = Vec::new();
    for asset in selected_export_assets(project, content_item_id, include_all) {
        let storage_path = asset
            .get("storage_path")
            .and_then(Value::as_str)
            .ok_or("素材缺少项目内路径")?;
        let relative = Path::new(storage_path);
        if relative.is_absolute()
            || relative
                .components()
                .any(|component| !matches!(component, Component::Normal(_)))
        {
            return Err("项目素材必须使用安全的项目内相对路径".into());
        }
        let source = project_dir.join(relative);
        reject_symlink(&source, "项目素材")?;
        if !source.is_file() {
            return Err(format!("项目素材文件不存在：{storage_path}"));
        }
        let target = destination_root.join(relative);
        let same_file = source == target
            || (target.exists()
                && fs::canonicalize(&source).ok() == fs::canonicalize(&target).ok());
        if same_file {
            // A single-file export beside the project may already reference the
            // canonical assets directory. Copying a file onto itself truncates
            // it on macOS; skip it so export remains strictly read-only.
            copied.push(storage_path.replace('\\', "/"));
            continue;
        }
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent).map_err(|error| format!("无法创建素材导出目录: {error}"))?;
        }
        fs::copy(&source, &target).map_err(|error| format!("无法复制导出素材: {error}"))?;
        copied.push(storage_path.replace('\\', "/"));
    }
    copied.sort();
    copied.dedup();
    Ok(copied)
}

fn safe_projection_output_path(media: &Value) -> Result<PathBuf, String> {
    let raw = media
        .get("output_path")
        .and_then(Value::as_str)
        .ok_or("投影素材缺少输出路径")?;
    let relative = Path::new(raw);
    if raw.contains('\\')
        || relative.is_absolute()
        || relative.as_os_str().is_empty()
        || relative
            .components()
            .any(|component| !matches!(component, Component::Normal(_)))
    {
        return Err("投影素材输出路径不安全".into());
    }
    Ok(relative.to_path_buf())
}

fn projection_media_sources(projection: &Value) -> Result<HashMap<String, String>, String> {
    let mut sources = HashMap::new();
    for id in paged_export::selected_media_ids(projection) {
        let media = projection_media(projection, &id).ok_or("投影素材缺少媒体记录")?;
        let relative = safe_projection_output_path(media)?;
        sources.insert(id, relative.to_string_lossy().replace('\\', "/"));
    }
    Ok(sources)
}

fn copy_projection_assets(
    projection: &Value,
    project: &Value,
    project_dir: &Path,
    destination_root: &Path,
) -> Result<Vec<String>, String> {
    let destination_root = fs::canonicalize(destination_root)
        .map_err(|error| format!("无法解析素材输出目录：{error}"))?;
    let mut copied = Vec::new();
    for id in paged_export::selected_media_ids(projection) {
        let media = projection_media(projection, &id).ok_or("投影素材缺少媒体记录")?;
        let relative = safe_projection_output_path(media)?;
        let source = canonical_export_asset_path(project, project_dir, &id)?;
        let target = destination_root.join(&relative);
        let mut cursor = destination_root.clone();
        let components: Vec<_> = relative.components().collect();
        for (index, component) in components.iter().enumerate() {
            cursor.push(component.as_os_str());
            reject_symlink(&cursor, "素材输出路径")?;
            if index + 1 < components.len() && !cursor.exists() {
                fs::create_dir(&cursor)
                    .map_err(|error| format!("无法创建素材输出目录：{error}"))?;
            }
            if index + 1 < components.len() && !cursor.is_dir() {
                return Err("素材输出路径的父级不是目录".into());
            }
        }
        if target.exists() {
            let real_target = fs::canonicalize(&target)
                .map_err(|error| format!("无法解析素材输出路径：{error}"))?;
            if real_target == source {
                copied.push(relative.to_string_lossy().replace('\\', "/"));
                continue;
            }
            return Err(format!(
                "素材输出路径已存在，请选择新的导出位置：{}",
                relative.display()
            ));
        }
        let parent = target.parent().ok_or("素材输出路径的父目录无效")?;
        let real_parent =
            fs::canonicalize(parent).map_err(|error| format!("无法解析素材输出目录：{error}"))?;
        if !real_parent.starts_with(&destination_root) {
            return Err("素材输出路径超出导出目录".into());
        }
        fs::copy(&source, &target).map_err(|error| format!("无法复制导出素材：{error}"))?;
        copied.push(relative.to_string_lossy().replace('\\', "/"));
    }
    copied.sort();
    copied.dedup();
    Ok(copied)
}

fn load_pptx_media(
    projection: &Value,
    project: &Value,
    project_dir: &Path,
) -> Result<HashMap<String, (String, Vec<u8>)>, String> {
    const PPTX_MEDIA_TOTAL_LIMIT: u64 = 256 * 1024 * 1024;
    let mut total = 0_u64;
    let mut result = HashMap::new();
    for id in paged_export::selected_media_ids(projection) {
        let media = projection_media(projection, &id).ok_or("投影素材缺少媒体记录")?;
        if media.get("type").and_then(Value::as_str) != Some("image") {
            continue;
        }
        let source = canonical_export_asset_path(project, project_dir, &id)?;
        let metadata =
            fs::metadata(&source).map_err(|error| format!("无法读取 PPTX 图片：{error}"))?;
        total = total.saturating_add(metadata.len());
        if total > PPTX_MEDIA_TOTAL_LIMIT {
            return Err("PPTX 图片总量超过 256 MB 的原生读取上限。".into());
        }
        let bytes = fs::read(&source).map_err(|error| format!("无法读取 PPTX 图片：{error}"))?;
        let mime = media
            .get("mime_type")
            .and_then(Value::as_str)
            .or_else(|| {
                project
                    .get("assets")
                    .and_then(Value::as_array)
                    .and_then(|assets| {
                        assets.iter().find(|asset| {
                            asset.get("id").and_then(Value::as_str) == Some(id.as_str())
                        })
                    })
                    .and_then(|asset| asset.get("mime_type"))
                    .and_then(Value::as_str)
            })
            .unwrap_or("application/octet-stream")
            .to_owned();
        result.insert(id, (mime, bytes));
    }
    Ok(result)
}

fn print_projection_pdf(
    html: &str,
    projection: &Value,
    project: &Value,
    project_dir: &Path,
    output_path: &Path,
) -> Result<(), String> {
    let chrome = chrome_binary()
        .ok_or("PDF 导出需要本机 Google Chrome/Chromium 打印引擎；请安装后重试，或先导出 HTML。")?;
    let staging = unique_export_staging(output_path)?;
    fs::create_dir_all(&staging).map_err(|error| format!("无法创建 PDF 临时目录：{error}"))?;
    let result = (|| {
        let html_path = staging.join("index.html");
        fs::write(&html_path, html).map_err(|error| format!("无法写入 PDF 临时页面：{error}"))?;
        copy_projection_assets(projection, project, project_dir, &staging)?;
        let pdf_path = staging.join("result.pdf");
        let file_url = format!("file://{}", html_path.to_string_lossy());
        let status = ProcessCommand::new(chrome)
            .args([
                "--headless=new",
                "--disable-gpu",
                "--allow-file-access-from-files",
                "--no-pdf-header-footer",
                &format!("--print-to-pdf={}", pdf_path.to_string_lossy()),
                &file_url,
            ])
            .status()
            .map_err(|error| format!("无法启动 PDF 打印引擎：{error}"))?;
        if !status.success() || !pdf_path.is_file() {
            return Err("PDF 打印引擎没有生成可用文件；未修改源项目，请重试或导出 HTML。".into());
        }
        let bytes = fs::read(&pdf_path).map_err(|error| format!("无法读取 PDF 输出：{error}"))?;
        if !bytes.starts_with(b"%PDF-") || bytes.len() < 1024 {
            return Err("PDF 输出验证失败；临时文件已清理。".into());
        }
        atomic_write_bytes_path(output_path, &bytes)
    })();
    let _ = fs::remove_dir_all(&staging);
    result
}

fn unique_export_staging(target: &Path) -> Result<PathBuf, String> {
    let parent = target.parent().ok_or("导出目标父目录无效")?;
    let name = target
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("export");
    Ok(parent.join(format!(".{name}.acw-{}.tmp", native_id("export"))))
}

fn sanitized_project_package(project: &Value) -> Value {
    let mut value = project.clone();
    if let Some(object) = value.as_object_mut() {
        for key in [
            "conversation_sources",
            "conversations",
            "messages",
            "context_packs",
            "context_pack_items",
        ] {
            object.insert(key.into(), Value::Array(Vec::new()));
        }
    }
    value
}

fn chrome_binary() -> Option<PathBuf> {
    [
        "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
        "/Applications/Chromium.app/Contents/MacOS/Chromium",
    ]
    .iter()
    .map(PathBuf::from)
    .find(|path| path.is_file())
}

fn print_html_pdf(
    html: &str,
    project: &Value,
    project_dir: &Path,
    output_path: &Path,
    content_item_id: Option<&str>,
) -> Result<(), String> {
    let chrome = chrome_binary()
        .ok_or("PDF 导出需要本机 Google Chrome/Chromium 打印引擎；请安装后重试，或先导出 HTML。")?;
    let staging = unique_export_staging(output_path)?;
    fs::create_dir_all(&staging).map_err(|error| format!("无法创建 PDF 临时目录: {error}"))?;
    let result = (|| {
        let html_path = staging.join("index.html");
        fs::write(&html_path, html).map_err(|error| format!("无法写入 PDF 临时页面: {error}"))?;
        copy_export_assets(project, project_dir, &staging, content_item_id, false)?;
        let pdf_path = staging.join("result.pdf");
        let file_url = format!("file://{}", html_path.to_string_lossy());
        let status = ProcessCommand::new(chrome)
            .args([
                "--headless=new",
                "--disable-gpu",
                "--allow-file-access-from-files",
                "--no-pdf-header-footer",
                &format!("--print-to-pdf={}", pdf_path.to_string_lossy()),
                &file_url,
            ])
            .status()
            .map_err(|error| format!("无法启动 PDF 打印引擎: {error}"))?;
        if !status.success() || !pdf_path.is_file() {
            return Err("PDF 打印引擎没有生成可用文件；未修改源项目，请重试或导出 HTML。".into());
        }
        let bytes = fs::read(&pdf_path).map_err(|error| format!("无法读取 PDF 输出: {error}"))?;
        if !bytes.starts_with(b"%PDF-") || bytes.len() < 1024 {
            return Err("PDF 输出验证失败；临时文件已清理。".into());
        }
        atomic_write_bytes_path(output_path, &bytes)
    })();
    let _ = fs::remove_dir_all(&staging);
    result
}

#[tauri::command]
fn export_run(preset: Value, options: Option<Value>) -> Result<Value, String> {
    let object = require_object(&preset, "export_run")?;
    let project_dir = required_string(object, &["project_dir", "projectDir"], "项目目录")?;
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let _lease_guard = require_active_project_lock(&project_dir)?;
    let (project, report, output_path, format) =
        export_preflight_report(&preset, options.as_ref())?;
    if !report.get("ok").and_then(Value::as_bool).unwrap_or(false) {
        return Err(structured_boundary_error(
            "export_blocked",
            "导出前检查发现严重问题，请先修复后重试。",
            report.clone(),
        ));
    }
    let acknowledged = options
        .as_ref()
        .and_then(|value| value.get("acknowledged_warnings"))
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .collect::<HashSet<_>>();
    let unacknowledged = report
        .get("warnings")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|warning| warning.get("code").and_then(Value::as_str))
        .filter(|code| !acknowledged.contains(code))
        .collect::<Vec<_>>();
    if !unacknowledged.is_empty() {
        return Err(structured_boundary_error(
            "export_warnings_unacknowledged",
            "请先在导出预检中确认所有警告，然后使用同一课程版本重新导出。",
            report.clone(),
        ));
    }
    let content_item_id = report.get("content_item_id").and_then(Value::as_str);
    let projection = options
        .as_ref()
        .and_then(|value| value.get("projection"))
        .filter(|value| value.is_object());
    let mut exported_files: Vec<Value> = Vec::new();
    let mut total_bytes = 0_u64;
    match format.as_str() {
        "markdown" | "html" | "wechat" => {
            let mut projection_copied = None;
            let contents = if format == "markdown" {
                markdown_for_project(&project, content_item_id)
            } else if format == "html" {
                if let Some(projection) = projection {
                    let sources = projection_media_sources(projection)?;
                    let parent = output_path.parent().ok_or("导出目标父目录无效")?;
                    projection_copied = Some(copy_projection_assets(
                        projection,
                        &project,
                        &project_dir,
                        parent,
                    )?);
                    paged_export::render_html(projection, &sources, false)?
                } else {
                    html_for_project(&project, content_item_id)
                }
            } else {
                let html = html_for_project(&project, content_item_id);
                if format == "wechat" {
                    html.replacen(
                        "<body>",
                        "<body><p style=\"padding:12px;border:1px solid #ddd\">富文本迁移版：图片/GIF 可复制；视频、音频和文档需在目标平台单独上传，平台可能调整字体与间距。</p>",
                        1,
                    )
                } else {
                    html
                }
            };
            atomic_write_path(&output_path, &contents, false)?;
            let copied = if let Some(copied) = projection_copied {
                copied
            } else {
                let parent = output_path.parent().ok_or("导出目标父目录无效")?;
                copy_export_assets(&project, &project_dir, parent, content_item_id, false)?
            };
            total_bytes = contents.len() as u64;
            exported_files.push(json!({
                "relative_path": output_path.file_name().and_then(|value| value.to_str()).unwrap_or("export"),
                "path": output_path,
                "mime_type": if format == "markdown" { "text/markdown" } else { "text/html" },
                "bytes": { "__bytes_base64": encode_base64(contents.as_bytes()) },
            }));
            exported_files.extend(copied.into_iter().map(|path| {
                json!({
                    "relative_path": path,
                    "mime_type": "application/octet-stream",
                })
            }));
        }
        "json" => {
            let safe = sanitized_project_package(&project);
            let contents =
                serde_json::to_string_pretty(&safe).map_err(|error| error.to_string())? + "\n";
            atomic_write_path(&output_path, &contents, false)?;
            total_bytes = contents.len() as u64;
            exported_files.push(json!({
                "relative_path": output_path.file_name().and_then(|value| value.to_str()).unwrap_or("project.json"),
                "path": output_path,
                "mime_type": "application/json",
                "bytes": { "__bytes_base64": encode_base64(contents.as_bytes()) },
            }));
        }
        "pdf" => {
            if let Some(projection) = projection {
                let sources = projection_media_sources(projection)?;
                let html = paged_export::render_html(projection, &sources, true)?;
                print_projection_pdf(&html, projection, &project, &project_dir, &output_path)?;
            } else {
                let html = html_for_project(&project, content_item_id);
                print_html_pdf(&html, &project, &project_dir, &output_path, content_item_id)?;
            }
            total_bytes = fs::metadata(&output_path)
                .map_err(|error| format!("无法检查 PDF 输出: {error}"))?
                .len();
            exported_files.push(json!({
                "relative_path": output_path.file_name().and_then(|value| value.to_str()).unwrap_or("course.pdf"),
                "path": output_path,
                "mime_type": "application/pdf",
            }));
        }
        "pptx" => {
            let projection = projection.ok_or("PPTX 导出缺少页面投影，请重新预检后重试。")?;
            let media = load_pptx_media(projection, &project, &project_dir)?;
            let bytes = paged_export::render_pptx(projection, &media)?;
            atomic_write_bytes_path(&output_path, &bytes)?;
            total_bytes = bytes.len() as u64;
            exported_files.push(json!({
                "relative_path": output_path.file_name().and_then(|value| value.to_str()).unwrap_or("course.pptx"),
                "path": output_path,
                "mime_type": "application/vnd.openxmlformats-officedocument.presentationml.presentation",
            }));
        }
        "web" | "asset_package" | "full_project" => {
            if output_path.exists() {
                return Err("导出目录已存在；为避免覆盖有效文件，请选择新的名称。".into());
            }
            let staging = unique_export_staging(&output_path)?;
            fs::create_dir_all(&staging)
                .map_err(|error| format!("无法创建导出临时目录: {error}"))?;
            let build = (|| -> Result<(), String> {
                let copied = if format == "web" {
                    if let Some(projection) = projection {
                        copy_projection_assets(projection, &project, &project_dir, &staging)?
                    } else {
                        copy_export_assets(
                            &project,
                            &project_dir,
                            &staging,
                            content_item_id,
                            false,
                        )?
                    }
                } else {
                    copy_export_assets(&project, &project_dir, &staging, content_item_id, true)?
                };
                if format == "web" {
                    let html = if let Some(projection) = projection {
                        let sources = projection_media_sources(projection)?;
                        paged_export::render_html(projection, &sources, false)?
                    } else {
                        html_for_project(&project, content_item_id)
                    };
                    fs::write(staging.join("index.html"), html.as_bytes())
                        .map_err(|error| format!("无法写入网页入口: {error}"))?;
                    let manifest = json!({
                        "schema_version": 1,
                        "project_id": project.get("project").and_then(|value| value.get("id")),
                        "scope": if content_item_id.is_some() { "lesson" } else { "course" },
                        "content_item_id": content_item_id,
                        "entrypoint": "index.html",
                        "assets": copied,
                    });
                    fs::write(
                        staging.join("manifest.json"),
                        serde_json::to_vec_pretty(&manifest).map_err(|error| error.to_string())?,
                    )
                    .map_err(|error| format!("无法写入网页 manifest: {error}"))?;
                } else {
                    let manifest = json!({
                        "schema_version": 1,
                        "project_id": project.get("project").and_then(|value| value.get("id")),
                        "assets": copied,
                    });
                    fs::write(
                        staging.join("assets-manifest.json"),
                        serde_json::to_vec_pretty(&manifest).map_err(|error| error.to_string())?,
                    )
                    .map_err(|error| format!("无法写入素材 manifest: {error}"))?;
                    if format == "full_project" {
                        let safe = sanitized_project_package(&project);
                        fs::write(
                            staging.join("project.json"),
                            serde_json::to_vec_pretty(&safe).map_err(|error| error.to_string())?,
                        )
                        .map_err(|error| format!("无法写入项目包: {error}"))?;
                        fs::write(
                            staging.join("COURSE.md"),
                            markdown_for_project(&project, content_item_id),
                        )
                        .map_err(|error| format!("无法写入项目课程正文: {error}"))?;
                    }
                }
                Ok(())
            })();
            if let Err(error) = build {
                let _ = fs::remove_dir_all(&staging);
                return Err(error);
            }
            fs::rename(&staging, &output_path).map_err(|error| {
                let _ = fs::remove_dir_all(&staging);
                format!("无法提交导出目录: {error}")
            })?;
            for entry in
                fs::read_dir(&output_path).map_err(|error| format!("无法检查导出目录: {error}"))?
            {
                let entry = entry.map_err(|error| format!("无法检查导出文件: {error}"))?;
                exported_files.push(json!({
                    "relative_path": entry.file_name().to_string_lossy(),
                    "path": entry.path(),
                }));
            }
        }
        _ => return Err("不支持的导出格式".into()),
    }
    Ok(json!({
        "status": "completed",
        "format": format,
        "scope": if content_item_id.is_some() { "lesson" } else { "course" },
        "output_path": output_path,
        "target_path": output_path,
        "bytes": total_bytes,
        "files": exported_files,
        "preflight": report,
    }))
}

#[tauri::command]
fn reveal_export_path(path: String) -> Result<Value, String> {
    let path = PathBuf::from(path.trim());
    if !path.is_absolute() || !path.exists() {
        return Err("导出结果不存在，无法在 Finder 中定位。".into());
    }
    reject_symlink(&path, "导出结果")?;
    let mut command = ProcessCommand::new("/usr/bin/open");
    if path.is_file() {
        command.arg("-R");
    }
    let status = command
        .arg(&path)
        .status()
        .map_err(|error| format!("无法打开 Finder: {error}"))?;
    if !status.success() {
        return Err("Finder 未能打开导出结果。".into());
    }
    Ok(json!({ "status": "opened", "path": path }))
}

#[tauri::command]
fn publication_record(input: Value) -> Result<Value, String> {
    let object = require_object(&input, "publication_record")?;
    let project_dir = required_string(object, &["project_dir", "projectDir"], "项目目录")?;
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let _lease_guard = require_active_project_lock(&project_dir)?;
    let mutation_binding = parse_canonical_mutation_binding(object)?;
    let active_generation = verify_lease_generation(
        &project_dir,
        mutation_binding
            .as_ref()
            .map(|binding| binding.lease_generation.as_str()),
    )?;
    let (mut project, current_fingerprint) = read_project_state(&project_dir)?;
    validate_canonical_mutation_binding(
        mutation_binding.as_ref(),
        &project,
        &current_fingerprint,
        &active_generation,
    )?;
    let publication = object.get("publication").cloned().unwrap_or_else(|| {
        let mut copy = object.clone();
        copy.remove("project_dir");
        copy.remove("projectDir");
        Value::Object(copy)
    });
    let publication = publication.as_object().ok_or("发布记录必须是结构化对象")?;
    if let Some(url) = publication.get("external_url").and_then(Value::as_str) {
        let lower = url.to_ascii_lowercase();
        if !(lower.starts_with("https://") || lower.starts_with("http://")) {
            return Err("发布链接必须使用 http 或 https".into());
        }
    }
    if let Some(path) = publication.get("export_path").and_then(Value::as_str) {
        if Path::new(path).is_absolute() || path.contains("..") {
            return Err("发布记录不能保存本机绝对路径".into());
        }
    }
    let mut record = Value::Object(publication.clone());
    let record_object = record.as_object_mut().ok_or("发布记录格式无效")?;
    record_object
        .entry("id")
        .or_insert_with(|| json!(native_id("publication")));
    record_object
        .entry("status")
        .or_insert_with(|| json!("published"));
    let list = project
        .as_object_mut()
        .ok_or("项目数据必须是 JSON 对象")?
        .entry("publications")
        .or_insert_with(|| Value::Array(Vec::new()));
    list.as_array_mut()
        .ok_or("项目的发布记录格式无效")?
        .push(record.clone());
    let report = write_canonical_mutation_report_unlocked(
        &project_dir,
        &project,
        &current_fingerprint,
        mutation_binding.as_ref(),
    )?;
    let mut result = json!({ "status": "recorded", "publication": record });
    attach_canonical_mutation_ack(
        &mut result,
        mutation_binding.as_ref(),
        &project,
        &report.fingerprint,
        &project_dir,
        &active_generation,
        "written",
        report.durability_warning.as_deref(),
        report.recovery_warning.as_deref(),
    );
    Ok(result)
}

#[tauri::command]
fn session_target_guard(target: &Path) -> Result<File, String> {
    let parent = target.parent().ok_or("会话文件没有父目录")?;
    ensure_directory(parent, "工作台本地目录")?;
    let file_name = target
        .file_name()
        .ok_or("会话文件名无效")?
        .to_string_lossy();
    let guard_path = parent.join(format!(".{file_name}.guard"));
    reject_symlink(&guard_path, "会话协调器")?;
    let guard = OpenOptions::new()
        .read(true)
        .write(true)
        .create(true)
        .open(guard_path)
        .map_err(|error| format!("无法打开会话协调器: {error}"))?;
    guard
        .lock()
        .map_err(|error| format!("无法锁定会话协调器: {error}"))?;
    Ok(guard)
}

const SESSION_SAVE_SIZE_LIMIT: usize = 64 * 1024;

fn validate_session_record(
    value: &Value,
    expected_id: Option<&str>,
    allow_slots: bool,
) -> Result<(), String> {
    let object = require_object(value, "save_session")?;
    for (key, child) in object {
        match key.as_str() {
            "project_id" => {
                if !child.is_null() && !child.as_str().is_some_and(|id| !id.trim().is_empty()) {
                    return Err("项目会话标识无效".into());
                }
            }
            "project_dir" => {
                if !child.is_null()
                    && !child
                        .as_str()
                        .is_some_and(|directory| !directory.trim().is_empty())
                {
                    return Err("项目会话目录无效".into());
                }
            }
            "project_sessions" if allow_slots => {
                let slots = child.as_object().ok_or("项目会话记录格式无效")?;
                if slots.len() > 512 {
                    return Err("项目会话记录数量超出限制".into());
                }
                for (id, record) in slots {
                    if id.trim().is_empty() {
                        return Err("项目会话标识无效".into());
                    }
                    validate_session_record(record, Some(id), false)?;
                }
            }
            "project_sessions" => return Err("项目会话记录不能嵌套".into()),
            "active_content_item_id" | "selected_block_id" | "layout_page_id" => {
                if !child.is_null() && !child.is_string() {
                    return Err(format!("会话字段 {key} 格式无效"));
                }
            }
            "left_collapsed" | "right_collapsed" => {
                if !child.is_boolean() {
                    return Err(format!("会话字段 {key} 格式无效"));
                }
            }
            "layout_zoom" => {
                if !matches!(child.as_str(), Some("fit" | "actual")) {
                    return Err("会话字段 layout_zoom 格式无效".into());
                }
            }
            "explorer_filter" => {
                if !child.as_str().is_some_and(|value| value.len() <= 256) {
                    return Err("会话字段 explorer_filter 格式无效".into());
                }
            }
            "collapsed_stage_ids" | "explorer_expanded" | "explorer_recent" => {
                let items = child
                    .as_array()
                    .ok_or_else(|| format!("会话字段 {key} 格式无效"))?;
                let limit = match key.as_str() {
                    "collapsed_stage_ids" => 1024,
                    "explorer_recent" => 8,
                    _ => 64,
                };
                if items.len() > limit
                    || items.iter().any(|item| {
                        !item
                            .as_str()
                            .is_some_and(|value| !value.trim().is_empty() && value.len() <= 1024)
                    })
                {
                    return Err(format!("会话字段 {key} 超出限制"));
                }
            }
            "tabs" => {
                let tabs = child.as_array().ok_or("会话字段 tabs 格式无效")?;
                if tabs.len() > 100 {
                    return Err("会话标签数量超出限制".into());
                }
                for tab in tabs {
                    let tab = require_object(tab, "session.tab")?;
                    if tab.keys().any(|key| {
                        !matches!(
                            key.as_str(),
                            "content_item_id" | "mode" | "pinned" | "scroll_top"
                        )
                    }) || !tab.get("content_item_id").is_some_and(Value::is_string)
                        || !tab.get("mode").is_some_and(Value::is_string)
                        || !tab.get("pinned").is_some_and(Value::is_boolean)
                        || !tab
                            .get("scroll_top")
                            .and_then(Value::as_f64)
                            .is_some_and(f64::is_finite)
                    {
                        return Err("会话标签记录格式无效".into());
                    }
                }
            }
            "mode" | "right_panel" | "route" | "ai_scope" | "ai_provider_id" | "ai_model" => {
                if !child.is_string() {
                    return Err(format!("会话字段 {key} 格式无效"));
                }
            }
            _ => return Err(format!("会话包含不允许的字段: {key}")),
        }
    }

    let project_id = object
        .get("project_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|id| !id.is_empty());
    let project_dir = object
        .get("project_dir")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|directory| !directory.is_empty());
    if project_id.is_some() != project_dir.is_some()
        || expected_id.is_some_and(|expected| project_id != Some(expected) || project_dir.is_none())
    {
        return Err("项目会话的目录与标识不一致".into());
    }
    Ok(())
}

fn valid_session_record(id: &str, value: &Value) -> bool {
    validate_session_record(value, Some(id), false).is_ok()
}

fn merge_native_session(existing: Option<Value>, session: Value) -> Result<Value, String> {
    validate_session_record(&session, None, true)?;
    let incoming = require_object(&session, "save_session")?;
    let mut slots = Map::new();
    let mut existing_top_level = None;
    if let Some(previous) = existing.as_ref().filter(|value| value.is_object()) {
        if let Some(previous_slots) = previous.get("project_sessions").and_then(Value::as_object) {
            for (id, record) in previous_slots {
                if valid_session_record(id, record) {
                    slots.insert(id.clone(), record.clone());
                }
            }
        }
        if let Some(id) = previous.get("project_id").and_then(Value::as_str) {
            let mut previous_record = previous.clone();
            previous_record
                .as_object_mut()
                .unwrap()
                .remove("project_sessions");
            if valid_session_record(id, &previous_record) {
                existing_top_level = Some((id.to_owned(), previous_record));
            }
        }
    }
    if let Some((id, record)) = existing_top_level {
        slots.entry(id).or_insert(record);
    }
    if let Some(incoming_slots) = incoming.get("project_sessions").and_then(Value::as_object) {
        for (id, record) in incoming_slots {
            if valid_session_record(id, record) {
                // The file is the shared source of truth. A process may have
                // an older in-memory copy of another project's reader slot.
                slots.entry(id.clone()).or_insert_with(|| record.clone());
            }
        }
    }

    let active_id = incoming
        .get("project_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|id| !id.is_empty());
    let active_dir = incoming
        .get("project_dir")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|directory| !directory.is_empty());
    if active_id.is_some() != active_dir.is_some() {
        return Err("项目会话的目录与标识不一致".into());
    }
    if let Some(id) = active_id {
        let mut active_record = session.clone();
        active_record
            .as_object_mut()
            .ok_or("save_session: 参数必须是 JSON 对象")?
            .remove("project_sessions");
        if valid_session_record(id, &active_record) {
            slots.insert(id.to_owned(), active_record);
        } else {
            return Err("项目会话记录与项目标识不一致".into());
        }
    }

    let mut merged = session;
    let object = merged
        .as_object_mut()
        .ok_or("save_session: 参数必须是 JSON 对象")?;
    object.remove("project_sessions");
    if !slots.is_empty() {
        object.insert("project_sessions".into(), Value::Object(slots));
    }
    Ok(merged)
}

fn save_session_target(
    target: &Path,
    session: Value,
    operation_id: Option<&str>,
    session_generation: Option<u64>,
    revision: Option<u64>,
) -> Result<Value, String> {
    reject_sensitive(&session)?;
    validate_session_record(&session, None, true)?;
    let has_metadata = operation_id.is_some() || session_generation.is_some() || revision.is_some();
    if has_metadata
        && (operation_id
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .is_none()
            || session_generation.is_none()
            || revision.is_none())
    {
        return Err("会话操作元数据不完整".into());
    }
    let _target_guard = session_target_guard(target)?;
    let existing = if target.exists() {
        Some(read_json_file(target)?)
    } else {
        None
    };
    #[cfg(test)]
    if let Ok(delay) = std::env::var("WORKBENCH_SESSION_LOCK_TEST_DELAY_MS") {
        if let Ok(delay) = delay.parse::<u64>() {
            thread::sleep(Duration::from_millis(delay));
        }
    }
    let merged = merge_native_session(existing.clone(), session)?;
    if serde_json::to_vec(&merged)
        .map_err(|error| error.to_string())?
        .len()
        > SESSION_SAVE_SIZE_LIMIT
    {
        return Err("会话数据超出 64 KiB 限制".into());
    }
    let unchanged = existing.as_ref() == Some(&merged);
    let durability_warning = if !unchanged {
        let contents = serde_json::to_string(&merged).map_err(|error| error.to_string())?;
        atomic_write_path_report(target, &contents, true).map_err(|failure| failure.message)?
    } else {
        None
    };
    let project_id = merged
        .get("project_id")
        .and_then(Value::as_str)
        .map(ToOwned::to_owned);
    let mut result = json!({
        "outcome": if unchanged { "unchanged" } else { "written" },
        "project_id": project_id,
    });
    if let Some(operation_id) = operation_id {
        result["operation_id"] = json!(operation_id);
    }
    if let Some(session_generation) = session_generation {
        result["session_generation"] = json!(session_generation);
    }
    if let Some(revision) = revision {
        result["revision"] = json!(revision);
    }
    if let Some(warning) = durability_warning {
        result["durability_warning"] = json!(warning);
    }
    Ok(result)
}

#[tauri::command]
fn save_session(
    app: AppHandle,
    session: Value,
    operation_id: Option<String>,
    session_generation: Option<u64>,
    revision: Option<u64>,
) -> Result<Value, String> {
    reject_sensitive(&session)?;
    let object = require_object(&session, "save_session")?;
    let project_dir = field(object, &["project_dir", "projectDir"])
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned);
    let path = app_local_path(&app, ".workspace/session.json")?;
    if let Some(project_dir) = project_dir {
        let project_dir = explicit_project_dir(&project_dir, false)?;
        // Lock order: project lease guard, then the shared session target.
        let _lease_guard = require_active_project_lock(&project_dir)?;
        let mut session = session;
        let object = session
            .as_object_mut()
            .ok_or("save_session: 参数必须是 JSON 对象")?;
        object.remove("projectDir");
        object.insert("project_dir".into(), json!(project_dir.to_string_lossy()));
        return save_session_target(
            &path,
            session,
            operation_id.as_deref(),
            session_generation,
            revision,
        );
    }
    save_session_target(
        &path,
        session,
        operation_id.as_deref(),
        session_generation,
        revision,
    )
}

#[tauri::command]
fn load_session(app: AppHandle) -> Result<Option<Value>, String> {
    // A directory passed on the command line wins for the first read, so
    // `workbench --project-dir <path>` opens that project immediately.
    if let Some(Some(directory)) = LAUNCH_PROJECT_DIR.get() {
        if !LAUNCH_PROJECT_CONSUMED.swap(true, Ordering::AcqRel) {
            return Ok(Some(json!({
                "project_dir": directory.to_string_lossy(),
            })));
        }
    }
    let path = app_local_path(&app, ".workspace/session.json")?;
    let _target_guard = session_target_guard(&path)?;
    if !path.exists() {
        return Ok(None);
    }
    Ok(Some(read_json_file(&path)?))
}

#[tauri::command]
fn write_recovery_journal(project_dir: String, contents: String) -> Result<(), String> {
    let project_dir = explicit_project_dir(&project_dir, true)?;
    let _lease_guard = require_active_project_lock(&project_dir)?;
    write_recovery_journal_unlocked(&project_dir, &contents)
}

fn write_recovery_journal_unlocked(project_dir: &Path, contents: &str) -> Result<(), String> {
    let value: Value = serde_json::from_str(&contents).map_err(|error| error.to_string())?;
    reject_sensitive(&value)?;
    let path = project_file(project_dir, ".workspace/recovery.json")?;
    match atomic_write_path_report(&path, contents, true).map_err(|failure| failure.message)? {
        Some(warning) => Err(format!("恢复日志已写入，但目录同步失败：{warning}")),
        None => Ok(()),
    }
}

#[tauri::command]
fn read_recovery_journal(project_dir: String) -> Result<Option<Value>, String> {
    let project_dir = explicit_project_dir(&project_dir, false)?;
    read_recovery_journal_with_canonical_context(&project_dir, None)
}

fn read_recovery_journal_with_canonical_context(
    project_dir: &Path,
    canonical_context: Option<&Value>,
) -> Result<Option<Value>, String> {
    let path = project_file(&project_dir, ".workspace/recovery.json")?;
    if !path.exists() {
        return Ok(None);
    }
    let journal = read_json_file(&path)?;
    // A crash or cleanup error can leave a recovery journal whose exact
    // snapshot is already canonical. Hide only that confirmed committed copy
    // from recovery UI; keep the file intact for normal later cleanup.
    let canonical_from_disk;
    let canonical = if let Some(canonical) = canonical_context {
        Some(canonical)
    } else {
        canonical_from_disk = read_project_state(project_dir)
            .ok()
            .map(|(project, _)| project);
        canonical_from_disk.as_ref()
    };
    if let Some(canonical) = canonical {
        let same_project_id = journal
            .get("project_id")
            .and_then(Value::as_str)
            .is_some_and(|journal_id| {
                project_id_of(&canonical).ok().as_deref() == Some(journal_id)
            });
        let canonical_revision = canonical
            .get("project")
            .and_then(|value| value.get("updated_at"))
            .and_then(Value::as_str);
        let same_revision = canonical_revision.is_some_and(|revision| {
            journal.get("canonical_revision").and_then(Value::as_str) == Some(revision)
        });
        if same_project_id && same_revision && journal.get("project") == Some(canonical) {
            return Ok(None);
        }
    }
    Ok(Some(journal))
}

/// Read-only asset access for previews.
///
/// The webview never receives filesystem access: the command resolves an asset
/// id against the open project's canonical metadata, refuses symlinked or
/// out-of-project storage paths, and returns at most `ASSET_READ_SIZE_LIMIT`
/// bytes.  It does not take an edit lease because it writes nothing.
const ASSET_READ_SIZE_LIMIT: u64 = 8 * 1024 * 1024;
const ASSET_PREVIEW_BATCH_ITEM_LIMIT: usize = 8;
const ASSET_PREVIEW_BATCH_RAW_LIMIT: u64 = 16 * 1024 * 1024;

struct AssetPreviewProblem {
    code: &'static str,
    message: String,
}

struct AssetPreviewFile {
    path: PathBuf,
    filename: String,
    mime_type: String,
    size: u64,
}

fn asset_preview_problem(code: &'static str, message: impl Into<String>) -> AssetPreviewProblem {
    AssetPreviewProblem {
        code,
        message: message.into(),
    }
}

fn resolve_asset_preview_file(
    project_dir: &Path,
    project: &Value,
    asset_id: &str,
) -> Result<AssetPreviewFile, AssetPreviewProblem> {
    let project_object = project
        .as_object()
        .ok_or_else(|| asset_preview_problem("project_invalid", "项目数据必须是 JSON 对象"))?;
    let asset = project_object
        .get("assets")
        .and_then(Value::as_array)
        .and_then(|assets| {
            assets
                .iter()
                .find(|asset| asset.get("id").and_then(Value::as_str) == Some(asset_id))
        })
        .ok_or_else(|| asset_preview_problem("asset_not_found", "找不到素材"))?;
    if asset
        .get("archived")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return Err(asset_preview_problem(
            "asset_archived",
            "素材已归档，无法读取",
        ));
    }
    let storage_path = asset
        .get("storage_path")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| asset_preview_problem("unsafe_asset_path", "素材缺少存储路径"))?;
    let relative = Path::new(storage_path);
    let inside_assets = relative
        .components()
        .next()
        .map(|component| matches!(component, Component::Normal(name) if name == "assets"))
        .unwrap_or(false);
    if !inside_assets {
        return Err(asset_preview_problem(
            "unsafe_asset_path",
            "素材路径必须位于 assets/ 目录内",
        ));
    }
    let target = project_file(project_dir, storage_path)
        .map_err(|error| asset_preview_problem("unsafe_asset_path", error))?;
    reject_symlink(&target, "素材文件")
        .map_err(|error| asset_preview_problem("unsafe_asset_path", error))?;
    let real_root = fs::canonicalize(project_dir).map_err(|error| {
        asset_preview_problem("project_read_failed", format!("无法解析项目目录: {error}"))
    })?;
    let real_target = fs::canonicalize(&target).map_err(|error| {
        asset_preview_problem("asset_read_failed", format!("无法读取素材: {error}"))
    })?;
    if !real_target.starts_with(&real_root) {
        return Err(asset_preview_problem(
            "unsafe_asset_path",
            "素材路径超出项目目录",
        ));
    }
    let metadata = fs::metadata(&real_target).map_err(|error| {
        asset_preview_problem("asset_read_failed", format!("无法读取素材: {error}"))
    })?;
    if !metadata.is_file() {
        return Err(asset_preview_problem(
            "unsafe_asset_path",
            "素材路径不是文件",
        ));
    }
    Ok(AssetPreviewFile {
        path: real_target,
        filename: asset
            .get("filename")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_owned(),
        mime_type: asset
            .get("mime_type")
            .and_then(Value::as_str)
            .unwrap_or("application/octet-stream")
            .to_owned(),
        size: metadata.len(),
    })
}

fn read_asset_preview_file(path: &Path, limit: u64) -> Result<Vec<u8>, String> {
    let file = File::open(path).map_err(|error| format!("无法读取素材字节: {error}"))?;
    let mut bytes = Vec::new();
    file.take(limit.saturating_add(1))
        .read_to_end(&mut bytes)
        .map_err(|error| format!("无法读取素材字节: {error}"))?;
    Ok(bytes)
}

fn preview_batch_error(code: &str, message: &str) -> String {
    json!({ "error": { "code": code, "message": message } }).to_string()
}

#[tauri::command]
fn asset_read(input: Value) -> Result<Value, String> {
    let outer = require_object(&input, "asset_read")?;
    let payload = outer
        .get("input")
        .filter(|value| value.is_object())
        .cloned()
        .unwrap_or(input);
    let object = require_object(&payload, "asset_read")?;
    let project_dir = required_string(object, &["project_dir", "projectDir"], "项目目录")?;
    let asset_id = required_string(object, &["asset_id", "assetId"], "素材 ID")?;
    let project_dir = explicit_project_dir(&project_dir, false)?;
    // This is a preview read only: it resolves one named asset inside the
    // project and writes nothing, so it deliberately takes no edit lease and
    // does not participate in the save-conflict protocol.
    let project = read_project_value(&project_dir)?;
    let file = resolve_asset_preview_file(&project_dir, &project, &asset_id)
        .map_err(|problem| problem.message)?;
    if file.size > ASSET_READ_SIZE_LIMIT {
        return Err(format!(
            "素材过大，无法在工作台内预览（单文件上限 {} MiB）",
            ASSET_READ_SIZE_LIMIT / (1024 * 1024)
        ));
    }
    let bytes = read_asset_preview_file(&file.path, ASSET_READ_SIZE_LIMIT)?;
    if bytes.len() as u64 > ASSET_READ_SIZE_LIMIT {
        return Err(format!(
            "素材过大，无法在工作台内预览（单文件上限 {} MiB）",
            ASSET_READ_SIZE_LIMIT / (1024 * 1024)
        ));
    }
    Ok(json!({
        "asset_id": asset_id,
        "filename": file.filename,
        "mime_type": file.mime_type,
        "file_size": bytes.len(),
        "bytes_base64": BASE64.encode(&bytes),
    }))
}

#[tauri::command]
fn asset_preview_batch(input: Value) -> Result<Value, String> {
    let diagnostics_enabled = std::env::var("WORKBENCH_IO_DIAGNOSTICS")
        .map(|value| value == "1")
        .unwrap_or(false);
    asset_preview_batch_with_diagnostics(input, diagnostics_enabled)
}

fn asset_preview_batch_with_diagnostics(
    input: Value,
    diagnostics_enabled: bool,
) -> Result<Value, String> {
    let outer = require_object(&input, "asset_preview_batch")?;
    let payload = outer
        .get("input")
        .filter(|value| value.is_object())
        .cloned()
        .unwrap_or(input);
    let object = require_object(&payload, "asset_preview_batch")?;
    let project_dir = required_string(object, &["project_dir", "projectDir"], "项目目录")?;
    let expected_project_id = required_string(object, &["project_id", "projectId"], "项目 ID")?;
    let generation = field(object, &["request_generation", "requestGeneration"])
        .and_then(Value::as_u64)
        .ok_or_else(|| {
            preview_batch_error(
                "invalid_preview_request",
                "request_generation 必须是非负整数",
            )
        })?;
    let requested_fingerprint: FileFingerprint = serde_json::from_value(
        field(object, &["fingerprint"])
            .cloned()
            .ok_or_else(|| preview_batch_error("invalid_preview_request", "缺少 fingerprint"))?,
    )
    .map_err(|error| {
        preview_batch_error(
            "invalid_preview_request",
            &format!("fingerprint 无效: {error}"),
        )
    })?;
    let requested_ids = field(object, &["asset_ids", "assetIds"])
        .and_then(Value::as_array)
        .ok_or_else(|| preview_batch_error("invalid_preview_request", "asset_ids 必须是数组"))?;
    if requested_ids.len() > ASSET_PREVIEW_BATCH_ITEM_LIMIT {
        return Err(preview_batch_error(
            "preview_batch_limit",
            "单批最多预览 8 个素材",
        ));
    }
    let mut asset_ids = Vec::with_capacity(requested_ids.len());
    for value in requested_ids {
        let asset_id = value
            .as_str()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| {
                preview_batch_error("invalid_preview_request", "asset_ids 包含无效素材 ID")
            })?;
        asset_ids.push(asset_id.to_owned());
    }

    let project_dir = explicit_project_dir(&project_dir, false)?;
    let (project, fingerprint) = read_project_state(&project_dir)?;
    let project_id =
        project_id_of(&project).map_err(|error| preview_batch_error("project_identity", &error))?;
    if project_id != expected_project_id {
        return Err(preview_batch_error(
            "project_id_mismatch",
            "素材预览请求所属项目已改变",
        ));
    }
    if fingerprints_differ(&fingerprint, &requested_fingerprint) {
        return Err(preview_batch_error(
            "fingerprint_mismatch",
            "项目文件已变化，请重新请求素材预览",
        ));
    }

    let mut raw_bytes_returned = 0_u64;
    let mut asset_file_bytes_read = 0_u64;
    let mut base64_bytes_emitted = 0_u64;
    let mut asset_file_opens = 0_u64;
    let mut items = Vec::with_capacity(asset_ids.len());
    for asset_id in asset_ids {
        let file = match resolve_asset_preview_file(&project_dir, &project, &asset_id) {
            Ok(file) => file,
            Err(problem) => {
                items.push(json!({
                    "asset_id": asset_id,
                    "status": "error",
                    "error": { "code": problem.code, "message": problem.message }
                }));
                continue;
            }
        };
        if file.size > ASSET_READ_SIZE_LIMIT {
            items.push(json!({
                "asset_id": asset_id,
                "status": "error",
                "error": {
                    "code": "asset_too_large",
                    "message": format!("素材超过 {} MiB 单文件预览上限", ASSET_READ_SIZE_LIMIT / (1024 * 1024))
                }
            }));
            continue;
        }
        let remaining = ASSET_PREVIEW_BATCH_RAW_LIMIT.saturating_sub(raw_bytes_returned);
        if file.size > remaining {
            items.push(json!({ "asset_id": asset_id, "status": "deferred" }));
            continue;
        }
        let read_limit = ASSET_READ_SIZE_LIMIT.min(remaining);
        asset_file_opens = asset_file_opens.saturating_add(1);
        let bytes = match read_asset_preview_file(&file.path, read_limit) {
            Ok(bytes) => bytes,
            Err(message) => {
                items.push(json!({
                    "asset_id": asset_id,
                    "status": "error",
                    "error": { "code": "asset_read_failed", "message": message }
                }));
                continue;
            }
        };
        asset_file_bytes_read = asset_file_bytes_read.saturating_add(bytes.len() as u64);
        if bytes.len() as u64 > ASSET_READ_SIZE_LIMIT {
            items.push(json!({
                "asset_id": asset_id,
                "status": "error",
                "error": {
                    "code": "asset_too_large",
                    "message": format!("素材超过 {} MiB 单文件预览上限", ASSET_READ_SIZE_LIMIT / (1024 * 1024))
                }
            }));
            continue;
        }
        if bytes.len() as u64 > remaining {
            items.push(json!({ "asset_id": asset_id, "status": "deferred" }));
            continue;
        }
        raw_bytes_returned = raw_bytes_returned.saturating_add(bytes.len() as u64);
        let encoded = BASE64.encode(&bytes);
        base64_bytes_emitted = base64_bytes_emitted.saturating_add(encoded.len() as u64);
        items.push(json!({
            "asset_id": asset_id,
            "status": "ok",
            "bytes_base64": encoded
        }));
    }

    let mut result = json!({
        "project_id": project_id,
        "fingerprint": fingerprint,
        "request_generation": generation,
        "items": items,
    });
    if diagnostics_enabled {
        result["diagnostics"] = json!({
            "manifest_reads": 1,
            "manifest_hash_bytes": fingerprint.size.unwrap_or_default(),
            "asset_file_opens": asset_file_opens,
            "asset_file_bytes_read": asset_file_bytes_read,
            "raw_bytes_returned": raw_bytes_returned,
            "base64_bytes_emitted": base64_bytes_emitted,
            "max_open_asset_handles": u8::from(asset_file_opens > 0),
        });
    }
    Ok(result)
}

/// Grant the asset protocol access to one validated video file for ranged
/// playback. Tauri's allow_file scope lasts for this app process; exact-file
/// grants keep the capability narrow. Add revocable opaque tokens if
/// per-project grant revocation becomes a requirement.
#[tauri::command]
fn asset_preview_source(app: AppHandle, input: Value) -> Result<String, String> {
    let outer = require_object(&input, "asset_preview_source")?;
    let payload = outer
        .get("input")
        .filter(|value| value.is_object())
        .cloned()
        .unwrap_or(input);
    let object = require_object(&payload, "asset_preview_source")?;
    let project_dir = required_string(object, &["project_dir", "projectDir"], "项目目录")?;
    let asset_id = required_string(object, &["asset_id", "assetId"], "素材 ID")?;
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let _project_guard = require_active_project_lock(&project_dir)?;
    let project = read_project_value(&project_dir)?;
    let asset = project
        .get("assets")
        .and_then(Value::as_array)
        .and_then(|assets| {
            assets
                .iter()
                .find(|asset| asset.get("id").and_then(Value::as_str) == Some(asset_id.as_str()))
        })
        .ok_or("找不到素材")?;
    if asset.get("archived").and_then(Value::as_bool) == Some(true) {
        return Err("素材已归档，无法预览".into());
    }
    if asset.get("type").and_then(Value::as_str) != Some("video")
        || !asset
            .get("mime_type")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .starts_with("video/")
    {
        return Err("该素材不是受支持的视频文件".into());
    }
    let path = canonical_export_asset_path(&project, &project_dir, &asset_id)?;
    app.asset_protocol_scope()
        .allow_file(&path)
        .map_err(|error| format!("无法授权视频预览：{error}"))?;
    Ok(path.to_string_lossy().into_owned())
}

/// The folder scanner has already shown this source to the user. Resolve its
/// relative path again at the trust boundary and grant only the exact video.
#[tauri::command]
fn folder_preview_source(
    app: AppHandle,
    root: String,
    relative_path: String,
) -> Result<String, String> {
    let root_path = PathBuf::from(root.trim());
    if !root_path.is_absolute() {
        return Err("导入文件夹必须是用户明确选择的绝对路径".into());
    }
    reject_symlink(&root_path, "导入文件夹")?;
    let root_meta =
        fs::symlink_metadata(&root_path).map_err(|error| format!("无法打开所选文件夹：{error}"))?;
    if root_meta.file_type().is_symlink() || !root_meta.is_dir() {
        return Err("视频预览需要已选择的文件夹根目录".into());
    }
    let resolved_root =
        fs::canonicalize(&root_path).map_err(|error| format!("无法解析所选文件夹：{error}"))?;
    reject_symlink(&resolved_root, "导入文件夹")?;
    let rel = relative_path.trim().replace('\\', "/");
    if rel.is_empty()
        || rel.starts_with('/')
        || rel.contains('\0')
        || rel
            .split('/')
            .any(|part| part.is_empty() || part == "." || part == "..")
    {
        return Err("预览路径无效".into());
    }
    let mut target = resolved_root.clone();
    for part in rel.split('/') {
        target.push(part);
        reject_symlink(&target, "视频来源")?;
    }
    let _ = scan_relative(&resolved_root, &target)?;
    let metadata = fs::metadata(&target).map_err(|error| format!("无法读取视频来源：{error}"))?;
    if !metadata.is_file() {
        return Err("视频来源不是文件".into());
    }
    let name = target
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("");
    let mime = mime_for_filename(name);
    if folder_preview_kind(name, Some(mime)) != "video" || !mime.starts_with("video/") {
        return Err("该文件不是受支持的视频格式".into());
    }
    let real_target =
        fs::canonicalize(&target).map_err(|error| format!("无法解析视频来源：{error}"))?;
    if !real_target.starts_with(&resolved_root) {
        return Err("视频来源超出所选文件夹".into());
    }
    if !SCANNED_FOLDER_VIDEOS
        .get_or_init(|| Mutex::new(HashSet::new()))
        .lock()
        .unwrap()
        .contains(&(resolved_root.clone(), rel.clone()))
    {
        return Err("请先从已扫描的文件夹中选择视频".into());
    }
    // ponytail: exact file grants live for this process; opaque revocable
    // grants only become necessary if per-project revocation is required.
    app.asset_protocol_scope()
        .allow_file(&real_target)
        .map_err(|error| format!("无法授权视频预览：{error}"))?;
    Ok(real_target.to_string_lossy().into_owned())
}

fn safe_asset_filename(value: &str) -> String {
    let name = Path::new(value)
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("unnamed");
    let sanitized: String = name
        .chars()
        .map(|character| {
            if character.is_control() || matches!(character, '/' | '\\') {
                '_'
            } else {
                character
            }
        })
        .collect();
    let sanitized = sanitized.trim();
    if sanitized.is_empty() {
        "unnamed".into()
    } else {
        sanitized.to_owned()
    }
}

fn mime_for_filename(filename: &str) -> &'static str {
    match Path::new(filename)
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase()
        .as_str()
    {
        "md" | "markdown" => "text/markdown",
        "txt" | "text" => "text/plain",
        "tex" | "latex" => "text/x-tex",
        "epub" => "application/epub+zip",
        "json" => "application/json",
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "webp" => "image/webp",
        "svg" => "image/svg+xml",
        "avif" => "image/avif",
        "mp4" => "video/mp4",
        "mov" => "video/quicktime",
        "webm" => "video/webm",
        "m4v" => "video/mp4",
        "mp3" => "audio/mpeg",
        "wav" => "audio/wav",
        "m4a" => "audio/mp4",
        "ogg" => "audio/ogg",
        // Kept in lockstep with ASSET_EXTENSIONS / mimeFor in
        // src/service/folder_scan.ts: the two stacks must classify the same
        // file name identically, or a folder imported through Deno and reopened
        // in Rust would disagree with itself.
        "html" | "htm" => "text/html",
        "pdf" => "application/pdf",
        "docx" => "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "doc" => "application/msword",
        _ => "application/octet-stream",
    }
}

fn normalize_asset_type(raw: Option<&str>, filename: &str, mime_type: &str) -> String {
    let extension = Path::new(filename)
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    if extension == "gif" {
        return "gif".into();
    }
    if mime_type.starts_with("video/")
        || matches!(extension.as_str(), "mp4" | "mov" | "webm" | "m4v")
    {
        return "video".into();
    }
    if mime_type.starts_with("audio/")
        || matches!(extension.as_str(), "mp3" | "wav" | "m4a" | "ogg")
    {
        return "audio".into();
    }
    if mime_type.starts_with("image/")
        || matches!(
            extension.as_str(),
            "png" | "jpg" | "jpeg" | "webp" | "svg" | "avif"
        )
    {
        return "image".into();
    }
    if matches!(extension.as_str(), "md" | "markdown" | "txt" | "json") {
        return "document".into();
    }
    match raw.unwrap_or_default().to_ascii_lowercase().as_str() {
        "image" | "gif" | "video" | "audio" | "document" | "other" => {
            raw.unwrap_or("other").to_ascii_lowercase()
        }
        _ => "other".into(),
    }
}

fn normalize_source_type(raw: Option<&str>) -> &'static str {
    match raw.unwrap_or_default().to_ascii_lowercase().as_str() {
        "original" => "original",
        "generated" => "generated",
        "external" => "external",
        "unknown" => "unknown",
        _ => "imported",
    }
}

fn append_asset_usage(
    project: &mut Value,
    input: &Map<String, Value>,
    asset_id: &str,
) -> Result<Option<Value>, String> {
    let Some(content_item_id) = field(input, &["content_item_id", "contentItemId"])
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
    else {
        return Ok(None);
    };
    let block_id = field(input, &["block_id", "blockId"])
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned);
    let layout_instance_id = field(input, &["layout_instance_id", "layoutInstanceId"])
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned);
    let role = field(input, &["role"])
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("content")
        .to_owned();
    let project_object = project.as_object().ok_or("项目数据必须是 JSON 对象")?;
    let project_id = project_object
        .get("project")
        .and_then(|value| value.get("id"))
        .and_then(Value::as_str)
        .ok_or("项目缺少 project.id")?;
    let item = project_object
        .get("content_items")
        .and_then(Value::as_array)
        .and_then(|items| {
            items.iter().find(|item| {
                item.get("id").and_then(Value::as_str) == Some(content_item_id.as_str())
            })
        })
        .ok_or("素材引用指向不存在的内容")?;
    if item.get("project_id").and_then(Value::as_str) != Some(project_id) {
        return Err("素材引用内容不属于当前项目".into());
    }
    if let Some(block_id) = block_id.as_deref() {
        let block = project_object
            .get("blocks")
            .and_then(Value::as_array)
            .and_then(|blocks| {
                blocks
                    .iter()
                    .find(|block| block.get("id").and_then(Value::as_str) == Some(block_id))
            })
            .ok_or("素材引用指向不存在的正文区块")?;
        let document_id = block
            .get("document_id")
            .and_then(Value::as_str)
            .ok_or("素材引用正文区块缺少 document_id")?;
        let document = project_object
            .get("documents")
            .and_then(Value::as_array)
            .and_then(|documents| {
                documents.iter().find(|document| {
                    document.get("id").and_then(Value::as_str) == Some(document_id)
                })
            })
            .ok_or("素材引用正文区块缺少文档")?;
        if document.get("content_item_id").and_then(Value::as_str) != Some(content_item_id.as_str())
        {
            return Err("素材正文引用与内容不匹配".into());
        }
    }
    if let Some(layout_instance_id) = layout_instance_id.as_deref() {
        let layout = project_object
            .get("layout_instances")
            .and_then(Value::as_array)
            .and_then(|layouts| {
                layouts.iter().find(|layout| {
                    layout.get("id").and_then(Value::as_str) == Some(layout_instance_id)
                })
            })
            .ok_or("素材引用指向不存在的排版版本")?;
        if layout.get("content_item_id").and_then(Value::as_str) != Some(content_item_id.as_str()) {
            return Err("素材排版引用与内容不匹配".into());
        }
    }
    let usages = project
        .as_object_mut()
        .ok_or("项目数据必须是 JSON 对象")?
        .entry("asset_usages")
        .or_insert_with(|| Value::Array(Vec::new()))
        .as_array_mut()
        .ok_or("项目的 asset_usages 数据格式无效")?;
    if let Some(existing) = usages.iter().find(|usage| {
        usage.get("asset_id").and_then(Value::as_str) == Some(asset_id)
            && usage.get("content_item_id").and_then(Value::as_str)
                == Some(content_item_id.as_str())
            && usage.get("block_id").and_then(Value::as_str) == block_id.as_deref()
            && usage.get("layout_instance_id").and_then(Value::as_str)
                == layout_instance_id.as_deref()
            && usage.get("role").and_then(Value::as_str) == Some(role.as_str())
    }) {
        return Ok(Some(existing.clone()));
    }
    let usage = json!({
        "id": native_id("usage"),
        "asset_id": asset_id,
        "content_item_id": content_item_id,
        "block_id": block_id,
        "layout_instance_id": layout_instance_id,
        "role": role,
        "created_at": unix_millis().to_string(),
    });
    usages.push(usage.clone());
    Ok(Some(usage))
}

#[tauri::command]
fn clear_recovery_journal(project_dir: String) -> Result<Value, String> {
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let _lease_guard = require_active_project_lock(&project_dir)?;
    let cleared = clear_recovery_journal_path(&project_dir)?;
    Ok(json!({
        "status": if cleared { "cleared" } else { "missing" },
        "project_dir": project_dir,
    }))
}

#[tauri::command]
fn asset_import(input: Value) -> Result<Value, String> {
    let outer = require_object(&input, "asset_import")?;
    // Native callers historically wrapped asset input as { input: ... };
    // accept both shapes so the browser bridge and direct Tauri callers share
    // one adapter contract.
    let payload = outer
        .get("input")
        .filter(|value| value.is_object())
        .cloned()
        .unwrap_or(input);
    let object = require_object(&payload, "asset_import")?;
    let project_dir = required_string(object, &["project_dir", "projectDir"], "项目目录")?;
    let project_dir = explicit_project_dir(&project_dir, false)?;
    let _lease_guard = require_active_project_lock(&project_dir)?;
    let mutation_binding = parse_canonical_mutation_binding(object)?;
    let active_generation = verify_lease_generation(
        &project_dir,
        mutation_binding
            .as_ref()
            .map(|binding| binding.lease_generation.as_str()),
    )?;
    let (mut project, current_fingerprint) = read_project_state(&project_dir)?;
    validate_canonical_mutation_binding(
        mutation_binding.as_ref(),
        &project,
        &current_fingerprint,
        &active_generation,
    )?;
    let project_id = project
        .get("project")
        .and_then(|value| value.get("id"))
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or("项目缺少 project.id")?
        .to_owned();

    let filename_hint = field(object, &["filename", "name"])
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let source_path = field(object, &["source_path", "sourcePath", "path"])
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let bytes_base64 = field(object, &["bytes_base64", "bytesBase64"])
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if source_path.is_some() && bytes_base64.is_some() {
        return Err("素材导入不能同时提供 source_path 和 bytes_base64".into());
    }
    let (filename, bytes) = if let Some(raw) = source_path {
        let path = PathBuf::from(raw);
        if !path.is_absolute() {
            return Err("素材来源必须是用户明确选择的绝对路径".into());
        }
        reject_symlink(&path, "素材来源")?;
        let canonical =
            fs::canonicalize(&path).map_err(|error| format!("无法读取素材来源: {error}"))?;
        reject_symlink(&canonical, "素材来源")?;
        let metadata =
            fs::metadata(&canonical).map_err(|error| format!("无法读取素材来源信息: {error}"))?;
        if !metadata.is_file() {
            return Err("素材来源必须是文件".into());
        }
        let filename = filename_hint
            .map(ToOwned::to_owned)
            .or_else(|| {
                canonical
                    .file_name()
                    .and_then(|value| value.to_str())
                    .map(ToOwned::to_owned)
            })
            .unwrap_or_else(|| "unnamed".into());
        let bytes = fs::read(&canonical).map_err(|error| format!("无法读取素材字节: {error}"))?;
        (filename, bytes)
    } else if let Some(encoded) = bytes_base64 {
        let filename = filename_hint.unwrap_or("unnamed").to_owned();
        (filename, decode_base64(encoded)?)
    } else {
        return Err("asset_import requires source_path or bytes_base64".into());
    };

    let filename = safe_asset_filename(&filename);
    let mime_type = field(object, &["mime_type", "mimeType"])
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .unwrap_or_else(|| mime_for_filename(&filename).into());
    let asset_type = normalize_asset_type(
        field(object, &["type", "asset_type", "assetType"]).and_then(Value::as_str),
        &filename,
        &mime_type,
    );
    let checksum = sha256_hex(&bytes);
    let keep_duplicate = object
        .get("keep_duplicate")
        .or_else(|| object.get("keepDuplicate"))
        .and_then(Value::as_bool)
        .unwrap_or(false)
        || object
            .get("duplicate_policy")
            .or_else(|| object.get("duplicatePolicy"))
            .and_then(Value::as_str)
            .map(|value| value.eq_ignore_ascii_case("copy"))
            .unwrap_or(false);

    let project_object = project.as_object_mut().ok_or("项目数据必须是 JSON 对象")?;
    let assets = project_object
        .entry("assets")
        .or_insert_with(|| Value::Array(Vec::new()))
        .as_array_mut()
        .ok_or("项目的 assets 数据格式无效")?;
    let existing = assets
        .iter()
        .find(|asset| {
            asset.get("project_id").and_then(Value::as_str) == Some(project_id.as_str())
                && asset.get("checksum").and_then(Value::as_str) == Some(checksum.as_str())
                && !asset
                    .get("archived")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
        })
        .cloned();
    if existing.is_some() && !keep_duplicate {
        let asset = existing.ok_or("重复素材状态无效")?;
        let usage = append_asset_usage(
            &mut project,
            object,
            asset
                .get("id")
                .and_then(Value::as_str)
                .ok_or("素材缺少 id")?,
        )?;
        let report = if usage.is_some() {
            touch_project_updated_at(&mut project)?;
            Some(
                write_project_value_report_unlocked(
                    &project_dir,
                    &project,
                    Some(&current_fingerprint),
                )
                .map_err(|failure| {
                    project_save_atomic_error_contract(
                        &failure,
                        mutation_binding
                            .as_ref()
                            .map(|binding| binding.operation_id.as_str()),
                        mutation_binding.as_ref().map(|binding| binding.revision),
                        Some(&current_fingerprint),
                        None,
                    )
                })?,
            )
        } else {
            None
        };
        let committed_fingerprint = report
            .as_ref()
            .map(|report| report.fingerprint.clone())
            .unwrap_or_else(|| current_fingerprint.clone());
        let outcome = if report.is_some() {
            "written"
        } else {
            "unchanged"
        };
        let durability_warning = report
            .as_ref()
            .and_then(|report| report.durability_warning.as_deref());
        let recovery_warning = report
            .as_ref()
            .and_then(|report| report.recovery_warning.as_deref());
        let warning = match (durability_warning, recovery_warning) {
            (Some(left), Some(right)) => Some(format!("{left}；{right}")),
            (Some(value), None) | (None, Some(value)) => Some(value.to_owned()),
            (None, None) => None,
        };
        let mut result = json!({
            "status": "existing",
            "duplicate": true,
            "asset": asset,
            "usage": usage,
            "checksum": checksum,
            "warning": warning,
        });
        attach_canonical_mutation_ack(
            &mut result,
            mutation_binding.as_ref(),
            &project,
            &committed_fingerprint,
            &project_dir,
            &active_generation,
            outcome,
            durability_warning,
            recovery_warning,
        );
        return Ok(result);
    }

    let asset_id = native_id("asset");
    let relative_path = format!("assets/{asset_id}-{filename}");
    let destination = project_file(&project_dir, &relative_path)?;
    let asset = json!({
        "id": asset_id,
        "project_id": project_id,
        "type": asset_type,
        "filename": filename,
        "storage_path": relative_path,
        "mime_type": mime_type,
        "width": null,
        "height": null,
        "duration_ms": null,
        "file_size": bytes.len(),
        "checksum": checksum,
        "title": field(object, &["title"]).and_then(Value::as_str).unwrap_or_else(|| filename.as_str()),
        "description": field(object, &["description"]).and_then(Value::as_str).unwrap_or(""),
        "source_type": normalize_source_type(field(object, &["source_type", "sourceType"]).and_then(Value::as_str)),
        "source_url": field(object, &["source_url", "sourceUrl"]).cloned().unwrap_or(Value::Null),
        "copyright_note": field(object, &["copyright_note", "copyrightNote"]).cloned().unwrap_or(Value::Null),
        "created_at": unix_millis().to_string(),
        "archived": false,
    });
    assets.push(asset.clone());
    let usage = append_asset_usage(
        &mut project,
        object,
        asset
            .get("id")
            .and_then(Value::as_str)
            .ok_or("素材缺少 id")?,
    )?;
    if let Err(error) = verify_active_project_lock(&project_dir) {
        return Err(error);
    }
    if let Err(error) = atomic_write_bytes_path(&destination, &bytes) {
        return Err(error);
    }
    if let Err(error) = verify_active_project_lock(&project_dir) {
        let _ = fs::remove_file(&destination);
        return Err(error);
    }
    if let Err(error) = touch_project_updated_at(&mut project) {
        let _ = fs::remove_file(&destination);
        return Err(error);
    }
    let report = match write_project_value_report_unlocked(
        &project_dir,
        &project,
        Some(&current_fingerprint),
    ) {
        Ok(report) => report,
        Err(failure) => {
            let error = project_save_atomic_error_contract(
                &failure,
                mutation_binding
                    .as_ref()
                    .map(|binding| binding.operation_id.as_str()),
                mutation_binding.as_ref().map(|binding| binding.revision),
                Some(&current_fingerprint),
                None,
            );
            if failure.commit_state == "not_committed" {
                let _ = fs::remove_file(&destination);
            }
            return Err(error);
        }
    };
    let mut result = json!({
        "status": "imported",
        "duplicate": false,
        "asset": asset,
        "usage": usage,
        "checksum": checksum,
        "warning": match (report.durability_warning.as_deref(), report.recovery_warning.as_deref()) {
            (Some(left), Some(right)) => Some(format!("{left}；{right}")),
            (Some(value), None) | (None, Some(value)) => Some(value.to_owned()),
            (None, None) => None,
        },
    });
    attach_canonical_mutation_ack(
        &mut result,
        mutation_binding.as_ref(),
        &project,
        &report.fingerprint,
        &project_dir,
        &active_generation,
        "written",
        report.durability_warning.as_deref(),
        report.recovery_warning.as_deref(),
    );
    Ok(result)
}

