    #[test]
    fn ai_complete_rejects_credential_shaped_request_fields() {
        let directory = test_directory("ai-guard");
        let base = ai_test_base(&directory);
        // 词表规则本身：标准采样参数必须可用，凭据字段必须被识别。
        assert!(!sensitive_key("max_tokens"), "max_tokens 是标准模型参数");
        assert!(!sensitive_key("max_completion_tokens"));
        assert!(sensitive_key("api_key"));
        assert!(sensitive_key("requires_credential"));
        assert!(sensitive_key("authorization"));

        // 刻意不给 `AiRequestSpec` 实现 Debug：它持有凭据，测试失败信息也不该打印它。
        let error = match ai_request_spec(
            &base,
            &json!({
                "request_id": "req-guard",
                "provider_id": "deepseek",
                "url": "https://api.deepseek.com/chat/completions",
                "body": {
                    "model": "deepseek-chat",
                    "messages": [{ "role": "user", "content": "hi", "api_key": "sk-must-not-leak" }],
                },
            }),
        ) {
            Ok(_) => panic!("请求体里的凭据字段必须被拦下"),
            Err(error) => error,
        };
        assert!(error.contains("\"invalid_request\""), "got: {error}");
        assert!(
            error.contains("body.messages[0].api_key"),
            "错误必须指明字段路径: {error}"
        );
        assert!(
            !error.contains("sk-must-not-leak"),
            "错误里不得出现字段值: {error}"
        );

        let spec = ai_request_spec(
            &base,
            &json!({
                "request_id": "req-ok",
                "provider_id": "deepseek",
                "url": "https://api.deepseek.com/chat/completions",
                "body": { "model": "m", "messages": [], "max_tokens": 16 },
            }),
        )
        .expect("标准采样参数不得被误伤");
        assert_eq!(spec.timeout_ms, AI_DEFAULT_TIMEOUT_MS);
        assert!(spec.auth_header.is_none());
        assert!(spec.secrets.forms.is_empty(), "没有存过凭据时不带擦除素材");

        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn ai_payloads_accept_both_invoke_shapes() {
        // 服务壳发 `{ "input": { … } }`，桌面壳的 nativeInput 对 AI 命令直接发裸字段，
        // 两种形状都必须能解析出同一份载荷。
        for value in [
            json!({ "request_id": "r1", "provider_id": "deepseek" }),
            json!({ "input": { "request_id": "r1", "provider_id": "deepseek" } }),
        ] {
            let payload = ai_payload(&value, "ai_complete").expect("两种调用形状都必须可解析");
            assert_eq!(payload["request_id"], json!("r1"));
            assert_eq!(payload["provider_id"], json!("deepseek"));
        }
        assert!(ai_payload(&Value::Null, "ai_complete")
            .expect("无参数调用按空载荷处理")
            .is_empty());
        let strict = strict_payload(&json!({ "input": { "provider_id": "p" } }), "ai_secret_set")
            .expect("信封形状必须可解析");
        assert_eq!(strict["provider_id"], json!("p"));
        assert!(
            strict_payload(&json!({ "api_key": "sk-x" }), "ai_secret_set").is_err(),
            "字段固定的命令必须继续做凭据字段扫描"
        );
    }

    #[test]
    fn ai_complete_posts_with_the_injected_credential_and_parses_json() {
        let directory = test_directory("ai-complete-ok");
        let base = ai_test_base(&directory);
        ai_connection_save_at(&base, &json!({ "id": "local", "label": "Local" }))
            .expect("provider should save");
        ai_secret_set_at(&base, "local", "sk-loopback-test-key").expect("secret should save");

        let (result, request) = run_ai_complete_once(
            &base,
            json!({
                "request_id": "req-1",
                "provider_id": "local",
                "auth": { "header": "authorization", "scheme": "Bearer" },
                "headers": {
                    "content-type": "application/json",
                    // 渲染层的内部标记：绝不能发给 Provider。
                    "x-workbench-auth": "provider",
                    "x-workbench-provider": "local",
                },
                "body": { "model": "test", "messages": [{ "role": "user", "content": "你好" }] },
                "timeout_ms": 5000,
            }),
            http_response(
                "200 OK",
                "application/json",
                "{\"choices\":[{\"message\":\"hi\"}]}",
            ),
        );
        let result = result.expect("本机回环请求应当成功");
        assert_eq!(result["status"], json!(200));
        assert_eq!(result["response_kind"], json!("json"));
        assert_eq!(result["body"]["choices"][0]["message"], json!("hi"));
        assert_eq!(result["headers"]["content-type"], json!("application/json"));
        assert!(!result.to_string().contains("sk-loopback-test-key"));

        let lowered = request.to_ascii_lowercase();
        assert!(
            lowered.contains("authorization: bearer sk-loopback-test-key"),
            "本地凭据必须由原生侧注入: {request}"
        );
        assert!(
            lowered.contains("\"model\":\"test\""),
            "请求体必须原样发出: {request}"
        );
        assert!(
            !lowered.contains("x-workbench-"),
            "内部标记不得离开本进程: {request}"
        );
        assert!(lowered.starts_with("post /v1/chat/completions"));

        // 不给 headers 时必须补上 content-type，且不能带任何鉴权头。
        let (plain, plain_request) = run_ai_complete_once(
            &base,
            json!({
                "request_id": "req-2",
                "provider_id": "local",
                "body": { "model": "test" },
                "timeout_ms": 5000,
            }),
            http_response("200 OK", "application/json", "{\"ok\":true}"),
        );
        plain.expect("不带鉴权的请求应当成功");
        let plain_lowered = plain_request.to_ascii_lowercase();
        assert!(
            plain_lowered.contains("content-type: application/json"),
            "缺省请求头必须补 content-type: {plain_request}"
        );
        assert!(
            !plain_lowered.contains("authorization")
                && !plain_lowered.contains("sk-loopback-test-key"),
            "没有 auth 时不得注入凭据: {plain_request}"
        );

        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn ai_complete_skips_auth_for_endpoints_without_a_header() {
        let directory = test_directory("ai-complete-no-auth");
        let base = ai_test_base(&directory);
        ai_connection_save_at(&base, &json!({ "id": "custom-1", "label": "本地端点" }))
            .expect("provider should save");
        // 刻意不保存任何密钥：空 header 的预设不需要密钥，也不得报 missing_credential。
        for auth in [
            json!({ "header": "", "scheme": "Bearer" }),
            json!({ "scheme": "Bearer" }),
            json!(null),
        ] {
            let (result, request) = run_ai_complete_once(
                &base,
                json!({
                    "request_id": "req-no-auth",
                    "provider_id": "custom-1",
                    "auth": auth,
                    "body": { "model": "local" },
                    "timeout_ms": 5000,
                }),
                http_response("200 OK", "application/json", "{\"ok\":true}"),
            );
            result.expect("不需要密钥的端点必须能直接调用");
            assert!(
                !request.to_ascii_lowercase().contains("authorization"),
                "空 header 不得注入鉴权头: {request}"
            );
        }
        let _ = fs::remove_dir_all(directory);
    }

    /// `ai_request_spec` 的失败分支：刻意不打印载荷（里面可能有凭据）。
    fn expect_spec_error(base: &Path, payload: Value) -> String {
        match ai_request_spec(base, &payload) {
            Ok(_) => panic!("该请求形状必须被拒绝"),
            Err(error) => error,
        }
    }

    #[test]
    fn ai_complete_stops_redirects_and_rejects_bad_request_shapes() {
        let directory = test_directory("ai-complete-redirect");
        let base = ai_test_base(&directory);
        ai_connection_save_at(&base, &json!({ "id": "local", "label": "Local" }))
            .expect("provider should save");
        ai_secret_set_at(&base, "local", "sk-redirect-test-key").expect("secret should save");

        // 3xx：不跟随跳转（自定义鉴权头可能被转发到别的站点），直接停在原地。
        let (redirected, _) = run_ai_complete_once(
            &base,
            json!({
                "request_id": "req-redirect",
                "provider_id": "local",
                "auth": { "header": "authorization", "scheme": "Bearer" },
                "body": { "model": "test" },
                "timeout_ms": 5000,
            }),
            http_response("302 Found", "text/plain", ""),
        );
        let redirected = redirected.expect_err("3xx 必须失败");
        assert!(
            redirected.contains("\"provider_error\""),
            "got: {redirected}"
        );
        assert!(redirected.contains("跳转"), "got: {redirected}");
        assert!(!redirected.contains("sk-redirect-test-key"));

        // 请求形状错误：非文本请求头 / 非法头名 / 缺 body / 超时值非法。
        let header_value = expect_spec_error(
            &base,
            json!({ "url": "https://example.com/v1", "headers": { "x-extra": 7 }, "body": {} }),
        );
        assert!(header_value.contains("必须是文本"), "got: {header_value}");
        let header_name = expect_spec_error(
            &base,
            json!({ "url": "https://example.com/v1", "headers": { "bad header": "x" }, "body": {} }),
        );
        assert!(header_name.contains("请求头名称无效"), "got: {header_name}");
        let missing_body = expect_spec_error(&base, json!({ "url": "https://example.com/v1" }));
        assert!(missing_body.contains("缺少 body"), "got: {missing_body}");
        let bad_timeout = expect_spec_error(
            &base,
            json!({ "url": "https://example.com/v1", "body": {}, "timeout_ms": 0 }),
        );
        assert!(bad_timeout.contains("超时时间无效"), "got: {bad_timeout}");
        // 要注入凭据却没给 provider_id：与浏览器壳一致报 not_configured。
        let unconfigured = expect_spec_error(
            &base,
            json!({
                "url": "https://example.com/v1",
                "auth": { "header": "authorization" },
                "body": {},
            }),
        );
        assert!(
            unconfigured.contains("\"not_configured\""),
            "got: {unconfigured}"
        );

        // request_id 缺省时本地补一个，取消依然可用。
        let spec = ai_request_spec(
            &base,
            &json!({ "url": "https://example.com/v1", "body": {} }),
        )
        .expect("request_id 缺省时应当本地补一个");
        assert!(
            spec.request_id.starts_with("ai-request-"),
            "got: {}",
            spec.request_id
        );
        assert_eq!(spec.provider_id, "");
        assert_eq!(spec.timeout_ms, AI_DEFAULT_TIMEOUT_MS);

        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn ai_complete_maps_provider_statuses_and_stream_responses() {
        let directory = test_directory("ai-complete-status");
        let base = ai_test_base(&directory);
        ai_connection_save_at(&base, &json!({ "id": "local", "label": "Local" }))
            .expect("provider should save");
        ai_secret_set_at(&base, "local", "sk-status-test-key").expect("secret should save");
        let payload = || {
            json!({
                "request_id": "req-status",
                "provider_id": "local",
                "auth": { "header": "authorization", "scheme": "Bearer" },
                "headers": { "content-type": "application/json" },
                "body": { "model": "test", "messages": [] },
                "timeout_ms": 5000,
            })
        };

        let (unauthorized, _) = run_ai_complete_once(
            &base,
            payload(),
            http_response(
                "401 Unauthorized",
                "application/json",
                "{\"error\":\"bad key\"}",
            ),
        );
        let unauthorized = unauthorized.expect_err("401 必须失败");
        assert!(
            unauthorized.contains("\"authentication_failed\""),
            "got: {unauthorized}"
        );
        assert!(
            unauthorized.contains("已保存凭据"),
            "401 should explain that the provider rejected the configured authentication"
        );
        assert!(!unauthorized.contains("sk-status-test-key"));

        let (forbidden, _) = run_ai_complete_once(
            &base,
            payload(),
            http_response(
                "403 Forbidden",
                "application/json",
                "{\"error\":\"no access\"}",
            ),
        );
        assert!(forbidden
            .expect_err("403 必须失败")
            .contains("\"permission_denied\""));

        let (limited, _) = run_ai_complete_once(
            &base,
            payload(),
            http_response(
                "429 Too Many Requests",
                "application/json",
                "{\"error\":\"slow down\"}",
            ),
        );
        let limited = limited.expect_err("429 必须失败");
        assert!(limited.contains("\"rate_limited\""), "got: {limited}");
        assert!(limited.contains("slow down"));

        let (failed, _) = run_ai_complete_once(
            &base,
            payload(),
            http_response(
                "500 Internal Server Error",
                "text/plain",
                "upstream exploded",
            ),
        );
        let failed = failed.expect_err("5xx 必须失败");
        assert!(failed.contains("\"provider_error\""), "got: {failed}");
        assert!(failed.contains("\"status\":500"), "got: {failed}");
        assert!(failed.contains("upstream exploded"), "got: {failed}");

        let (stream, _) = run_ai_complete_once(
            &base,
            payload(),
            http_response("200 OK", "text/event-stream", "data: {\"choices\":[]}\n\n"),
        );
        let stream = stream.expect("SSE 响应应当成功");
        assert_eq!(stream["response_kind"], json!("stream"));
        assert_eq!(stream["body"], json!("data: {\"choices\":[]}\n\n"));
        assert_eq!(
            stream["headers"]["content-type"],
            json!("text/event-stream")
        );

        let (malformed, _) = run_ai_complete_once(
            &base,
            payload(),
            http_response("200 OK", "application/json", "<html>not json</html>"),
        );
        let malformed = malformed.expect("非 JSON 正文按原文回传，由前端判定 malformed_response");
        assert_eq!(malformed["response_kind"], json!("json"));
        assert_eq!(malformed["body"], json!("<html>not json</html>"));

        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn ai_cancel_unknown_request_is_a_harmless_no_op() {
        let requests = ai_test_handles();
        let unknown = ai_cancel_at(&requests, &json!({ "request_id": "req-missing" }))
            .expect("取消未知请求不得报错");
        assert_eq!(unknown["cancelled"], json!(false));
        // 与浏览器壳一致：取消永不失败，空 id / 空载荷都只是空操作。
        let blank =
            ai_cancel_at(&requests, &json!({ "request_id": "   " })).expect("空请求 ID 也不得报错");
        assert_eq!(blank["cancelled"], json!(false));
        let empty = ai_cancel_at(&requests, &Value::Null).expect("无参数也不得报错");
        assert_eq!(empty["cancelled"], json!(false));
    }

    #[test]
    fn ai_cancel_aborts_a_registered_handle() {
        let requests = ai_test_handles();
        let handle = tauri::async_runtime::spawn(async {
            thread::sleep(Duration::from_millis(50));
        });
        requests.lock().unwrap().insert("req-sleep".into(), handle);
        let cancelled = ai_cancel_at(&requests, &json!({ "request_id": "req-sleep" }))
            .expect("取消已登记的句柄不得报错");
        assert_eq!(cancelled["cancelled"], json!(true));
        assert!(requests.lock().unwrap().is_empty(), "取消后必须摘掉句柄");
    }

    #[test]
    fn ai_complete_cancel_aborts_an_in_flight_request() {
        let directory = test_directory("ai-complete-cancel");
        let base = ai_test_base(&directory);
        ai_connection_save_at(&base, &json!({ "id": "local", "label": "Local" }))
            .expect("provider should save");
        ai_secret_set_at(&base, "local", "sk-cancel-test-key").expect("secret should save");

        // 只接受 TCP 连接、永不回应 TLS 握手的「服务端」：请求会一直挂在握手上，
        // 于是取消测试不需要任何外部网络，也不会因为网络抖动而不稳定。
        let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("listener should bind");
        listener
            .set_nonblocking(true)
            .expect("listener should be non-blocking");
        let port = listener
            .local_addr()
            .expect("listener should have an address")
            .port();
        ai_connection_save_with_confirmation_at(
            &base,
            &json!({
                "id": "local",
                "base_url": format!("http://127.0.0.1:{port}/v1"),
                "chat_path": "/chat/completions",
            }),
            true,
        )
        .expect("test endpoint should be explicitly configured");
        let stop = Arc::new(AtomicBool::new(false));
        let server_stop = Arc::clone(&stop);
        let server = thread::spawn(move || {
            let mut held = Vec::new();
            while !server_stop.load(Ordering::Acquire) {
                match listener.accept() {
                    Ok((stream, _)) => held.push(stream),
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(5));
                    }
                    Err(_) => break,
                }
            }
            drop(held);
        });

        let requests = Arc::new(ai_test_handles());
        let client_requests = Arc::clone(&requests);
        let client_base = base.clone();
        let (sender, receiver) = std::sync::mpsc::channel();
        let client = thread::spawn(move || {
            let result = tauri::async_runtime::block_on(ai_complete_at(
                &client_base,
                &client_requests,
                &json!({
                    "request_id": "req-cancel",
                    "provider_id": "local",
                    "url": format!("https://127.0.0.1:{port}/v1/chat/completions"),
                    "auth": { "header": "authorization", "scheme": "Bearer" },
                    "headers": { "content-type": "application/json" },
                    "body": { "model": "test", "messages": [] },
                    "timeout_ms": 5000,
                }),
            ));
            let _ = sender.send(result);
        });

        let mut cancelled = false;
        let mut finished_early = None;
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        while std::time::Instant::now() < deadline {
            let outcome = ai_cancel_at(&requests, &json!({ "request_id": "req-cancel" }))
                .expect("取消不得报错");
            if outcome["cancelled"] == json!(true) {
                cancelled = true;
                break;
            }
            if let Ok(result) = receiver.try_recv() {
                finished_early = Some(result);
                break;
            }
            thread::sleep(Duration::from_millis(5));
        }
        assert!(
            cancelled,
            "in-flight 请求必须可取消（提前结束: {finished_early:?}）"
        );

        let result = receiver
            .recv_timeout(Duration::from_secs(5))
            .expect("取消后必须立刻返回");
        let error = result.expect_err("被取消的请求不得报告成功");
        assert!(error.contains("\"cancelled\""), "got: {error}");
        assert!(error.contains("已取消这次 AI 请求"), "got: {error}");
        assert!(!error.contains("sk-cancel-test-key"));

        assert_eq!(
            ai_cancel_at(&requests, &json!({ "request_id": "req-cancel" })).unwrap()["cancelled"],
            json!(false),
            "已经结束的请求再次取消必须是空操作"
        );
        client.join().expect("客户端线程应当结束");
        stop.store(true, Ordering::Release);
        server.join().expect("服务端线程应当结束");
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn ai_protocols_post_to_the_saved_loopback_endpoints_with_protocol_auth() {
        for (index, (protocol, expected_path, header, scheme, response)) in [
            ("openai-completions", "/v1/chat/completions", "authorization", "Bearer", http_response("200 OK", "application/json", "{\"choices\":[{\"message\":{\"content\":\"OK\"}}]}")),
            ("openai-responses", "/v1/responses", "authorization", "Bearer", http_response("200 OK", "text/event-stream", "data: {\"type\":\"response.output_text.delta\",\"delta\":\"OK\"}\n\ndata: [DONE]\n\n")),
            ("anthropic-messages", "/v1/messages", "x-api-key", "", http_response("200 OK", "application/json", "{\"model\":\"test\",\"content\":[{\"type\":\"text\",\"text\":\"OK\"}]}")),
        ].into_iter().enumerate() {
            let directory = test_directory(&format!("ai-protocol-{index}"));
            let base = ai_test_base(&directory);
            let (port, receiver, server) = serve_once(response);
            let provider_id = format!("protocol-{index}");
            let provider = json!({
                "id": provider_id,
                "label": provider_id,
                "kind": "openai_compatible",
                "api_protocol": protocol,
                "base_url": format!("http://127.0.0.1:{port}/v1"),
                "chat_path": "/chat/completions",
                "auth_header": header,
                "auth_scheme": scheme,
                "default_model": "test-model",
            });
            ai_connection_save_at(&base, &provider).expect("protocol provider should save");
            let key = format!("sk-protocol-{index}-test-key-8abcdef");
            ai_secret_set_at(&base, &provider_id, &key).expect("protocol key should save");
            let auth = json!({ "header": "renderer-controlled", "scheme": "wrong" });
            let body = match protocol {
                "openai-responses" => json!({ "model": "test-model", "input": "hello", "store": false, "stream": true }),
                "anthropic-messages" => json!({ "model": "test-model", "messages": [{"role":"user","content":"hello"}], "max_tokens": 8 }),
                _ => json!({ "model": "test-model", "messages": [{"role":"user","content":"hello"}] }),
            };
            let result = tauri::async_runtime::block_on(ai_complete_at(
                &base,
                &ai_test_handles(),
                &json!({
                    "request_id": format!("req-protocol-{index}"),
                    "provider_id": provider_id,
                    "url": "https://attacker.invalid/ignore",
                    "auth": auth,
                    "headers": { "content-type": "application/json" },
                    "body": body,
                    "timeout_ms": 5000,
                }),
            )).expect("protocol request to loopback should succeed");
            assert_eq!(result["status"], json!(200));
            let request = receiver.recv_timeout(Duration::from_secs(5)).expect("local server should receive the request");
            server.join().expect("local server should stop");
            let lowered = request.to_ascii_lowercase();
            assert!(lowered.starts_with(&format!("post {expected_path}")), "wrong saved protocol path: {request}");
            let auth_value = if scheme.is_empty() { key.clone() } else { format!("{scheme} {key}") }.to_ascii_lowercase();
            assert!(lowered.contains(&format!("{header}: {auth_value}")), "saved protocol auth header must be used: {request}");
            assert!(!lowered.contains("attacker.invalid"), "renderer URL must not override the saved endpoint");
            assert!(!request.split_once("\r\n\r\n").map(|(_, body)| body.contains(&key)).unwrap_or(true), "credential must not appear in request body");
            if protocol == "openai-responses" {
                assert!(lowered.contains("accept: text/event-stream"), "Responses must negotiate streaming");
                assert!(request.contains("\"store\":false"), "Responses must disable storage");
            }
            if protocol == "anthropic-messages" {
                assert!(lowered.contains("anthropic-version: 2023-06-01"), "Anthropic must send its version header");
            }
            let _ = fs::remove_dir_all(directory);
        }
    }

    fn siwc_test_account(
        base: &Path,
        provider_id: &str,
        subject: &str,
        access: &str,
        refresh: &str,
        expires_at: u64,
    ) {
        let client_id = format!("client-{provider_id}");
        let claims = SiwcIdClaims {
            iss: SIWC_ISSUER.into(),
            sub: subject.into(),
            aud: json!(client_id),
            exp: unix_seconds() + 3600,
            nonce: Some("test-nonce".into()),
            email: Some(format!("{provider_id}@example.test")),
        };
        let credential = SiwcCredential {
            client_id: client_id.clone(),
            subject: subject.into(),
            email: format!("{provider_id}@example.test"),
            host_id: "urn:uuid:test-host".into(),
            id_token: "test-id-token".into(),
            access_token: access.into(),
            refresh_token: refresh.into(),
            scopes: siwc_scopes(
                "openid profile email offline_access resource.invoke chatgpt.tokens.use.direct",
            ),
            expires_at,
        };
        siwc_save_account(
            base,
            provider_id,
            &client_id,
            "urn:uuid:test-host",
            &claims,
            &credential,
        )
        .expect("synthetic test account should be saved");
    }

    fn serve_once_gated(
        response: String,
    ) -> (
        u16,
        tokio::sync::oneshot::Receiver<String>,
        std::sync::mpsc::Sender<()>,
        thread::JoinHandle<()>,
    ) {
        let listener =
            std::net::TcpListener::bind("127.0.0.1:0").expect("loopback listener should bind");
        let port = listener
            .local_addr()
            .expect("listener should have an address")
            .port();
        let (request_tx, request_rx) = tokio::sync::oneshot::channel();
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        let server = thread::spawn(move || {
            let Ok((mut stream, _)) = listener.accept() else {
                return;
            };
            let _ = stream.set_read_timeout(Some(Duration::from_secs(5)));
            let mut buffer = Vec::new();
            let mut chunk = [0_u8; 4096];
            loop {
                match stream.read(&mut chunk) {
                    Ok(0) => break,
                    Ok(read) => {
                        buffer.extend_from_slice(&chunk[..read]);
                        let text = String::from_utf8_lossy(&buffer);
                        if let Some(position) = text.find("\r\n\r\n") {
                            let length = text[..position]
                                .lines()
                                .find_map(|line| {
                                    let (name, value) = line.split_once(':')?;
                                    name.eq_ignore_ascii_case("content-length")
                                        .then(|| value.trim().parse::<usize>().ok())
                                        .flatten()
                                })
                                .unwrap_or(0);
                            if buffer.len() >= position + 4 + length {
                                break;
                            }
                        }
                    }
                    Err(_) => return,
                }
            }
            let _ = request_tx.send(String::from_utf8_lossy(&buffer).into_owned());
            let _ = release_rx.recv_timeout(Duration::from_secs(5));
            let _ = stream.write_all(response.as_bytes());
        });
        (port, request_rx, release_tx, server)
    }

    #[test]
    fn siwc_refresh_is_deduplicated_and_credentials_are_account_isolated() {
        let directory = test_directory("siwc-refresh-isolation");
        let base = ai_test_base(&directory);
        siwc_test_account(
            &base,
            "chatgpt-account-a",
            "subject-a",
            "old-access-a",
            "refresh-a",
            0,
        );
        siwc_test_account(
            &base,
            "chatgpt-account-b",
            "subject-b",
            "old-access-b",
            "refresh-b",
            0,
        );
        let body_a = r#"{"access_token":"new-access-a","refresh_token":"new-refresh-a","token_type":"Bearer","expires_in":3600,"scope":"openid profile email offline_access resource.invoke chatgpt.tokens.use.direct"}"#;
        let body_b = r#"{"access_token":"new-access-b","refresh_token":"new-refresh-b","token_type":"Bearer","expires_in":3600,"scope":"openid profile email offline_access resource.invoke chatgpt.tokens.use.direct"}"#;
        let (port_a, receiver_a, server_a) =
            serve_once(http_response("200 OK", "application/json", body_a));
        let (port_b, receiver_b, server_b) =
            serve_once(http_response("200 OK", "application/json", body_b));
        let endpoint_a = format!("http://127.0.0.1:{port_a}/token");
        let endpoint_b = format!("http://127.0.0.1:{port_b}/token");
        let result = tauri::async_runtime::block_on(async {
            let (a1, a2, b) = tokio::join!(
                siwc_access_token_with_endpoint(&base, "chatgpt-account-a", &endpoint_a),
                siwc_access_token_with_endpoint(&base, "chatgpt-account-a", &endpoint_a),
                siwc_access_token_with_endpoint(&base, "chatgpt-account-b", &endpoint_b),
            );
            (a1, a2, b)
        });
        assert_eq!(
            result.0.expect("first refresh should succeed"),
            "new-access-a"
        );
        assert_eq!(
            result
                .1
                .expect("coalesced refresh should reuse saved token"),
            "new-access-a"
        );
        assert_eq!(
            result
                .2
                .expect("independent account refresh should succeed"),
            "new-access-b"
        );
        let request_a = receiver_a
            .recv_timeout(Duration::from_secs(5))
            .expect("one request should refresh account A");
        let request_b = receiver_b
            .recv_timeout(Duration::from_secs(5))
            .expect("one request should refresh account B");
        server_a.join().expect("account A server should stop");
        server_b.join().expect("account B server should stop");
        assert!(request_a.starts_with("POST /token"));
        assert!(
            request_a.contains("refresh_token=refresh-a")
                && request_a.contains("client_id=client-chatgpt-account-a")
        );
        assert!(
            request_b.contains("refresh_token=refresh-b")
                && request_b.contains("client_id=client-chatgpt-account-b")
        );
        let stored_a = siwc_parse_credential(
            &ai_keychain_credential(&base, "chatgpt-account-a")
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        let stored_b = siwc_parse_credential(
            &ai_keychain_credential(&base, "chatgpt-account-b")
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(stored_a.refresh_token, "new-refresh-a");
        assert_eq!(stored_b.refresh_token, "new-refresh-b");
        assert_eq!(
            siwc_provider_at(&base, "chatgpt-account-a").unwrap()["siwc_identity"],
            "subject-a"
        );
        assert_eq!(
            siwc_provider_at(&base, "chatgpt-account-b").unwrap()["siwc_identity"],
            "subject-b"
        );
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn siwc_logout_revokes_then_erases_only_the_selected_account() {
        let directory = test_directory("siwc-logout-isolation");
        let base = ai_test_base(&directory);
        siwc_test_account(
            &base,
            "chatgpt-account-a",
            "subject-a",
            "access-a",
            "refresh-a",
            unix_seconds() + 3600,
        );
        siwc_test_account(
            &base,
            "chatgpt-account-b",
            "subject-b",
            "access-b",
            "refresh-b",
            unix_seconds() + 3600,
        );
        let (port, receiver, server) =
            serve_once(http_response("200 OK", "application/json", "{}"));
        let endpoint = format!("http://127.0.0.1:{port}/revoke");
        let result = tauri::async_runtime::block_on(siwc_logout_with_endpoint(
            &base,
            "chatgpt-account-a",
            Some(&endpoint),
        ))
        .expect("logout should clear the local account after revocation");
        assert_eq!(result["remote_revoked"], true);
        assert!(ai_keychain_credential(&base, "chatgpt-account-a")
            .unwrap()
            .is_none());
        assert!(ai_keychain_credential(&base, "chatgpt-account-b")
            .unwrap()
            .is_some());
        let request = receiver
            .recv_timeout(Duration::from_secs(5))
            .expect("revoke request should reach loopback");
        server.join().expect("revocation server should stop");
        assert!(request.starts_with("POST /revoke"));
        assert!(
            request.contains("token=refresh-a")
                && request.contains("client_id=client-chatgpt-account-a")
        );
        assert!(
            !request.contains("access-a"),
            "logout must revoke the refresh token, not send the access token"
        );
        assert_eq!(
            siwc_provider_at(&base, "chatgpt-account-a").unwrap()["kind"],
            SIWC_KIND
        );
        assert!(siwc_cached_access_token_at(&base, "chatgpt-account-a")
            .unwrap_err()
            .contains("missing_credential"));
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn siwc_logout_waits_for_refresh_and_cannot_be_undone_by_it() {
        let directory = test_directory("siwc-logout-refresh-race");
        let base = ai_test_base(&directory);
        siwc_test_account(
            &base,
            "chatgpt-race-account",
            "subject-race",
            "old-access",
            "old-refresh",
            0,
        );
        let refreshed = r#"{"access_token":"rotated-access","refresh_token":"rotated-refresh","token_type":"Bearer","expires_in":3600,"scope":"openid profile email offline_access resource.invoke chatgpt.tokens.use.direct"}"#;
        let (token_port, token_request, release_token, token_server) =
            serve_once_gated(http_response("200 OK", "application/json", refreshed));
        let (revoke_port, revoke_receiver, revoke_server) =
            serve_once(http_response("200 OK", "application/json", "{}"));
        let token_endpoint = format!("http://127.0.0.1:{token_port}/token");
        let revoke_endpoint = format!("http://127.0.0.1:{revoke_port}/revoke");
        let result = tauri::async_runtime::block_on(async {
            let refresh = tokio::spawn({
                let base = base.clone();
                let endpoint = token_endpoint.clone();
                async move {
                    siwc_access_token_with_endpoint(&base, "chatgpt-race-account", &endpoint).await
                }
            });
            let refresh_request = token_request
                .await
                .expect("refresh request should reach gated server");
            let logout = tokio::spawn({
                let base = base.clone();
                let endpoint = revoke_endpoint.clone();
                async move {
                    siwc_logout_with_endpoint(&base, "chatgpt-race-account", Some(&endpoint)).await
                }
            });
            tokio::task::yield_now().await;
            release_token
                .send(())
                .expect("refresh server should be released");
            (
                refresh_request,
                refresh.await.expect("refresh task should finish"),
                logout.await.expect("logout task should finish"),
            )
        });
        assert!(result.0.contains("old-refresh"));
        assert_eq!(
            result.1.expect("refresh completes before queued logout"),
            "rotated-access"
        );
        let logged_out = result.2.expect("logout should complete after refresh");
        assert_eq!(logged_out["logged_out"], true);
        let revoke_request = revoke_receiver
            .recv_timeout(Duration::from_secs(5))
            .expect("rotated credential should be revoked");
        token_server.join().expect("refresh server should stop");
        revoke_server.join().expect("revocation server should stop");
        assert!(
            revoke_request.contains("token=rotated-refresh"),
            "logout must observe the completed rotation"
        );
        assert!(
            ai_keychain_credential(&base, "chatgpt-race-account")
                .unwrap()
                .is_none(),
            "a late refresh must not recreate credentials after logout"
        );
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn siwc_cancel_terminates_callback_and_status_never_contains_credentials() {
        let attempt_id = format!("siwc-test-{}", native_id("cancel"));
        let attempt = Arc::new(Mutex::new(SiwcAttempt {
            view: SiwcAttemptView {
                attempt_id: attempt_id.clone(),
                status: "pending".into(),
                provider_id: None,
                message: Some("waiting".into()),
            },
            cancelled: false,
        }));
        siwc_attempts()
            .lock()
            .unwrap()
            .insert(attempt_id.clone(), attempt.clone());
        let listener = Arc::new(
            std::net::TcpListener::bind("127.0.0.1:0").expect("callback listener should bind"),
        );
        let callback_listener = listener.clone();
        let callback_attempt = attempt.clone();
        let callback = thread::spawn(move || {
            siwc_read_callback(callback_listener.as_ref(), &callback_attempt)
        });
        let status = siwc_status_at(&attempt_id).expect("attempt status should be readable");
        let encoded_status = serde_json::to_string(&status).unwrap();
        assert!(
            !encoded_status.contains("access_token")
                && !encoded_status.contains("authorization_code")
        );
        assert_eq!(siwc_cancel_at(&attempt_id).unwrap()["cancelled"], true);
        assert!(callback
            .join()
            .expect("callback thread should stop")
            .unwrap_err()
            .contains("subscription_cancelled"));
        assert_eq!(siwc_status_at(&attempt_id).unwrap()["status"], "cancelled");
        assert_eq!(
            siwc_cancel_at(&attempt_id).unwrap()["cancelled"],
            false,
            "terminal cancellation should be idempotent"
        );
        siwc_attempts().lock().unwrap().remove(&attempt_id);
    }

