    /// §4.4: a symlinked descendant is never read through, so a selected folder
    /// cannot pull in media that lives outside it.
    #[test]
    fn folder_adopt_directory_media_skips_symlink_escape() {
        let root = test_directory("folder-adopt-directory-media-symlink");
        let outside = test_directory("folder-adopt-directory-media-outside");
        fs::create_dir_all(outside.join("pics")).expect("pics");
        fs::write(outside.join("leak.png"), vec![42_u8]).expect("leak");
        fs::create_dir_all(root.join("course")).expect("course");
        fs::write(root.join("course/keep.png"), vec![7_u8]).expect("png");
        std::os::unix::fs::symlink(outside.join("leak.png"), root.join("course/escape.png"))
            .expect("symlink");
        let result = folder_adopt(
            json!({
                "root": root.to_string_lossy(),
                "confirmed": true,
                "confirmed_at": "2026-01-01T00:00:00.000Z",
                "items": [{
                    "relative_path": "course",
                    "kind": "directory",
                    "suggested": "stage",
                    "mapping": "stage",
                    "selected": true,
                    "is_suggestion": true
                }]
            }),
            None,
            None,
            None,
        )
        .expect("adoption next to a symlink");
        let names: Vec<&str> = result["data"]["assets"]
            .as_array()
            .expect("assets")
            .iter()
            .map(|asset| asset["filename"].as_str().unwrap_or(""))
            .collect();
        assert_eq!(names, vec!["keep.png"]);
        let warnings: Vec<&str> = result["warnings"]
            .as_array()
            .expect("warnings")
            .iter()
            .filter_map(Value::as_str)
            .collect();
        assert!(
            warnings.iter().any(|warning| warning.contains("符号链接")),
            "got: {warnings:?}"
        );
        let _ = project_close(root.to_string_lossy().into_owned());
        let _ = fs::remove_dir_all(root);
        let _ = fs::remove_dir_all(outside);
    }

    /// A descendant the confirmed plan already lists keeps its own row: the sweep
    /// never adds a second decision for the same path.
    #[test]
    fn folder_adopt_directory_media_leaves_listed_paths_alone() {
        let root = test_directory("folder-adopt-directory-media-claimed");
        fs::create_dir_all(root.join("course/deep")).expect("deep");
        fs::write(root.join("course/deep/shot.png"), vec![7_u8, 8, 9]).expect("png");
        fs::write(root.join("course/deep/clip.mp4"), vec![1_u8, 2, 3, 4]).expect("mp4");
        fs::write(root.join("course/deep/notes.md"), "# 不要导入\n").expect("md");
        let result = folder_adopt(
            json!({
                "root": root.to_string_lossy(),
                "confirmed": true,
                "confirmed_at": "2026-01-01T00:00:00.000Z",
                "items": [
                    {
                        "relative_path": "course",
                        "kind": "directory",
                        "suggested": "stage",
                        "mapping": "stage",
                        "selected": true,
                        "is_suggestion": true
                    },
                    {
                        "relative_path": "course/deep/clip.mp4",
                        "kind": "file",
                        "mime": "video/mp4",
                        "size": 4,
                        "suggested": "asset",
                        "mapping": "asset",
                        "selected": true,
                        "is_suggestion": true
                    }
                ]
            }),
            None,
            None,
            None,
        )
        .expect("mixed selection");
        let mut names: Vec<&str> = result["data"]["assets"]
            .as_array()
            .expect("assets")
            .iter()
            .map(|asset| asset["filename"].as_str().unwrap_or(""))
            .collect();
        names.sort_unstable();
        assert_eq!(names, vec!["clip.mp4", "shot.png"]);
        let warnings: Vec<&str> = result["warnings"]
            .as_array()
            .expect("warnings")
            .iter()
            .filter_map(Value::as_str)
            .collect();
        assert!(
            warnings
                .iter()
                .any(|warning| warning.contains("递归收录 1")),
            "got: {warnings:?}"
        );
        let _ = project_close(root.to_string_lossy().into_owned());
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn folder_adopt_reuses_identical_checksum_and_keeps_original_bytes() {
        let root = test_directory("folder-adopt-checksum");
        fs::create_dir_all(root.join("media")).expect("media");
        let bytes_a = vec![10_u8, 20, 30, 40];
        fs::write(root.join("media/shot.png"), &bytes_a).expect("png");
        fs::write(root.join("readme.md"), "# hi\n").expect("md");
        let plan = json!({
            "root": root.to_string_lossy(),
            "confirmed": true,
            "confirmed_at": "2026-01-01T00:00:00.000Z",
            "items": [
                {
                    "relative_path": "media/shot.png",
                    "kind": "file",
                    "mime": "image/png",
                    "size": 4,
                    "suggested": "asset",
                    "mapping": "asset",
                    "selected": true,
                    "is_suggestion": true
                },
                {
                    "relative_path": "readme.md",
                    "kind": "file",
                    "mime": "text/markdown",
                    "size": 4,
                    "suggested": "lesson",
                    "mapping": "lesson",
                    "selected": true,
                    "is_suggestion": true,
                    "parsed_markdown": test_markdown_payload(
                        &root.join("readme.md"),
                        json!([heading_block("# hi\n", "hi", 1)]),
                        json!([]),
                    )
                }
            ]
        });
        let first = folder_adopt(plan, None, None, None).expect("first adopt");
        let first_asset = first["data"]["assets"].as_array().unwrap()[0].clone();
        let first_id = first_asset["id"].as_str().unwrap().to_string();
        let storage = first_asset["storage_path"].as_str().unwrap().to_string();
        let _ = project_close(root.to_string_lossy().into_owned());

        // Second adopt into a sibling folder copy is heavy; instead call the
        // helper against an in-memory project by writing a duplicate file into
        // a fresh folder that also includes the already-managed checksum via
        // a second confirmed plan on a new root that imports two identical files.
        let root2 = test_directory("folder-adopt-checksum-reuse");
        fs::create_dir_all(root2.join("media")).expect("media");
        fs::write(root2.join("media/shot.png"), &bytes_a).expect("png");
        fs::write(root2.join("media/shot-copy.png"), &bytes_a).expect("copy");
        let plan2 = json!({
            "root": root2.to_string_lossy(),
            "confirmed": true,
            "confirmed_at": "2026-01-01T00:00:00.000Z",
            "items": [
                {
                    "relative_path": "media/shot.png",
                    "kind": "file",
                    "mime": "image/png",
                    "size": 4,
                    "suggested": "asset",
                    "mapping": "asset",
                    "selected": true,
                    "is_suggestion": true
                },
                {
                    "relative_path": "media/shot-copy.png",
                    "kind": "file",
                    "mime": "image/png",
                    "size": 4,
                    "suggested": "asset",
                    "mapping": "asset",
                    "selected": true,
                    "is_suggestion": true
                }
            ]
        });
        let second = folder_adopt(plan2, None, None, None).expect("second adopt");
        let reused = second["reused_asset_ids"]
            .as_array()
            .cloned()
            .unwrap_or_default();
        assert!(
            !reused.is_empty() || second["asset_ids"].as_array().map(|v| v.len()).unwrap_or(0) == 1,
            "identical checksum within one adopt must reuse one Asset id"
        );
        let warnings = second["warnings"].as_array().cloned().unwrap_or_default();
        assert!(
            warnings.iter().any(|w| {
                let s = w.as_str().unwrap_or("");
                s.contains("复用") || s.contains("checksum") || s.contains("已存在")
            }),
            "reuse must surface a Chinese warning"
        );
        assert_eq!(
            fs::read(root2.join("media/shot.png")).unwrap(),
            bytes_a,
            "originals unchanged"
        );
        assert_eq!(
            fs::read(root2.join("media/shot-copy.png")).unwrap(),
            bytes_a,
            "duplicate original unchanged"
        );
        let _ = first_id;
        let _ = storage;
        let _ = root;
        let _ = project_close(root2.to_string_lossy().into_owned());
        let _ = fs::remove_dir_all(root);
        let _ = fs::remove_dir_all(root2);
    }

    #[test]
    fn folder_adopt_same_name_different_bytes_gets_distinct_asset_paths() {
        let root = test_directory("folder-adopt-collision");
        fs::create_dir_all(root.join("a")).expect("a");
        fs::create_dir_all(root.join("b")).expect("b");
        let bytes_a = vec![1_u8, 2, 3, 4];
        let bytes_b = vec![1_u8, 2, 3, 99];
        fs::write(root.join("a/shot.png"), &bytes_a).expect("a");
        fs::write(root.join("b/shot.png"), &bytes_b).expect("b");
        let plan = json!({
            "root": root.to_string_lossy(),
            "confirmed": true,
            "confirmed_at": "2026-01-01T00:00:00.000Z",
            "items": [
                {
                    "relative_path": "a/shot.png",
                    "kind": "file",
                    "mime": "image/png",
                    "size": 4,
                    "suggested": "asset",
                    "mapping": "asset",
                    "selected": true,
                    "is_suggestion": true
                },
                {
                    "relative_path": "b/shot.png",
                    "kind": "file",
                    "mime": "image/png",
                    "size": 4,
                    "suggested": "asset",
                    "mapping": "asset",
                    "selected": true,
                    "is_suggestion": true
                }
            ]
        });
        let result = folder_adopt(plan, None, None, None).expect("adopt");
        let assets = result["data"]["assets"]
            .as_array()
            .cloned()
            .unwrap_or_default();
        assert_eq!(assets.len(), 2, "different bytes → two Asset records");
        let paths: Vec<String> = assets
            .iter()
            .filter_map(|asset| asset["storage_path"].as_str().map(str::to_string))
            .collect();
        assert_ne!(paths[0], paths[1], "storage paths must differ");
        assert!(
            paths
                .iter()
                .all(|p| p.starts_with("assets/") && p.contains("-shot.png")),
            "id-prefixed assets/ paths"
        );
        assert_eq!(fs::read(root.join("a/shot.png")).unwrap(), bytes_a);
        assert_eq!(fs::read(root.join("b/shot.png")).unwrap(), bytes_b);
        // Managed copies must keep both byte identities.
        let managed_a = fs::read(root.join(&paths[0])).unwrap();
        let managed_b = fs::read(root.join(&paths[1])).unwrap();
        assert!(managed_a == bytes_a || managed_a == bytes_b);
        assert!(managed_b == bytes_a || managed_b == bytes_b);
        assert_ne!(managed_a, managed_b, "no silent overwrite of managed bytes");
        let _ = project_close(root.to_string_lossy().into_owned());
        let _ = fs::remove_dir_all(root);
    }

